var e=JSON.parse(`[[2501,"Используйте useMemo и useCallback только когда есть измеримая проблема производительности. Они полезны для предотвращения дорогих перерисовок или повторных вычислений, когда зависимые значения не меняются. Не применяйте их по умолчанию — это может ухудшить производительность из-за накладных расходов на мемоизацию. Оценивайте сложность вычислений и частоту ререндеров.","Когда оправдано применение useMemo и useCallback\\nЭти хуки React предназначены для оптимизации производительности, но их использование должно быть обоснованным. Основное правило: применяйте их только тогда, когда вы наблюдаете реальные проблемы с производительностью, такие как частые ререндеры или дорогие вычисления.\\n\\nКритерии для использования\\n\\n- Дорогие вычисления: если функция внутри useMemo выполняет сложные операции (например, сортировка большого массива, фильтрация тысяч элементов), мемоизация может быть полезна.\\n- Стабильные ссылки: useCallback нужен, когда вы передаете колбэк в дочерний компонент, обернутый в React.memo, и хотите избежать его ререндера при неизменных зависимостях.\\n- Измеримая выгода: используйте инструменты профилирования (React DevTools Profiler), чтобы убедиться, что мемоизация действительно сокращает время рендеринга.\\n\\nПример кода\\n\\nКогда не стоит применять\\n\\n- Для простых вычислений (например, сложение чисел) — накладные расходы на мемоизацию превышают выгоду.\\n- Для колбэков, которые передаются в нативные HTML-элементы — они не используют React.memo.\\n- Без профилирования — преждевременная оптимизация может усложнить код без реального прироста.\\n\\nВывод: используйте useMemo и useCallback только после выявления узких мест производительности с помощью профилировщика. Они полезны для дорогих вычислений и стабильных ссылок в компонентах с React.memo, но не должны применяться по умолчанию.","import React, { useMemo, useCallback, useState } from 'react';\\n\\nfunction ExpensiveList({ items, filter }) {\\n  // Дорогая фильтрация — оправдано useMemo\\n  const filteredItems = useMemo(() => {\\n    return items.filter(item => item.name.includes(filter));\\n  }, [items, filter]);\\n\\n  // Простое вычисление — useMemo не нужен\\n  const count = items.length;\\n\\n  return (\\n    <ul>\\n      {filteredItems.map(item => (\\n        <li key={item.id}>{item.name}</li>\\n      ))}\\n    </ul>\\n  );\\n}\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  \\n  // useCallback для стабильной ссылки\\n  const handleClick = useCallback(() => {\\n    setCount(c => c + 1);\\n  }, []);\\n\\n  return (\\n    <div>\\n      <button onClick={handleClick}>{count}</button>\\n      <ExpensiveList items={bigArray} filter=\\"test\\" />\\n    </div>\\n  );\\n}"],[2502,"Для отмены setTimeout внутри хука используйте функцию очистки в useEffect. Сохраните идентификатор таймера, возвращаемый setTimeout, и вызовите clearTimeout в возвращаемой функции. Это гарантирует, что таймер будет отменен при размонтировании компонента или при повторном выполнении эффекта.","Проблема с setTimeout в React\\nПри использовании setTimeout внутри React-компонента возникает риск, что колбэк выполнится после того, как компонент уже размонтирован. Это может привести к утечкам памяти, ошибкам обновления состояния на размонтированном компоненте или неожиданному поведению.\\n\\nРешение с помощью useEffect и cleanup функции\\nReact предоставляет механизм очистки через возврат функции из useEffect. Эта функция вызывается при размонтировании компонента или перед повторным выполнением эффекта. Используйте её для вызова clearTimeout.\\n\\nОбработка зависимостей и сброса состояния\\nЕсли таймер должен перезапускаться при изменении определённых значений, укажите их в массиве зависимостей. При каждом изменении зависимости эффект перезапускается: сначала вызывается cleanup (отменяет старый таймер), затем создаётся новый.\\n\\nВывод\\nВсегда используйте cleanup функцию в useEffect для отмены setTimeout. Это обязательная практика для предотвращения утечек памяти и ошибок в React-приложениях, особенно при работе с асинхронными операциями и таймерами.","import { useEffect, useState } from 'react';\\n\\nfunction TimerComponent() {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const timerId = setTimeout(() => {\\n      setCount(prev => prev + 1);\\n    }, 1000);\\n\\n    // Функция очистки\\n    return () => {\\n      clearTimeout(timerId);\\n    };\\n  }, []); // Пустой массив зависимостей — выполняется один раз\\n\\n  return Count: {count};\\n}\\n\\nuseEffect(() => {\\n  const timerId = setTimeout(() => {\\n    // действие\\n  }, delay);\\n\\n  return () => clearTimeout(timerId);\\n}, [delay]); // перезапуск при изменении delay"],[2503,"Для небольшого одноразового SPA-проекта внедрение строгой архитектуры вроде FSD обычно избыточно. Основная цель архитектуры — поддержка масштабирования и долгосрочной поддерживаемости. Если проект не будет развиваться, можно обойтись минимальной организацией кода. Однако даже в маленьком проекте полезно придерживаться базовых принципов, таких как разделение ответственности, чтобы избежать хаоса.","Зачем нужна архитектура?\\nАрхитектура проекта — это набор соглашений и структурных решений, которые помогают организовать код так, чтобы его было легко понимать, изменять и расширять. Feature-Sliced Design (FSD) — это один из современных подходов для фронтенд-проектов, который предлагает четкое разделение по функциональным модулям (слоям).\\n\\nКогда архитектура обязательна?\\nЕсли проект планируется развивать в течение длительного времени, над ним работает несколько разработчиков, или он будет интегрироваться с другими системами — архитектура необходима. Она снижает технический долг и ускоряет добавление нового функционала.\\n\\nКогда можно обойтись без строгой архитектуры?\\nДля одноразового SPA-проекта, который не будет поддерживаться после сдачи, строгая архитектура вроде FSD может быть излишней. В таком случае достаточно:\\n- Разделить код на логические блоки (например, компоненты, утилиты, API-запросы).\\n- Избегать глобальных переменных и сильной связанности.\\n- Использовать простую структуру папок, например: \`components/\`, \`utils/\`, \`pages/\`.\\n\\nПример минимальной структуры для маленького SPA\\n\\nТакой подход не требует внедрения FSD, но сохраняет читаемость и позволяет быстро найти нужный файл.\\n\\nВывод\\nДля одноразового небольшого SPA-проекта внедрение FSD избыточно. Достаточно базовой организации кода с разделением по папкам. Если проект будет жить дольше или расти — стоит рассмотреть более строгую архитектуру, чтобы избежать проблем с поддержкой.","src/\\n  components/\\n    Header.js\\n    Footer.js\\n  pages/\\n    Home.js\\n    About.js\\n  utils/\\n    api.js\\n    helpers.js\\n  App.js\\n  index.js"],[2504,"Для SPA с авторизацией и одной многошаговой формой state manager не обязателен. Можно использовать локальное состояние компонентов и контекст React для передачи данных между шагами формы. State manager оправдан при сложном взаимодействии множества компонентов, кэшировании данных или синхронизации с сервером. В данном случае он добавит излишнюю сложность без существенной выгоды.","Когда state manager необходим?\\nState manager (например, Redux, MobX, Zustand) решает проблему управления глобальным состоянием в больших приложениях. Он позволяет централизованно хранить данные, доступные из любого компонента, и упрощает отладку и тестирование. Однако его использование оправдано не всегда.\\n\\nАнализ сценария\\nВ описанном сценарии — SPA с авторизацией и одной многошаговой формой — состояние приложения относительно простое. Авторизация обычно хранит токен и информацию о пользователе, а форма — данные, заполняемые на нескольких шагах. Для передачи данных между шагами формы можно использовать локальное состояние родительского компонента или React Context. Это не требует установки дополнительных библиотек и не усложняет архитектуру.\\n\\nПример реализации без state manager\\n\\nКогда стоит использовать state manager\\n\\n- Множество компонентов используют одни и те же данные (например, корзина в интернет-магазине).\\n- Сложная логика синхронизации с сервером (кэширование, optimistic updates).\\n- Необходимость в инструментах отладки (Redux DevTools).\\n\\nВывод\\nДля простых SPA с ограниченным количеством состояний использование state manager избыточно. Локальное состояние и контекст React — более легковесное и понятное решение. State manager стоит внедрять только когда приложение разрастается и появляется реальная потребность в централизованном управлении состоянием.","// Компонент формы с многошаговостью\\nfunction MultiStepForm() {\\n  const [step, setStep] = useState(1);\\n  const [formData, setFormData] = useState({});\\n\\n  const handleNext = (data) => {\\n    setFormData(prev => ({ ...prev, ...data }));\\n    setStep(step + 1);\\n  };\\n\\n  return (\\n    <AuthContext.Provider value={{ token }}>\\n      {step === 1 && <Step1 onNext={handleNext} />}\\n      {step === 2 && <Step2 onNext={handleNext} />}\\n      {step === 3 && <Step3 data={formData} />}\\n    </AuthContext.Provider>\\n  );\\n}"],[2505,"Для хранения промежуточного состояния многошаговой формы можно использовать локальный state компонента, useReducer или Context API. Локальный state подходит для простых форм, useReducer — для сложной логики, а Context API — для доступа к данным из разных компонентов. Также можно использовать Redux или библиотеки вроде Formik и React Hook Form.","Основные подходы к хранению состояния многошаговой формы\\nПри разработке многошаговых форм на фронтенде важно сохранять данные между шагами, чтобы пользователь мог вернуться назад или продолжить позже. Существует несколько способов организации такого хранения, каждый из которых подходит для разных сценариев.\\n\\nЛокальный state компонента\\nСамый простой способ — хранить все данные формы в одном объекте внутри компонента, который управляет шагами. Это удобно для небольших форм с 2-3 шагами.\\n\\nuseReducer для сложной логики\\nЕсли форма имеет много полей и сложные правила валидации, лучше использовать useReducer. Это позволяет централизованно обрабатывать изменения и упрощает тестирование.\\n\\nContext API для глобального доступа\\nКогда форма разбита на отдельные компоненты для каждого шага, удобно использовать Context API, чтобы избежать prop drilling. Создаётся контекст, который предоставляет данные формы и функции для их обновления всем дочерним компонентам.\\n\\nВывод\\nВыбор метода зависит от сложности формы и архитектуры приложения. Для простых форм достаточно локального state, для средних — useReducer, а для крупных проектов с множеством шагов и компонентов — Context API или Redux. Это обеспечивает удобство разработки и поддержки кода.","import React, { useState } from 'react';\\n\\nfunction MultiStepForm() {\\n  const [step, setStep] = useState(1);\\n  const [formData, setFormData] = useState({\\n    name: '',\\n    email: '',\\n    address: ''\\n  });\\n\\n  const updateField = (field, value) => {\\n    setFormData(prev => ({ ...prev, [field]: value }));\\n  };\\n\\n  // Рендер шагов в зависимости от step\\n}\\n\\nconst initialState = { name: '', email: '', address: '' };\\n\\nfunction formReducer(state, action) {\\n  switch (action.type) {\\n    case 'UPDATE_FIELD':\\n      return { ...state, [action.field]: action.value };\\n    case 'RESET':\\n      return initialState;\\n    default:\\n      return state;\\n  }\\n}\\n\\nfunction MultiStepForm() {\\n  const [formData, dispatch] = useReducer(formReducer, initialState);\\n}\\n\\nconst FormContext = React.createContext();\\n\\nfunction FormProvider({ children }) {\\n  const [formData, setFormData] = useState({});\\n  return (\\n    <FormContext.Provider value={{ formData, setFormData }}>\\n      {children}\\n    </FormContext.Provider>\\n  );\\n}"],[2506,"Для небольшого React-проекта с корпоративными стандартами лучше всего использовать Webpack, так как он является наиболее гибким и настраиваемым сборщиком. Он поддерживает React из коробки через Babel и позволяет легко интегрировать любые плагины и лоадеры. Если в компании уже есть готовые конфигурации или шаблоны, Webpack обеспечит их совместимость. Альтернативы вроде Vite или Parcel могут быть проще, но могут не соответствовать внутренним стандартам.","Выбор сборщика для React-проекта\\nПри выборе сборщика для небольшого React-проекта в условиях корпоративных стандартов ключевым фактором становится совместимость с существующей инфраструктурой. Webpack является де-факто стандартом в крупных компаниях благодаря своей гибкости и широкой экосистеме плагинов. Он позволяет точно настроить процесс сборки под любые требования, включая оптимизацию, разделение кода и поддержку устаревших браузеров.\\n\\nПрактический пример конфигурации Webpack для React\\n\\nПочему Webpack, а не альтернативы\\n\\n- Совместимость со стандартами: Webpack легко адаптируется под существующие корпоративные конфигурации, ESLint, Prettier и другие инструменты.\\n- Гибкость: Возможность тонкой настройки через лоадеры и плагины для работы с TypeScript, CSS Modules, изображениями и шрифтами.\\n- Производительность: Встроенные оптимизации, такие как tree shaking и code splitting, критичны для production-сборок.\\n\\nХотя Vite предлагает более быструю разработку за счет ESM, он может не поддерживать специфические корпоративные плагины или требовать дополнительной настройки для совместимости. Parcel, в свою очередь, слишком автоматизирован и не дает достаточного контроля.\\n\\nВывод\\nДля небольшого React-проекта в компании с устоявшимися стандартами Webpack остается оптимальным выбором благодаря своей гибкости, зрелости и совместимости с существующими инструментами. Он обеспечивает полный контроль над сборкой и легко интегрируется в любую корпоративную среду.","// webpack.config.js\\nconst path = require('path');\\nconst HtmlWebpackPlugin = require('html-webpack-plugin');\\n\\nmodule.exports = {\\n  entry: './src/index.js',\\n  output: {\\n    path: path.resolve(__dirname, 'dist'),\\n    filename: 'bundle.js',\\n  },\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\\\".jsx?$/,\\n        exclude: /node_modules/,\\n        use: {\\n          loader: 'babel-loader',\\n          options: {\\n            presets: ['@babel/preset-env', '@babel/preset-react'],\\n          },\\n        },\\n      },\\n      {\\n        test: /\\\\\\".css$/,\\n        use: ['style-loader', 'css-loader'],\\n      },\\n    ],\\n  },\\n  plugins: [\\n    new HtmlWebpackPlugin({\\n      template: './public/index.html',\\n    }),\\n  ],\\n  resolve: {\\n    extensions: ['.js', '.jsx'],\\n  },\\n};"],[2507,"React использует алгоритм сравнения (diffing) для обновления DOM. При изменении списка React сравнивает старый и новый виртуальные DOM-деревья. Ключи (keys) помогают React идентифицировать элементы и минимизировать перерисовку. Без ключей React может пересоздать все элементы списка.","Как работает реконсиляция списков в React\\nКогда React обновляет список элементов, он использует алгоритм реконсиляции (reconciliation), который сравнивает виртуальные DOM-деревья до и после изменения. Этот процесс основан на двух предположениях: элементы разных типов создают разные деревья, а ключи (keys) позволяют React идентифицировать элементы между рендерами.\\n\\nРоль ключей\\nКлючи — это уникальные идентификаторы, которые помогают React понять, какой элемент был добавлен, удален или перемещен. Без ключей React будет сравнивать элементы по индексу, что может привести к неправильному обновлению DOM и потере состояния компонентов.\\n\\nАлгоритм сравнения\\nReact использует алгоритм O(n), который проходит по списку и сравнивает элементы по ключам. Если ключи совпадают, React обновляет только измененные атрибуты. Если ключ изменился, React удаляет старый элемент и создает новый. Это позволяет эффективно обновлять DOM без полной перерисовки.\\n\\nВывод\\nИспользование стабильных и уникальных ключей в списках React критически важно для производительности и корректного обновления DOM. Это особенно полезно при работе с динамическими списками, где элементы могут добавляться, удаляться или переставляться местами.","// Пример с ключами\\nconst items = ['a', 'b', 'c'];\\nreturn (\\n  <ul>\\n    {items.map((item, index) => (\\n      <li key={item}>{item}</li>\\n    ))}\\n  </ul>\\n);\\n\\n// Без ключей React может пересоздать все элементы\\n{items.map((item, index) => (\\n  <li>{item}</li>\\n))}"],[2508,"React использует ключи для идентификации элементов в массиве. Если ключи не указаны, React использует индекс элемента. При переключении между разными массивами данных React может повторно использовать существующие DOM-узлы, если их индексы совпадают, что приводит к сохранению состояния компонентов. Это происходит из-за того, что React не пересоздает компонент, а обновляет его пропсы.","Почему без явных ключей компоненты сохраняют состояние?\\nКогда вы рендерите список компонентов без указания явных ключей, React использует индекс элемента в массиве в качестве ключа по умолчанию. Это может привести к неожиданному поведению при переключении между разными массивами данных.\\n\\nМеханизм согласования (Reconciliation)\\nReact сравнивает виртуальные DOM-деревья с помощью алгоритма сравнения. Если ключи элементов совпадают, React считает, что это один и тот же элемент, и обновляет только его пропсы, сохраняя состояние компонента.\\n\\nПример проблемы\\n\\nВ этом примере при нажатии на кнопку React повторно использует существующие компоненты InputComponent, потому что их индексы (0 и 1) совпадают. Состояние внутри компонентов (например, введенный текст) сохранится, хотя данные полностью изменились.\\n\\nПравильное решение\\nВсегда используйте уникальные и стабильные ключи, например, идентификаторы из базы данных:\\n\\nВывод\\nЯвные ключи необходимы для корректной работы React при рендеринге списков. Они помогают избежать ошибок с сохранением состояния и обеспечивают правильное обновление компонентов при изменении данных.","function App() {\\n  const [items, setItems] = useState([{id: 1, text: 'A'}, {id: 2, text: 'B'}]);\\n  \\n  return (\\n    <div>\\n      {items.map((item, index) => (\\n        <InputComponent key={index} value={item.text} />\\n      ))}\\n      <button onClick={() => setItems([{id: 3, text: 'C'}, {id: 4, text: 'D'}])}>\\n        Сменить данные\\n      </button>\\n    </div>\\n  );\\n}\\n\\n{items.map(item => (\\n  <InputComponent key={item.id} value={item.text} />\\n))}"],[2509,"React Testing Library фокусируется на тестировании поведения компонентов с точки зрения пользователя, работая с реальным DOM. Enzyme предоставляет доступ к внутреннему состоянию и методам компонентов, что ведет к тестированию деталей реализации. RTL поощряет тесты, устойчивые к рефакторингу, в то время как Enzyme делает их хрупкими.","Философия тестирования\\nReact Testing Library (RTL) и Enzyme представляют два разных подхода к тестированию React-компонентов. RTL следует принципу: \\"Чем больше ваши тесты похожи на то, как ваше приложение используется, тем больше уверенности они могут вам дать\\". Enzyme же предоставляет более низкоуровневый доступ к внутренностям компонента.\\n\\nКлючевые различия\\n\\n- Подход к поиску элементов: RTL использует запросы, основанные на доступности (getByRole, getByText, getByLabelText), имитируя действия пользователя. Enzyme использует селекторы (find('.class'), find(Component)).\\n- Доступ к состоянию: RTL не предоставляет прямого доступа к состоянию или пропсам компонента. Enzyme позволяет вызывать .state(), .props(), .instance().\\n- Тестирование деталей реализации: RTL активно discourages тестирование внутренних методов и состояний. Enzyme это поощряет.\\n\\nПример кода\\n\\nВ примере RTL проверяет, что пользователь видит '1' после клика. Enzyme проверяет внутреннее состояние count.\\n\\nВывод\\nReact Testing Library предпочтительнее для создания надежных тестов, которые не ломаются при рефакторинге. Enzyme может быть полезен для быстрого прототипирования тестов, но его использование часто приводит к хрупким тестам, привязанным к реализации.","// React Testing Library\\nimport { render, screen, fireEvent } from '@testing-library/react';\\nimport Counter from './Counter';\\n\\ntest('increments counter', () => {\\n  render(<Counter />);\\n  const button = screen.getByRole('button', { name: /increment/i });\\n  fireEvent.click(button);\\n  expect(screen.getByText('1')).toBeInTheDocument();\\n});\\n\\n// Enzyme\\nimport { shallow } from 'enzyme';\\nimport Counter from './Counter';\\n\\ntest('increments counter', () => {\\n  const wrapper = shallow(<Counter />);\\n  wrapper.find('button').simulate('click');\\n  expect(wrapper.state('count')).toBe(1);\\n});"],[2510,"Для оптимизации компонента, подвешивающего страницу при загрузке больших данных, используйте виртуализацию списка (например, react-window), ленивую загрузку (React.lazy), мемоизацию (React.memo, useMemo, useCallback) и пагинацию. Также можно разбить рендеринг на части с помощью requestAnimationFrame или Web Workers.","Проблема и её причины\\nКогда React-компонент обрабатывает и рендерит большой объём данных (например, список из тысяч элементов), браузер может зависнуть из-за блокировки основного потока. Это происходит, потому что React синхронно выполняет рендеринг, а браузер не может обновлять интерфейс до завершения работы JavaScript.\\n\\nОсновные подходы к оптимизации\\n\\n- Виртуализация списка — рендерит только видимые элементы, используя библиотеки вроде react-window или react-virtualized.\\n- Ленивая загрузка — разбивает код на чанки с помощью React.lazy и Suspense.\\n- Мемоизация — предотвращает повторные вычисления с помощью React.memo, useMemo и useCallback.\\n- Пагинация — загружает данные порциями по запросу пользователя.\\n- Разбиение рендеринга — использует requestAnimationFrame или setTimeout для распределения работы по кадрам.\\n\\nПример с виртуализацией\\n\\nПример с мемоизацией\\n\\nВывод\\nПрименяйте виртуализацию для списков с тысячами элементов, мемоизацию для предотвращения лишних перерисовок, а ленивую загрузку — для уменьшения начального бандла. Эти техники критичны для создания отзывчивых интерфейсов с большими данными.","import { FixedSizeList as List } from 'react-window';\\n\\nconst Row = ({ index, style }) => (\\n  <div style={style}>Элемент {index}</div>\\n);\\n\\nconst BigList = ({ items }) => (\\n  <List\\n    height={400}\\n    itemCount={items.length}\\n    itemSize={35}\\n    width={300}\\n  >\\n    {Row}\\n  </List>\\n);\\n\\nconst ExpensiveComponent = React.memo(({ data }) => {\\n  // Тяжёлые вычисления\\n  return <div>{data}</div>;\\n});\\n\\nconst Parent = ({ items }) => {\\n  const processed = useMemo(() => items.map(process), [items]);\\n  return processed.map(item => <ExpensiveComponent key={item.id} data={item} />);\\n};"],[2511,"Проблема overflow возникает, когда выпадающий список выходит за границы родительского контейнера. Решить её можно с помощью CSS-свойства overflow: visible на родителе, использования порталов React (ReactDOM.createPortal) для рендеринга списка вне контейнера, или применения библиотек типа Popper.js для динамического позиционирования. Также помогает установка z-index и проверка границ экрана.","Понимание проблемы overflow\\nКогда выпадающий список отображается внутри контейнера с ограниченной высотой или свойством overflow: hidden, его содержимое может обрезаться. Это часто встречается в модальных окнах, боковых панелях или компонентах с фиксированной высотой. Проблема усугубляется, если список должен появляться за пределами родительского элемента.\\n\\nОсновные подходы к решению\\n\\n- CSS-решение: Установить родительскому контейнеру overflow: visible, если это не нарушает дизайн. Однако это может сломать скролл или макет.\\n- React Portals: Использовать ReactDOM.createPortal для рендеринга выпадающего списка в отдельном узле DOM (например, в body). Это гарантирует, что список не будет ограничен родительскими стилями.\\n- Библиотеки позиционирования: Popper.js или Floating UI автоматически вычисляют оптимальное положение списка, избегая выхода за границы экрана и overflow.\\n\\nПример с порталом\\n\\nВ этом примере список рендерится в body, поэтому overflow родителя не влияет на него. Важно также управлять z-index и закрытием при клике вне списка.\\n\\nПример с Popper.js\\n\\nPopper.js автоматически подстраивает положение, чтобы список не выходил за пределы видимой области.\\n\\nВывод\\nДля решения overflow в выпадающих списках используйте порталы, если нужно полностью избавиться от ограничений родителя, или библиотеки позиционирования для динамической адаптации. CSS-решения подходят только для простых случаев без глубокой вложенности.","import ReactDOM from 'react-dom';\\n\\nfunction Dropdown({ isOpen, children }) {\\n  if (!isOpen) return null;\\n  return ReactDOM.createPortal(\\n    <div className=\\"dropdown-menu\\">{children}</div>,\\n    document.body\\n  );\\n}\\n\\nimport { usePopper } from 'react-popper';\\n\\nfunction Dropdown({ referenceElement }) {\\n  const [popperElement, setPopperElement] = useState(null);\\n  const { styles, attributes } = usePopper(referenceElement, popperElement);\\n\\n  return (\\n    <div ref={setPopperElement} style={styles.popper} {...attributes.popper}>\\n      Содержимое списка\\n    </div>\\n  );\\n}"],[2512,"Производительность drag-and-drop может деградировать со временем из-за накопления неотменённых обработчиков событий, особенно при повторных перетаскиваниях. Если обработчики не удаляются после завершения перетаскивания, они продолжают висеть в памяти и вызываться, замедляя работу. Также возможны утечки памяти из-за создания новых DOM-элементов без их очистки.","Почему производительность drag-and-drop падает постепенно?\\nПроблема часто связана с тем, как разработчики реализуют механизм перетаскивания. При каждом новом цикле drag-and-drop (mousedown -> mousemove -> mouseup) могут добавляться новые обработчики событий, но не удаляться старые. Со временем количество активных слушателей растёт, и браузер тратит всё больше ресурсов на их вызов, даже когда перетаскивание не активно.\\n\\nОсновные причины деградации\\n\\n- Накопление обработчиков: Если при каждом mousedown добавлять обработчики mousemove и mouseup, но не удалять их после mouseup, они остаются в памяти.\\n- Утечки памяти: Создание временных DOM-элементов (например, клонов перетаскиваемого объекта) без последующего удаления приводит к росту потребления памяти.\\n- Неоптимизированные вычисления: Постоянный пересчёт позиций элементов или вызов дорогих функций (например, getBoundingClientRect) на каждом mousemove без кэширования.\\n\\nПример проблемы и решения\\n\\nВывод\\nДля предотвращения деградации производительности drag-and-drop всегда удаляйте временные обработчики событий после завершения перетаскивания, используйте requestAnimationFrame для оптимизации частоты обновлений и избегайте создания лишних DOM-элементов без очистки. Это особенно важно в приложениях с длительной сессией пользователя.","// Проблемный код: обработчики не удаляются\\nlet dragItem = document.getElementById('drag');\\ndragItem.addEventListener('mousedown', function(e) {\\n  function onMouseMove(e) {\\n    // дорогие вычисления\\n    dragItem.style.left = e.clientX + 'px';\\n  }\\n  function onMouseUp() {\\n    document.removeEventListener('mousemove', onMouseMove);\\n    document.removeEventListener('mouseup', onMouseUp);\\n  }\\n  document.addEventListener('mousemove', onMouseMove);\\n  document.addEventListener('mouseup', onMouseUp);\\n});\\n\\n// Исправленный код: удаление обработчиков после завершения\\ndragItem.addEventListener('mousedown', function(e) {\\n  const onMouseMove = (e) => {\\n    requestAnimationFrame(() => {\\n      dragItem.style.left = e.clientX + 'px';\\n    });\\n  };\\n  const onMouseUp = () => {\\n    document.removeEventListener('mousemove', onMouseMove);\\n    document.removeEventListener('mouseup', onMouseUp);\\n  };\\n  document.addEventListener('mousemove', onMouseMove);\\n  document.addEventListener('mouseup', onMouseUp);\\n});"],[2513,"Использование top/left вызывает перерасчёт layout (reflow) при каждом изменении, что снижает производительность. styled-components генерирует новые CSS-классы при каждом обновлении стилей, что усугубляет проблему. Рекомендуется использовать CSS-свойство transform: translate() для перемещения элементов, так как оно работает на уровне compositing и не вызывает reflow.","Проблема использования top/left с styled-components в drag-and-drop\\nПри реализации drag-and-drop часто возникает соблазн изменять позицию элемента через CSS-свойства \`top\` и \`left\`. Однако такой подход имеет серьёзные недостатки, особенно в сочетании с библиотекой styled-components.\\n\\nПочему top/left — плохой выбор\\nСвойства \`top\` и \`left\` относятся к геометрии элемента и влияют на layout страницы. При каждом их изменении браузер выполняет перерасчёт позиций всех элементов (reflow), что является дорогой операцией. В контексте drag-and-drop, где позиция меняется десятки раз в секунду, это приводит к заметным тормозам интерфейса.\\n\\nОсобенности styled-components\\nstyled-components динамически генерирует CSS-классы. Когда вы передаёте изменяющиеся значения в стили, библиотека создаёт новый класс при каждом рендере. Это дополнительно нагружает React и браузер, так как приходится пересоздавать стили и применять их к DOM.\\n\\nПример проблемного кода\\n\\nКаждое движение мыши вызывает ререндер и создание нового CSS-класса.\\n\\nПравильное решение: transform\\nСвойство \`transform: translate(x, y)\` работает на уровне compositing — браузер перемещает элемент без перерасчёта layout. Это значительно быстрее. Кроме того, transform не требует создания новых CSS-классов, поэтому styled-components не будет пересоздавать стили.\\n\\nИсправленный пример\\n\\nТеперь изменения позиции происходят плавно, без лишних перерасчётов.\\n\\nВывод\\nИспользуйте \`transform: translate()\` для анимаций и перемещений элементов, особенно в drag-and-drop. Это обеспечивает высокую производительность и избегает проблем с динамическими стилями в styled-components.","const Draggable = styled.div\`\\n  position: absolute;\\n  top: \${props => props.y}px;\\n  left: \${props => props.x}px;\\n\`;\\n\\nfunction Component() {\\n  const [pos, setPos] = useState({x: 0, y: 0});\\n  \\n  const handleMouseMove = (e) => {\\n    setPos({x: e.clientX, y: e.clientY});\\n  };\\n  \\n  return <Draggable x={pos.x} y={pos.y} />;\\n}\\n\\nconst Draggable = styled.div\`\\n  position: absolute;\\n  transform: translate(\${props => props.x}px, \${props => props.y}px);\\n\`;\\n\\nfunction Component() {\\n  const [pos, setPos] = useState({x: 0, y: 0});\\n  \\n  const handleMouseMove = (e) => {\\n    setPos({x: e.clientX, y: e.clientY});\\n  };\\n  \\n  return <Draggable x={pos.x} y={pos.y} />;\\n}"],[2514,"Паттерн «Фабрика» во фронтенде применяется, когда нужно создавать объекты (компоненты, классы) с общей структурой, но разными деталями. Например, для генерации модальных окон, кнопок или элементов форм в зависимости от типа. Это упрощает код и делает его более гибким.","Что такое паттерн «Фабрика»?\\nПаттерн «Фабрика» (Factory) — это порождающий шаблон проектирования, который предоставляет интерфейс для создания объектов в суперклассе, но позволяет подклассам изменять тип создаваемых объектов. Во фронтенд-разработке он особенно полезен, когда необходимо создавать множество однотипных элементов с разными конфигурациями.\\n\\nГде применять во фронтенде?\\n\\n- Создание UI-компонентов (кнопки, модальные окна, карточки) на основе переданного типа.\\n- Генерация элементов формы (input, select, checkbox) по конфигурации.\\n- Создание объектов для работы с API (разные адаптеры для разных версий).\\n\\nПример на JavaScript\\n\\nВывод\\nПаттерн «Фабрика» стоит применять, когда код часто создаёт объекты с похожей логикой, но разными параметрами. Это уменьшает дублирование и упрощает добавление новых типов объектов.","class ButtonFactory {\\n  createButton(type) {\\n    switch (type) {\\n      case 'primary':\\n        return new PrimaryButton();\\n      case 'secondary':\\n        return new SecondaryButton();\\n      default:\\n        return new DefaultButton();\\n    }\\n  }\\n}\\n\\nclass PrimaryButton {\\n  render() { return '<button class=\\"primary\\">OK</button>'; }\\n}\\n\\nconst factory = new ButtonFactory();\\nconst btn = factory.createButton('primary');\\nconsole.log(btn.render()); // <button class=\\"primary\\">OK</button>"],[2515,"Состояние загрузки при асинхронной валидации обычно добавляется на уровне поля или формы. Используйте флаг isLoading, который устанавливается в true перед началом запроса и в false после его завершения. Лоадер отображается рядом с полем ввода, чтобы пользователь понимал, что идет проверка. Важно блокировать отправку формы до завершения валидации и обрабатывать ошибки.","Концепция асинхронной валидации с лоадером\\nАсинхронная валидация выполняется, когда нужно проверить данные на сервере, например, уникальность имени пользователя. В это время пользователь должен видеть индикатор загрузки, чтобы понимать, что система работает. Лоадер обычно размещается рядом с полем ввода или внутри кнопки отправки.\\n\\nГде добавлять состояние загрузки\\n\\n- На уровне поля: флаг isLoading для каждого поля, которое требует асинхронной проверки.\\n- На уровне формы: общий флаг isSubmitting для всей формы, когда отправка данных требует валидации.\\n\\nКак правильно реализовать\\nИспользуйте состояние компонента (например, useState в React) для хранения флага загрузки. Установите его в true перед вызовом асинхронной функции и в false после получения ответа. Отобразите спиннер или текст \\"Проверка...\\" рядом с полем. Пример на React:\\n\\nВывод\\nДобавление лоадера при асинхронной валидации улучшает пользовательский опыт, предотвращает повторные отправки и информирует о процессе. Применяйте этот подход в формах регистрации, входа или любых других, где требуется проверка на сервере.","const [isLoading, setIsLoading] = useState(false);\\nconst [error, setError] = useState(null);\\n\\nconst validateUsername = async (value) => {\\n  setIsLoading(true);\\n  setError(null);\\n  try {\\n    const response = await fetch('/api/check-username', { method: 'POST', body: JSON.stringify({ username: value }) });\\n    if (!response.ok) throw new Error('Username taken');\\n  } catch (err) {\\n    setError(err.message);\\n  } finally {\\n    setIsLoading(false);\\n  }\\n};"],[2516,"Паттерн Observer используется, когда один объект (субъект) уведомляет множество зависимых объектов (наблюдателей) об изменениях своего состояния. Например, в интерфейсе пользователя при изменении данных модели автоматически обновляются все связанные представления. Это реализует слабую связанность и упрощает поддержку кода.","Что такое паттерн Observer?\\nПаттерн Observer (наблюдатель) — это поведенческий шаблон проектирования, который определяет зависимость типа \\"один ко многим\\" между объектами. Когда один объект (субъект) изменяет своё состояние, все зависимые объекты (наблюдатели) автоматически уведомляются и обновляются. Это позволяет избежать тесной связанности и упрощает расширение системы.\\n\\nГде применяется в реальных приложениях?\\nОдин из самых распространённых примеров — системы событий в пользовательских интерфейсах. Например, в веб-приложении на JavaScript при изменении данных в модели (например, списка задач) все компоненты, отображающие эти данные (например, таблица и счётчик), должны обновиться. Паттерн Observer позволяет подписать эти компоненты на изменения модели и автоматически реагировать.\\n\\nПример кода на JavaScript\\n\\nВывод\\nПаттерн Observer полезен в системах, где требуется автоматическое уведомление множества компонентов об изменениях, например, в UI-фреймворках (React, Vue), системах событий или при реализации pub/sub моделей. Он улучшает модульность и упрощает поддержку кода.","class Subject {\\n  constructor() {\\n    this.observers = [];\\n  }\\n  subscribe(observer) {\\n    this.observers.push(observer);\\n  }\\n  unsubscribe(observer) {\\n    this.observers = this.observers.filter(obs => obs !== observer);\\n  }\\n  notify(data) {\\n    this.observers.forEach(observer => observer.update(data));\\n  }\\n}\\n\\nclass Observer {\\n  constructor(name) {\\n    this.name = name;\\n  }\\n  update(data) {\\n    console.log(\`\${this.name} получил данные: \${data}\`);\\n  }\\n}\\n\\nconst subject = new Subject();\\nconst observer1 = new Observer('Наблюдатель 1');\\nconst observer2 = new Observer('Наблюдатель 2');\\n\\nsubject.subscribe(observer1);\\nsubject.subscribe(observer2);\\nsubject.notify('Новое сообщение');\\n// Вывод: Наблюдатель 1 получил данные: Новое сообщение\\n//        Наблюдатель 2 получил данные: Новое сообщение"],[2517,"Лучше показывать страницу частично, используя скелетоны или индикаторы загрузки для отдельных блоков. Это улучшает восприятие скорости и позволяет пользователю взаимодействовать с уже загруженными частями. Полное ожидание всех данных ухудшает UX и может привести к потере пользователей.","Проблема\\nКогда часть данных на странице зависит от медленного внешнего сервиса, возникает дилемма: ждать полной загрузки или показывать частичный контент. Ожидание всех данных блокирует рендеринг и ухудшает пользовательский опыт, особенно на мобильных устройствах или при нестабильном соединении.\\n\\nРешение: частичная загрузка\\nСовременный подход — показывать страницу сразу с доступными данными, а для медленных блоков отображать скелетоны (серые прямоугольники, имитирующие структуру контента) или спиннеры. Это называется асинхронным рендерингом с постепенным улучшением.\\n\\nПример реализации на React\\n\\nКогда применять\\n\\n- Если данные независимы — показывайте их сразу.\\n- Если данные критичны для навигации (например, меню) — можно показать скелетон, но не блокировать всю страницу.\\n- Для SEO и SSR может потребоваться ожидание, но с использованием потоковой передачи (streaming).\\n\\nВывод: частичная загрузка с визуальной обратной связью (скелетоны, спиннеры) предпочтительнее полного ожидания, так как улучшает восприятие производительности и удерживает пользователя на странице.","import React, { useState, useEffect } from 'react';\\n\\nfunction UserProfile({ userId }) {\\n  const [user, setUser] = useState(null);\\n  const [orders, setOrders] = useState(null);\\n\\n  useEffect(() => {\\n    fetch(\`/api/users/\${userId}\`)\\n      .then(res => res.json())\\n      .then(setUser);\\n    fetch(\`/api/orders/\${userId}\`)\\n      .then(res => res.json())\\n      .then(setOrders);\\n  }, [userId]);\\n\\n  return (\\n    <div>\\n      {user ? <h1>{user.name}</h1> : <div className=\\"skeleton\\" />}\\n      {orders ? <OrderList items={orders} /> : <div className=\\"skeleton\\" />}\\n    </div>\\n  );\\n}"],[2518,"Да, предыдущий результат валидации нужно сбрасывать при каждом новом вводе пользователя. Это необходимо, чтобы пользователь видел актуальное состояние ошибок, а не устаревшие сообщения. Например, если поле было отмечено как невалидное, а затем пользователь его исправил, сообщение об ошибке должно исчезнуть. Иначе пользователь будет дезориентирован и не поймет, что ошибка уже исправлена.","При разработке форм с валидацией важно своевременно обновлять состояние ошибок. Если не сбрасывать предыдущий результат валидации при новом вводе, пользователь будет видеть устаревшие сообщения, что приводит к путанице и плохому пользовательскому опыту.\\n\\nПочему это важно\\n\\n- Обратная связь в реальном времени: пользователь должен сразу видеть, что его исправление принято системой.\\n- Предотвращение ложных ошибок: если поле было невалидным, а затем стало валидным, сообщение об ошибке должно исчезнуть.\\n- Улучшение UX: пользователь не будет тратить время на исправление уже решенных проблем.\\n\\nПример реализации\\nРассмотрим простую форму с валидацией email на React. При каждом изменении поля мы сбрасываем предыдущую ошибку и запускаем новую валидацию.\\n\\nВ этом примере при каждом вызове \`handleChange\` мы сначала сбрасываем ошибку, а затем проверяем новое значение. Если пользователь ввел корректный email, ошибка не появится.\\n\\nВывод\\nСброс предыдущего результата валидации при каждом новом вводе — это обязательная практика для создания интуитивно понятных форм. Она обеспечивает актуальную обратную связь и предотвращает дезинформацию пользователя.","import React, { useState } from 'react';\\n\\nfunction EmailForm() {\\n  const [email, setEmail] = useState('');\\n  const [error, setError] = useState('');\\n\\n  const validateEmail = (value) => {\\n    // Сбрасываем предыдущую ошибку\\n    setError('');\\n    \\n    if (!value.includes('@')) {\\n      setError('Email должен содержать @');\\n    }\\n  };\\n\\n  const handleChange = (e) => {\\n    const value = e.target.value;\\n    setEmail(value);\\n    validateEmail(value);\\n  };\\n\\n  return (\\n    <div>\\n      <input\\n        type=\\"email\\"\\n        value={email}\\n        onChange={handleChange}\\n      />\\n      {error && <p style={{color: 'red'}}>{error}</p>}\\n    </div>\\n  );\\n}"],[2519,"Лучше показывать элементы сразу, но с индикацией процесса валидации. Это улучшает пользовательский опыт, так как пользователь видит мгновенную обратную связь. Если дожидаться полной валидации, интерфейс будет казаться медленным. Исключение — критичные данные, где ошибка недопустима.","Введение\\nВопрос касается баланса между производительностью и пользовательским опытом при работе с формами или списками данных. Основная дилемма: показывать элементы сразу (оптимистичный UI) или после полной валидации (консервативный подход).\\n\\nОптимистичный UI\\nЭтот подход предполагает немедленное отображение данных, даже если они ещё не прошли проверку. Например, при добавлении элемента в список:\\n\\nПреимущества: интерфейс остаётся отзывчивым, пользователь видит результат мгновенно. Недостатки: возможны временные некорректные данные.\\n\\nКонсервативный подход\\nЗдесь данные отображаются только после успешной валидации. Это гарантирует, что пользователь никогда не увидит ошибочные данные, но увеличивает время ожидания.\\n\\nКогда что выбирать\\n\\n- Оптимистичный UI — для не критичных данных (например, комментарии, лайки), где временная ошибка не страшна.\\n- Консервативный — для финансовых операций, медицинских данных или любых случаев, где ошибка недопустима.\\n\\nВывод\\nОптимальная стратегия — гибрид: показывать элементы сразу с индикацией статуса валидации, но для критичных данных использовать блокировку интерфейса до подтверждения.","function addItem(item) {\\n  // Сразу добавляем в состояние\\n  setItems(prev => [...prev, { ...item, status: 'pending' }]);\\n  \\n  // Асинхронная валидация\\n  validateItem(item)\\n    .then(validated => {\\n      setItems(prev => prev.map(i => \\n        i.id === item.id ? { ...validated, status: 'valid' } : i\\n      ));\\n    })\\n    .catch(error => {\\n      setItems(prev => prev.filter(i => i.id !== item.id));\\n      showError(error);\\n    });\\n}\\n\\nasync function addItem(item) {\\n  try {\\n    const validated = await validateItem(item);\\n    setItems(prev => [...prev, validated]);\\n  } catch (error) {\\n    showError(error);\\n  }\\n}"],[2520,"Паттерн «Команда» превращает запрос или операцию в отдельный объект, содержащий всю информацию для её выполнения. Это позволяет параметризовать объекты операциями, ставить запросы в очередь, логировать их и поддерживать отмену. Во фронтенде он часто используется для реализации истории действий (undo/redo), макросов и асинхронных очередей.","Что такое паттерн «Команда»?\\nПаттерн «Команда» (Command) — это поведенческий паттерн проектирования, который превращает запрос в самостоятельный объект. Этот объект содержит все необходимые данные для выполнения действия: ссылку на получателя, параметры и метод выполнения. Такой подход отделяет отправителя запроса от его исполнителя, что даёт гибкость в управлении операциями.\\n\\nКак это работает?\\nОсновные участники паттерна:\\n- Command — интерфейс с методом execute() и, опционально, undo().\\n- ConcreteCommand — конкретная реализация, которая связывает действие с получателем.\\n- Invoker — инициатор, который хранит команду и вызывает её выполнение.\\n- Receiver — объект, который непосредственно выполняет бизнес-логику.\\n\\nПример на JavaScript для фронтенда\\nРассмотрим простой редактор текста с возможностью отмены действий:\\n\\nГде применяется во фронтенде?\\n\\n- Undo/Redo — в текстовых редакторах, графических редакторах, формах.\\n- Макросы и скрипты — запись последовательности действий для повторного выполнения.\\n- Очереди асинхронных операций — например, отправка нескольких запросов с возможностью отката.\\n- Компоненты с отложенным выполнением — кнопки, которые ставят команду в очередь вместо немедленного действия.\\n\\nВывод\\nПаттерн «Команда» полезен, когда нужно отделить инициирование операции от её выполнения, особенно если требуется поддержка отмены, логирования или постановки в очередь. Во фронтенде он незаменим для создания интерактивных интерфейсов с историей действий и гибким управлением пользовательскими операциями.","class Command {\\n  execute() {}\\n  undo() {}\\n}\\n\\nclass InsertTextCommand extends Command {\\n  constructor(receiver, text) {\\n    super();\\n    this.receiver = receiver;\\n    this.text = text;\\n  }\\n  execute() {\\n    this.receiver.insert(this.text);\\n  }\\n  undo() {\\n    this.receiver.deleteLast(this.text.length);\\n  }\\n}\\n\\nclass TextEditor {\\n  constructor() {\\n    this.content = '';\\n    this.history = [];\\n  }\\n  insert(text) {\\n    this.content += text;\\n  }\\n  deleteLast(n) {\\n    this.content = this.content.slice(0, -n);\\n  }\\n  executeCommand(command) {\\n    command.execute();\\n    this.history.push(command);\\n  }\\n  undo() {\\n    const command = this.history.pop();\\n    if (command) command.undo();\\n  }\\n}\\n\\nconst editor = new TextEditor();\\neditor.executeCommand(new InsertTextCommand(editor, 'Hello'));\\neditor.executeCommand(new InsertTextCommand(editor, ' World'));\\nconsole.log(editor.content); // 'Hello World'\\neditor.undo();\\nconsole.log(editor.content); // 'Hello'"],[2521,"При клике на кнопку в React вызывается функция setState, которая обновляет состояние компонента. Это приводит к ререндеру самого компонента и всех его дочерних компонентов, если они не оптимизированы с помощью React.memo или PureComponent. Ререндер происходит из-за того, что React сравнивает виртуальный DOM и обновляет реальный DOM только при изменениях.","Как работает ререндер в React\\nКогда пользователь кликает на кнопку, вызывается обработчик события, который обновляет состояние через setState. React помечает компонент как 'грязный' и планирует ререндер. При ререндере React вызывает функцию компонента (или метод render для классовых компонентов) и сравнивает полученный виртуальный DOM с предыдущим.\\n\\nКакие компоненты перерендерятся\\n\\n- Компонент, в котором произошло изменение состояния, перерендеривается всегда.\\n- Все его дочерние компоненты также перерендериваются по умолчанию, даже если их пропсы не изменились.\\n- Если дочерний компонент обернут в React.memo или является PureComponent, он перерендерится только при изменении его пропсов.\\n\\nПример кода\\n\\nВ этом примере при клике на кнопку Parent перерендерится, но Child не перерендерится благодаря React.memo, так как его пропсы не изменились.\\n\\nВывод\\nПонимание механизма ререндера помогает оптимизировать производительность React-приложений, особенно при работе с большими деревьями компонентов. Используйте React.memo, useMemo и useCallback для предотвращения лишних ререндеров.","function Parent() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <button onClick={() => setCount(count + 1)}>Click</button>\\n      <Child />\\n    </div>\\n  );\\n}\\n\\nconst Child = React.memo(() => {\\n  console.log('Child rendered');\\n  return <div>Child</div>\\n});"],[2522,"Да, дочерний компонент будет рендериться заново при каждом наборе текста в input. Это происходит потому, что изменение состояния (через useState) в родительском компоненте вызывает его повторный рендер, что по умолчанию приводит к повторному рендеру всех дочерних компонентов. React не оптимизирует это автоматически, если не использовать React.memo или другие методы.","Почему происходит повторный рендер дочернего компонента?\\nКогда пользователь вводит текст в input, обработчик события onChange обновляет состояние родительского компонента с помощью setState (например, через useState). Изменение состояния запускает повторный рендер родителя, и React по умолчанию рекурсивно перерисовывает все его дочерние компоненты, даже если их пропсы не изменились. Это стандартное поведение React для обеспечения актуальности UI.\\n\\nПример кода\\n\\nВ этом примере при каждом наборе текста в консоли будет появляться сообщение 'Child re-rendered', что подтверждает повторный рендер дочернего компонента.\\n\\nКак это применяется на практике?\\nТакое поведение может быть нежелательным для тяжелых компонентов. Для оптимизации используют React.memo, который предотвращает повторный рендер, если пропсы не изменились. Также можно вынести состояние в отдельный компонент или использовать useMemo/useCallback для стабильных ссылок.\\n\\nВывод\\nПонимание этого механизма важно для оптимизации производительности React-приложений. Используйте React.memo для дочерних компонентов, которые не зависят от изменяющегося состояния, чтобы избежать лишних рендеров.","function Parent() {\\n  const [text, setText] = useState('');\\n  return (\\n    <div>\\n      <input value={text} onChange={e => setText(e.target.value)} />\\n      <Child />\\n    </div>\\n  );\\n}\\n\\nfunction Child() {\\n  console.log('Child re-rendered');\\n  return <div>Static content</div>;\\n}"],[2523,"Чтобы дочерний компонент не рендерился при наборе текста в input, оберните его в React.memo. Это предотвратит ререндер, если пропсы не изменились. Также убедитесь, что функции-колбэки, передаваемые в дочерний компонент, обернуты в useCallback, чтобы их ссылки оставались стабильными.","Проблема лишних ререндеров\\nВ React при изменении состояния родительского компонента (например, при вводе текста в input) все его дочерние компоненты по умолчанию перерендериваются. Это может привести к проблемам производительности, особенно если дочерний компонент выполняет тяжелые вычисления или содержит сложную вложенность.\\n\\nРешение с React.memo\\nReact.memo — это компонент высшего порядка (HOC), который запоминает результат рендеринга. Он сравнивает новые пропсы с предыдущими с помощью поверхностного сравнения. Если пропсы не изменились, React.memo пропускает ререндер и использует закешированный результат.\\n\\nВажность useCallback\\nЕсли передавать функцию напрямую (без useCallback), при каждом рендере родителя будет создаваться новая ссылка на функцию. React.memo увидит изменение пропса onClick и выполнит ререндер, несмотря на обертку. useCallback гарантирует, что ссылка на функцию останется той же, если зависимости не изменились.\\n\\nВывод\\nИспользуйте React.memo для дочерних компонентов, которые не должны реагировать на изменения состояния родителя, и комбинируйте его с useCallback для функций-пропсов. Это стандартный подход для оптимизации производительности React-приложений, особенно при работе с формами, списками или анимациями.","import React, { useState, useCallback } from 'react';\\n\\nconst ExpensiveChild = React.memo(({ onClick }) => {\\n  console.log('Child rendered');\\n  return Click me;\\n});\\n\\nfunction Parent() {\\n  const [text, setText] = useState('');\\n  \\n  const handleClick = useCallback(() => {\\n    console.log('Button clicked');\\n  }, []);\\n\\n  return (\\n    \\n       setText(e.target.value)} />\\n      \\n    \\n  );\\n}"],[2524,"useEffect с зависимостью выполняется после рендера, когда указанное значение изменилось, и предназначен для синхронизации с внешним миром. Обработчик события вызывается немедленно при действии пользователя. useEffect подходит для запросов, логирования, а обработчик — для валидации, отправки формы, анимаций.","Разница между useEffect и обработчиком события\\nВ React побочные эффекты можно выполнять двумя основными способами: через \`useEffect\` (декларативно) и через обработчики событий (императивно). Понимание разницы критично для правильного управления состоянием и производительностью.\\n\\nКогда выполняется код\\n\\n- useEffect запускается после того, как React зафиксировал изменения в DOM. Если указан массив зависимостей, эффект выполняется только при изменении этих значений. Это асинхронно относительно рендера.\\n- Обработчик события (например, \`onClick\`) вызывается синхронно в момент действия пользователя, до следующего рендера.\\n\\nПример кода\\n\\nКогда что использовать\\n\\n- useEffect — для синхронизации с внешними системами (запросы, подписки, таймеры), когда нужно реагировать на изменения состояния или пропсов.\\n- Обработчик события — для немедленной реакции на действия пользователя (валидация, отправка формы, анимации, обновление локального состояния).\\n\\nВывод: Используйте useEffect для декларативных побочных эффектов, которые должны происходить после рендера, и обработчики событий для императивных действий, требующих мгновенного отклика.","import { useState, useEffect } from 'react';\\n\\nfunction Example() {\\n  const [count, setCount] = useState(0);\\n\\n  // useEffect: выполняется после рендера, когда count изменился\\n  useEffect(() => {\\n    console.log('Count changed to', count);\\n    // Здесь можно делать запрос к API\\n  }, [count]);\\n\\n  // Обработчик: вызывается сразу при клике\\n  const handleClick = () => {\\n    console.log('Button clicked, current count:', count);\\n    setCount(count + 1);\\n  };\\n\\n  return <button onClick={handleClick}>Click me</button>;\\n}"],[2525,"Помимо useEffect, можно использовать useLayoutEffect для синхронного выполнения после мутаций DOM, callback ref для прямого доступа к DOM-узлу при монтировании, MutationObserver для отслеживания появления элемента, а также атрибут autofocus в HTML. Эти подходы позволяют избежать лишних рендеров и улучшить производительность.","Альтернативные способы автофокуса\\nАвтофокус на элементе при его появлении в DOM можно реализовать несколькими способами, помимо стандартного useEffect. Каждый из них имеет свои особенности и области применения.\\n\\n1. useLayoutEffect\\nЭтот хук выполняется синхронно после всех мутаций DOM, но до того, как браузер отрисует изменения. Это гарантирует, что фокус будет установлен до того, как пользователь увидит элемент.\\n\\n2. Callback ref\\nCallback ref позволяет выполнить действие сразу после монтирования элемента. Это более гибкий подход, который не требует дополнительных эффектов.\\n\\n3. MutationObserver\\nДля динамически добавляемых элементов можно использовать MutationObserver, который отслеживает изменения в DOM и устанавливает фокус при появлении нужного элемента.\\n\\n4. HTML атрибут autofocus\\nСамый простой способ — использовать встроенный атрибут autofocus, который работает без JavaScript, но поддерживается не всеми браузерами и может конфликтовать с React.\\n\\nВывод: Выбор способа зависит от контекста: useLayoutEffect подходит для синхронного фокуса, callback ref — для простых случаев, MutationObserver — для динамических элементов, а autofocus — для статического HTML. Используйте эти подходы для оптимизации производительности и избежания лишних рендеров.","import { useLayoutEffect, useRef } from 'react';\\n\\nfunction AutoFocusInput() {\\n  const inputRef = useRef(null);\\n\\n  useLayoutEffect(() => {\\n    inputRef.current?.focus();\\n  }, []);\\n\\n  return <input ref={inputRef} />;\\n}\\n\\nfunction AutoFocusInput() {\\n  const inputRef = useCallback((node) => {\\n    node?.focus();\\n  }, []);\\n\\n  return <input ref={inputRef} />;\\n}\\n\\nconst observer = new MutationObserver((mutations) => {\\n  mutations.forEach((mutation) => {\\n    mutation.addedNodes.forEach((node) => {\\n      if (node.matches?.('input')) {\\n        node.focus();\\n        observer.disconnect();\\n      }\\n    });\\n  });\\n});\\n\\nobserver.observe(document.body, { childList: true, subtree: true });\\n\\n<input autofocus />"],[2526,"На frontend-проектах я предпочитаю модульную архитектуру папок, основанную на фичах (feature-based). В ней каждый модуль содержит все связанные с ним компоненты, стили, тесты и логику. Это упрощает навигацию, масштабирование и поддержку кода. Например, папка 'auth' включает компоненты, хуки, API-запросы и утилиты для авторизации.","Выбор архитектуры папок на frontend-проектах\\nАрхитектура папок напрямую влияет на поддерживаемость, масштабируемость и скорость разработки. Наиболее эффективным подходом для средних и крупных проектов является feature-based (модульная) архитектура. Она группирует код по функциональным возможностям, а не по техническим ролям.\\n\\nПочему feature-based?\\n\\n- Изоляция: Каждый модуль самодостаточен, что упрощает рефакторинг и удаление функциональности.\\n- Масштабирование: Новые фичи добавляются без изменения существующей структуры.\\n- Навигация: Разработчик быстро находит нужный код, так как все связанные файлы рядом.\\n\\nПример структуры\\n\\nВывод\\nFeature-based архитектура рекомендуется для проектов, где важна долгосрочная поддержка и командная работа. Она уменьшает связанность кода и ускоряет онбординг новых разработчиков.","src/\\n  features/\\n    auth/\\n      components/\\n        LoginForm.tsx\\n        RegisterForm.tsx\\n      hooks/\\n        useAuth.ts\\n      api/\\n        authApi.ts\\n      utils/\\n        validateEmail.ts\\n      tests/\\n        LoginForm.test.tsx\\n    dashboard/\\n      components/\\n        Chart.tsx\\n        StatsCard.tsx\\n      hooks/\\n        useDashboardData.ts\\n  shared/\\n    ui/\\n      Button.tsx\\n      Modal.tsx\\n    utils/\\n      formatDate.ts\\n  app/\\n    App.tsx\\n    routes.tsx"],[2527,"Для поиска избыточных ре-рендеров используют React DevTools Profiler, который показывает, какие компоненты перерисовываются и почему. Также можно использовать console.log или флаги в компонентах. Инструменты вроде Why Did You Render помогают автоматически выявлять ненужные ре-рендеры. Оптимизация включает React.memo, useMemo и useCallback.","Инструменты для выявления избыточных ре-рендеров\\nОсновной инструмент — React DevTools Profiler. Он записывает сессию взаимодействия с приложением и показывает, какие компоненты перерисовывались, сколько времени это заняло и какие пропсы или состояние изменились. Это позволяет быстро найти проблемные места.\\n\\nПрактические подходы\\n\\n- React.memo — оборачивает компонент, предотвращая ре-рендер, если пропсы не изменились (поверхностное сравнение).\\n- useMemo и useCallback — мемоизируют значения и функции, чтобы ссылки на них оставались стабильными между рендерами.\\n- Правильная структура состояния — поднимайте состояние только до необходимого уровня, избегайте хранения вычисляемых данных в state.\\n\\nПример кода\\n\\nВ этом примере \`ExpensiveComponent\` перерисовывается только при изменении \`text\`, а не при каждом клике на кнопку, благодаря \`React.memo\` и \`useMemo\`.\\n\\nВывод\\nИспользуйте React DevTools Profiler для первичного анализа, а затем применяйте мемоизацию и оптимизацию структуры компонентов. Это особенно полезно в больших приложениях с частыми обновлениями данных, чтобы избежать падения производительности.","import React, { useState, useMemo } from 'react';\\n\\nconst ExpensiveComponent = React.memo(({ data }) => {\\n  console.log('Render ExpensiveComponent');\\n  return <div>{data}</div>;\\n});\\n\\nfunction App() {\\n  const [count, setCount] = useState(0);\\n  const [text, setText] = useState('');\\n\\n  // Мемоизация, чтобы ссылка не менялась при изменении count\\n  const memoizedData = useMemo(() => text.toUpperCase(), [text]);\\n\\n  return (\\n    <div>\\n      <button onClick={() => setCount(c => c + 1)}>{count}</button>\\n      <input value={text} onChange={e => setText(e.target.value)} />\\n      <ExpensiveComponent data={memoizedData} />\\n    </div>\\n  );\\n}"],[2528,"Кэширование во frontend-приложении можно реализовать на нескольких уровнях: HTTP-кэш (через заголовки Cache-Control), кэш браузера (localStorage, sessionStorage, IndexedDB), кэш Service Worker (Cache API) и кэш CDN. Каждый уровень решает свою задачу: HTTP-кэш уменьшает количество запросов к серверу, Service Worker позволяет кэшировать ресурсы для офлайн-режима, а localStorage/IndexedDB хранят данные приложения. Выбор уровня зависит от типа данных и требований к актуальности.","Уровни кэширования во frontend-приложении\\nКэширование на стороне клиента — это ключевая техника для ускорения загрузки страниц и снижения нагрузки на сервер. Оно позволяет хранить копии ресурсов (HTML, CSS, JS, изображения, данные API) локально, чтобы при повторных запросах не загружать их заново. Рассмотрим основные уровни кэширования.\\n\\nHTTP-кэш (Cache-Control, ETag)\\nЭтот уровень управляется заголовками ответа сервера. Браузер автоматически сохраняет ответы в свой внутренний кэш и использует их до истечения срока действия. Пример настройки на сервере (Node.js/Express):\\n\\nЗдесь ресурс будет кэшироваться на 1 час. Для проверки актуальности используется ETag или Last-Modified.\\n\\nКэш Service Worker (Cache API)\\nService Worker — это прокси-слой между браузером и сетью. Он может перехватывать запросы и возвращать закэшированные ответы, даже при отсутствии интернета. Пример кэширования статики:\\n\\nЭто позволяет приложению работать офлайн и ускоряет загрузку при слабом соединении.\\n\\nКэш на стороне приложения (localStorage, IndexedDB)\\nДля хранения данных приложения (например, пользовательские настройки, результаты API) используются Web Storage API или IndexedDB. Пример с localStorage:\\n\\nIndexedDB подходит для больших объёмов структурированных данных.\\n\\nКэш CDN\\nContent Delivery Network (CDN) кэширует статические ресурсы на географически распределённых серверах. Это не совсем клиентский кэш, но он влияет на время загрузки. Настройка обычно происходит на стороне CDN-провайдера.\\n\\nВывод: Кэширование во frontend-приложении следует применять для улучшения пользовательского опыта и снижения нагрузки на сервер. HTTP-кэш подходит для статики, Service Worker — для офлайн-режима и динамических данных, а localStorage/IndexedDB — для данных приложения. Выбор уровня зависит от конкретных требований к актуальности и объёму данных.","app.get('/api/data', (req, res) => {\\n  res.set('Cache-Control', 'public, max-age=3600');\\n  res.json({ data: 'some data' });\\n});\\n\\nself.addEventListener('install', event => {\\n  event.waitUntil(\\n    caches.open('v1').then(cache => {\\n      return cache.addAll(['/index.html', '/style.css', '/app.js']);\\n    })\\n  );\\n});\\n\\nself.addEventListener('fetch', event => {\\n  event.respondWith(\\n    caches.match(event.request).then(response => {\\n      return response || fetch(event.request);\\n    })\\n  );\\n});\\n\\n// Сохранение\\nlocalStorage.setItem('user', JSON.stringify({ name: 'John' }));\\n\\n// Чтение\\nconst user = JSON.parse(localStorage.getItem('user'));"],[2529,"Да, эффект будет триггериться при каждом рендере, если передать spread-объект в зависимости. Причина в том, что spread-оператор создает новый объект каждый раз при рендере, и React сравнивает зависимости по ссылке. Новый объект всегда имеет новую ссылку, поэтому useEffect будет выполняться при каждом рендере, даже если поля объекта не изменились.","Проблема с spread-объектом в зависимостях useEffect\\nКогда вы передаете spread-объект в массив зависимостей useEffect, вы создаете новый объект при каждом рендере. React использует строгое сравнение (===) для проверки зависимостей. Поскольку каждый новый объект имеет уникальную ссылку в памяти, React считает, что зависимость изменилась, и запускает эффект заново.\\n\\nПример кода\\n\\nВ этом примере эффект будет выполняться при каждом рендере, даже если data не изменилась. Это происходит потому, что { ...data } создает новый объект с новой ссылкой.\\n\\nПравильное решение\\nЧтобы избежать этой проблемы, передавайте конкретные поля объекта в зависимости:\\n\\nИли используйте стабильную ссылку на объект, если он не меняется:\\n\\nВывод\\nИспользуйте spread-оператор в зависимостях useEffect только если вам действительно нужно реагировать на каждое изменение объекта. В большинстве случаев лучше передавать конкретные поля или использовать useMemo для стабилизации ссылки.","const MyComponent = ({ data }) => {\\n  useEffect(() => {\\n    console.log('Effect runs');\\n  }, [{ ...data }]); // Новый объект каждый раз\\n\\n  return {data.name};\\n};\\n\\nuseEffect(() => {\\n  console.log('Effect runs only when name changes');\\n}, [data.name]); // Только конкретное поле\\n\\nconst stableData = useMemo(() => data, [data]);\\n\\nuseEffect(() => {\\n  console.log('Effect runs');\\n}, [stableData]);"],[2530,"Используйте useRef для хранения предыдущего значения пропса. Внутри useEffect обновляйте ref.current после того, как вы использовали его для сравнения. Это позволяет получить предыдущее значение при следующем рендере.","Как получить предыдущее значение пропса с помощью useRef\\nВ React нет встроенного способа получить предыдущее значение пропса, но это можно сделать с помощью хука useRef в сочетании с useEffect. useRef создает объект, который сохраняет свое значение между рендерами, не вызывая повторный рендер при изменении.\\n\\nРеализация\\nСоздайте ref, который будет хранить предыдущее значение. Внутри useEffect обновите ref.current после того, как вы его использовали. Таким образом, при следующем рендере ref.current будет содержать предыдущее значение.\\n\\nКак это работает\\n\\n- useRef создает ref с начальным значением undefined.\\n- useEffect запускается после каждого рендера, когда value изменяется.\\n- Внутри useEffect мы обновляем ref.current, но это не вызывает повторный рендер.\\n- При следующем рендере usePrevious возвращает предыдущее значение, так как ref.current еще не обновлен.\\n\\nВывод\\nЭтот паттерн полезен для сравнения текущего и предыдущего значений пропсов, например, для анимаций, логирования или условных эффектов. Он прост в реализации и не требует дополнительных библиотек.","import { useRef, useEffect } from 'react';\\n\\nfunction usePrevious(value) {\\n  const ref = useRef();\\n  useEffect(() => {\\n    ref.current = value;\\n  }, [value]);\\n  return ref.current;\\n}\\n\\nfunction MyComponent({ count }) {\\n  const prevCount = usePrevious(count);\\n  return (\\n    <div>\\n      <p>Текущее: {count}</p>\\n      <p>Предыдущее: {prevCount}</p>\\n    </div>\\n  );\\n}"],[2531,"Передача функции в useState позволяет выполнить инициализацию состояния только один раз при первом рендере. Это полезно, когда начальное значение требует сложных вычислений или чтения из localStorage. В отличие от передачи значения, функция не будет вызываться при каждом обновлении компонента, что повышает производительность.","Что такое ленивая инициализация в useState?\\nВ React хук useState может принимать не только значение, но и функцию. Когда передаётся функция, React вызывает её только один раз — при первом рендере компонента. Это называется ленивой инициализацией (lazy initialization). Результат вызова функции становится начальным состоянием.\\n\\nКогда это нужно?\\nЛенивая инициализация полезна, когда начальное состояние требует дорогостоящих операций: чтение из localStorage, сложные математические вычисления, парсинг больших данных. Без неё эти операции выполнялись бы при каждом рендере, даже если состояние уже инициализировано.\\n\\nПример кода\\n\\nОтличие от передачи значения\\nЕсли передать значение, оно будет вычислено при каждом рендере (если это выражение). Функция же вызывается только один раз. Это особенно важно для тяжелых операций или когда начальное значение зависит от пропсов, которые могут меняться.\\n\\nВывод\\nИспользуйте ленивую инициализацию в useState, когда начальное состояние требует дорогих вычислений или асинхронных операций. Это улучшает производительность и делает код более предсказуемым.","// Плохо: вычисление при каждом рендере\\nconst [state, setState] = useState(expensiveComputation());\\n\\n// Хорошо: вычисление только один раз\\nconst [state, setState] = useState(() => expensiveComputation());\\n\\n// Пример с localStorage\\nconst [theme, setTheme] = useState(() => {\\n  const saved = localStorage.getItem('theme');\\n  return saved ? saved : 'light';\\n});"],[2532,"В useState можно положить любое значение: примитив (число, строка, булево), объект, массив, null, undefined или функцию. Если передать функцию, React вызовет её только при первом рендере — это называется ленивой инициализацией. Нельзя передавать Promise или другие асинхронные значения напрямую.","Что можно передать в initialValue useState?\\nХук \`useState\` в React принимает начальное значение состояния. Это может быть любой тип данных JavaScript: примитивы (числа, строки, булевы значения), объекты, массивы, \`null\`, \`undefined\` или даже функция. Главное правило — значение должно быть синхронным и не асинхронным (например, Promise не подойдёт).\\n\\nЛенивая инициализация\\nЕсли начальное состояние требует сложных вычислений, можно передать функцию. React вызовет её только один раз при первом рендере компонента, что улучшает производительность. Например:\\n\\nЭто особенно полезно, когда начальное значение получается из localStorage или API (но синхронно).\\n\\nПримеры использования\\n\\n- Примитивы: \`useState(0)\`, \`useState('hello')\`, \`useState(true)\`\\n- Объекты: \`useState({ name: 'John', age: 30 })\`\\n- Массивы: \`useState([1, 2, 3])\`\\n- null/undefined: \`useState(null)\`\\n- Функция: \`useState(() => 42)\`\\n\\nЧто нельзя передавать?\\nНельзя передавать асинхронные значения, такие как Promise или результат вызова асинхронной функции. Если нужно загрузить данные с сервера, используйте \`useEffect\` для установки состояния после монтирования.\\n\\nВывод\\nИспользуйте \`useState\` с любым синхронным значением. Для дорогих вычислений применяйте ленивую инициализацию через функцию. Это стандартная практика в React для управления состоянием компонентов.","const [state, setState] = useState(() => {\\n  const initial = expensiveComputation();\\n  return initial;\\n});"],[2533,"Хуки в React выполняются синхронно во время рендеринга компонента. Это означает, что вызов хука, такого как useState или useEffect, происходит в том же потоке, что и рендеринг. Однако обновление состояния, вызванное хуком, может быть отложено и обработано асинхронно в следующем рендере. Важно помнить, что сами хуки не являются асинхронными, но их эффекты могут быть.","Синхронная природа хуков\\nХуки в React, такие как useState, useEffect, useContext и другие, выполняются синхронно во время рендеринга компонента. Это означает, что когда вы вызываете хук, его логика обрабатывается немедленно в том же потоке выполнения, что и функция компонента. React гарантирует, что порядок вызовов хуков сохраняется между рендерами, что позволяет правильно связывать состояние и эффекты.\\n\\nПример синхронного выполнения\\n\\nВ этом примере useState вызывается синхронно, и значение count доступно сразу после вызова. Однако setCount, который обновляет состояние, работает асинхронно: React планирует новый рендер, но не выполняет его мгновенно.\\n\\nАсинхронные аспекты\\nХотя сами хуки синхронны, некоторые их эффекты могут быть асинхронными. Например, useEffect может содержать асинхронные операции, такие как запросы к API. Но сам хук useEffect вызывается синхронно после рендеринга, а его callback выполняется позже.\\n\\nЗдесь useEffect синхронно регистрирует эффект, но fetch выполняется асинхронно.\\n\\nВывод\\nХуки React синхронны по своей природе, что обеспечивает предсказуемость и порядок выполнения. Асинхронность возникает только в колбэках эффектов или при обновлении состояния, которое планируется на следующий рендер. Это важно учитывать при разработке, чтобы избежать ошибок, связанных с ожиданием мгновенных изменений состояния.","function Counter() {\\n  const [count, setCount] = useState(0); // синхронно\\n  console.log('Render:', count); // выполняется сразу\\n  return <button onClick={() => setCount(count + 1)}>{count}</button>;\\n}\\n\\nuseEffect(() => {\\n  fetch('/data').then(response => response.json()); // асинхронно\\n}, []);"],[2534,"Компонент степпера отображает последовательность шагов. Пропс length задает общее количество шагов, а activeStep указывает на текущий активный шаг. Компонент визуально выделяет активный шаг и показывает прогресс пользователя. Это упрощает навигацию по многошаговым формам или процессам.","Что такое компонент степпера?\\nКомпонент степпера (Stepper) — это UI-элемент, который визуализирует последовательность шагов в процессе, например, в многошаговой форме или мастере настройки. Он помогает пользователю понимать, на каком этапе он находится и сколько шагов осталось.\\n\\nПропсы length и activeStep\\nПропс \`length\` определяет общее количество шагов в процессе. Пропс \`activeStep\` указывает индекс текущего активного шага (начиная с 0). Компонент использует эти значения для отображения индикаторов шагов, выделения активного шага и, возможно, отметки завершенных шагов.\\n\\nПример реализации\\n\\nПрименение\\nСтепперы широко используются в регистрационных формах, процессах оформления заказа, настройке приложений и любых сценариях, где требуется пошаговое выполнение действий. Они улучшают пользовательский опыт, делая процесс прозрачным и управляемым.\\n\\nВывод: Компонент степпера с пропсами length и activeStep — это простой и эффективный способ визуализации прогресса в многошаговых интерфейсах. Его стоит применять везде, где пользователь должен последовательно выполнять несколько шагов, чтобы снизить когнитивную нагрузку и повысить удобство.","function Stepper({ length, activeStep }) {\\n  const steps = Array.from({ length }, (_, i) => i);\\n  return (\\n    <div style={{ display: 'flex', gap: '8px' }}>\\n      {steps.map((step) => (\\n        <div\\n          key={step}\\n          style={{\\n            width: '30px',\\n            height: '30px',\\n            borderRadius: '50%',\\n            backgroundColor: step === activeStep ? '#007bff' : '#ccc',\\n            display: 'flex',\\n            alignItems: 'center',\\n            justifyContent: 'center',\\n            color: '#fff',\\n          }}\\n        >\\n          {step + 1}\\n        </div>\\n      ))}\\n    </div>\\n  );\\n}"],[2535,"Элемент в HTML имеет атрибут open, который показывает диалог. В React управление через проп open означает, что компонент контролирует видимость диалога с помощью состояния. Когда open равен true, диалог отображается, иначе скрыт. Для закрытия можно использовать метод close() или изменить состояние.","Управление через проп open\\nЭлемент — это нативный HTML-элемент для создания модальных окон. В React управление его видимостью через проп open позволяет сделать компонент контролируемым: состояние родителя определяет, открыт диалог или нет.\\n\\nКак это работает\\nПроп open — это булево значение. Когда оно true, диалог отображается; когда false — скрыт. Однако просто установить атрибут open недостаточно для корректной работы модального окна: нужно также использовать методы show() или showModal() для открытия и close() для закрытия. В React это делается через рефы и эффекты.\\n\\nПример кода\\n\\nПрименение\\nТакой подход используется для создания модальных окон, попапов или диалогов подтверждения. Проп open даёт родительскому компоненту полный контроль над видимостью, что упрощает управление состоянием.\\n\\nВывод: Используйте управление через проп open, когда нужно синхронизировать состояние диалога с внешними данными, например, при открытии по клику или после загрузки.","import React, { useRef, useEffect } from 'react';\\n\\nfunction Dialog({ open, onClose, children }) {\\n  const dialogRef = useRef(null);\\n\\n  useEffect(() => {\\n    const dialog = dialogRef.current;\\n    if (open) {\\n      dialog.showModal(); // или show() для немодального\\n    } else {\\n      dialog.close();\\n    }\\n  }, [open]);\\n\\n  return (\\n    <dialog ref={dialogRef} onClose={onClose}>\\n      {children}\\n      <button onClick={onClose}>Закрыть</button>\\n    </dialog>\\n  );\\n}"],[2536,"Элемент предоставляет методы showModal() и close() для управления отображением. В React нужно получить доступ к DOM-элементу через useRef, затем вызвать эти методы в обработчиках событий. Это позволяет создавать модальные окна без сторонних библиотек.","Что такое элемент\\nЭлемент — это нативный HTML-элемент, предназначенный для создания модальных окон и диалогов. Он предоставляет встроенные методы showModal() для открытия окна в модальном режиме (с блокировкой фона) и close() для его закрытия. Это упрощает разработку, так как не требует дополнительных библиотек.\\n\\nИспользование в React через рефы\\nВ React для доступа к DOM-элементу используется хук useRef. Создаётся реф, который привязывается к элементу . Затем в обработчиках событий (например, onClick) вызываются методы showModal() и close() через текущее значение рефа.\\n\\nОсобенности и применение\\nМетод showModal() открывает диалог поверх остального контента и блокирует взаимодействие с фоном. Для закрытия можно использовать close() или нажатие клавиши Escape. Элемент также поддерживает событие 'close', которое можно обработать для дополнительной логики. Этот подход полезен для простых модальных окон, уведомлений или форм, когда не требуется сложная анимация или кастомизация.\\n\\nВывод: Используйте с рефами в React для быстрого создания модальных окон без внешних зависимостей, если проект не требует сложного управления состоянием или стилизации.","import { useRef } from 'react';\\n\\nfunction Modal() {\\n  const dialogRef = useRef(null);\\n\\n  const openModal = () => {\\n    dialogRef.current?.showModal();\\n  };\\n\\n  const closeModal = () => {\\n    dialogRef.current?.close();\\n  };\\n\\n  return (\\n    <>\\n      <button onClick={openModal}>Open Modal</button>\\n      <dialog ref={dialogRef}>\\n        <p>Modal content</p>\\n        <button onClick={closeModal}>Close</button>\\n      </dialog>\\n    </>\\n  );\\n}"],[2537,"React.memo принимает вторым необязательным аргументом функцию сравнения (areEqual). Она получает предыдущие и новые пропсы и должна вернуть true, если пропсы равны (ререндер не нужен), и false, если разные (нужен ререндер). По умолчанию используется поверхностное сравнение.","Что такое React.memo и зачем нужен второй аргумент?\\nReact.memo — это компонент высшего порядка (HOC), который мемоизирует функциональный компонент. Он предотвращает повторный рендеринг, если пропсы не изменились. По умолчанию React.memo использует поверхностное сравнение пропсов (shallow comparison). Однако в некоторых случаях требуется кастомная логика сравнения — для этого и существует второй аргумент.\\n\\nВторой аргумент: функция areEqual\\nВторой аргумент — это функция, которая принимает два параметра: prevProps и nextProps. Она должна вернуть true, если пропсы считаются равными (ререндер не нужен), и false, если они разные (нужен ререндер). Если функция не передана, React.memo использует стандартное поверхностное сравнение.\\n\\nКогда это полезно?\\n\\n- Когда пропсы содержат объекты или массивы, которые создаются заново при каждом рендере родителя, но их содержимое не меняется.\\n- Когда нужно игнорировать изменения определённых пропсов.\\n- Для оптимизации производительности в компонентах с тяжёлыми вычислениями.\\n\\nВажные замечания\\n\\n- Функция сравнения вызывается только при изменении пропсов. Если компонент ререндерится по другой причине (например, из-за изменения состояния), мемоизация не применяется.\\n- Не стоит злоупотреблять кастомным сравнением — оно само по себе может быть дорогим.\\n- Если функция сравнения возвращает false слишком часто, мемоизация теряет смысл.\\n\\nВывод: Второй аргумент React.memo — это функция areEqual для точного контроля над тем, когда компонент должен ререндериться. Используйте её, когда поверхностного сравнения недостаточно, например, при работе с вложенными объектами или массивами, чтобы избежать лишних ререндеров и улучшить производительность.","const MyComponent = React.memo(\\n  (props) => <div>{props.value}</div>,\\n  (prevProps, nextProps) => {\\n    // Кастомная логика сравнения\\n    return prevProps.value === nextProps.value;\\n  }\\n);"],[2538,"Для инициализации массива в useState передайте массив как начальное значение: const [items, setItems] = useState([]). Если массив должен быть пустым, используйте пустой массив []. Для предзаполненного массива передайте его напрямую: useState([1, 2, 3]). Избегайте передачи функции, возвращающей массив, если только не требуется ленивая инициализация.","Инициализация массива в useState\\nВ React хук useState позволяет хранить состояние компонента. Для массива начальное значение передается как аргумент. Простейший случай — пустой массив: \`useState([])\`. Если массив должен содержать данные, передайте его напрямую: \`useState([1, 2, 3])\`.\\n\\nЛенивая инициализация\\nЕсли начальное состояние требует сложных вычислений, используйте функцию-инициализатор: \`useState(() => computeInitialArray())\`. Это гарантирует, что вычисление выполнится только один раз при первом рендере.\\n\\nПример кода\\n\\nВажные моменты\\n\\n- Не изменяйте массив напрямую (push, splice) — используйте методы, возвращающие новый массив (spread, concat, filter, map).\\n- Для обновления состояния всегда передавайте новое значение или функцию, возвращающую новое значение.\\n- При работе с объектами в массиве создавайте копии объектов при изменении.\\n\\nВывод: правильная инициализация массива в useState — это передача начального значения (пустого или заполненного) или функции для ленивой инициализации. Это основа работы с коллекциями данных в React.","import React, { useState } from 'react';\\n\\nfunction TodoList() {\\n  const [todos, setTodos] = useState([]); // пустой массив\\n  const [initialTodos] = useState(() => {\\n    // ленивая инициализация\\n    return ['Learn React', 'Build project'];\\n  });\\n\\n  const addTodo = (text) => {\\n    setTodos([...todos, text]); // добавление элемента\\n  };\\n\\n  return (\\n    <div>\\n      <ul>\\n        {todos.map((todo, index) => (\\n          <li key={index}>{todo}</li>\\n        ))}\\n      </ul>\\n      <button onClick={() => addTodo('New task')}>Add</button>\\n    </div>\\n  );\\n}"],[2539,"Проблема в том, что setInterval создает замыкание на значение состояния, которое было на момент создания интервала. Чтобы использовать актуальное значение, можно передать функцию в setState (prev => prev + 1) или использовать useRef для хранения актуального значения. Также можно пересоздавать интервал при изменении зависимости с помощью useEffect.","Проблема с замыканиями в setInterval\\nКогда вы используете setInterval внутри useEffect, функция обратного вызова создает замыкание на переменную состояния, которая была актуальна на момент создания интервала. Это означает, что даже если состояние обновляется, интервал продолжает использовать старое значение.\\n\\nРешение с функциональным обновлением\\nСамый простой способ — использовать функциональную форму setState, которая получает предыдущее состояние и возвращает новое:\\n\\nРешение с useRef\\nДругой подход — хранить актуальное значение в ref и читать его внутри интервала:\\n\\nВывод\\nИспользуйте функциональное обновление состояния для простых случаев или useRef, когда нужно читать актуальное значение без пересоздания интервала. Это гарантирует корректную работу таймеров и избегает багов с устаревшими данными.","const [count, setCount] = useState(0);\\n\\nuseEffect(() => {\\n  const id = setInterval(() => {\\n    setCount(prev => prev + 1); // всегда использует актуальное значение\\n  }, 1000);\\n  return () => clearInterval(id);\\n}, []);\\n\\nconst [count, setCount] = useState(0);\\nconst countRef = useRef(count);\\n\\nuseEffect(() => {\\n  countRef.current = count;\\n}, [count]);\\n\\nuseEffect(() => {\\n  const id = setInterval(() => {\\n    console.log(countRef.current); // всегда актуально\\n  }, 1000);\\n  return () => clearInterval(id);\\n}, []);"],[2540,"TanStack Query (React Query) специализируется на управлении серверным состоянием: кэшировании, синхронизации и обновлении данных с API. Redux — это универсальный менеджер состояний, который часто используют для клиентского состояния, но для серверного требует написания большого количества шаблонного кода (редьюсеры, экшены, thunks). TanStack Query автоматически обрабатывает кэш, фоновую перезагрузку и инвалидацию, а Redux оставляет это разработчику.","Основное различие\\nTanStack Query (ранее React Query) и Redux решают разные задачи, хотя оба управляют состоянием. TanStack Query создан специально для работы с серверным состоянием — данными, которые приходят с API и могут устаревать. Он предоставляет встроенные механизмы кэширования, фоновой перезагрузки, пагинации и инвалидации. Redux — это универсальный контейнер для состояния, который не делает различий между серверными и клиентскими данными. Для работы с API в Redux приходится вручную настраивать middleware (например, Redux Thunk или Redux Saga) и писать редьюсеры для каждого запроса.\\n\\nПример кода\\nTanStack Query:\\n\\nRedux с Thunk:\\n\\nКогда что использовать\\n\\n- TanStack Query — для любого приложения, которое активно взаимодействует с API. Он сокращает код, автоматически обновляет данные и управляет кэшем.\\n- Redux — когда нужно сложное клиентское состояние (например, корзина, UI-настройки, формы) или когда серверное и клиентское состояние тесно переплетены.\\n\\nВывод: TanStack Query — лучший выбор для серверного состояния, Redux — для клиентского. Их можно комбинировать в одном проекте.","import { useQuery } from '@tanstack/react-query';\\n\\nfunction Posts() {\\n  const { data, isLoading, error } = useQuery({\\n    queryKey: ['posts'],\\n    queryFn: () => fetch('/api/posts').then(res => res.json()),\\n  });\\n\\n  if (isLoading) return 'Loading...';\\n  if (error) return 'Error!';\\n  return data.map(post => {post.title});\\n}\\n\\n// actions.js\\nexport const fetchPosts = () => async (dispatch) => {\\n  dispatch({ type: 'posts/fetchStart' });\\n  try {\\n    const res = await fetch('/api/posts');\\n    const data = await res.json();\\n    dispatch({ type: 'posts/fetchSuccess', payload: data });\\n  } catch (err) {\\n    dispatch({ type: 'posts/fetchError', payload: err });\\n  }\\n};\\n\\n// reducer.js\\nconst initialState = { data: [], isLoading: false, error: null };\\nexport default function postsReducer(state = initialState, action) {\\n  switch (action.type) {\\n    case 'posts/fetchStart': return { ...state, isLoading: true };\\n    case 'posts/fetchSuccess': return { ...state, isLoading: false, data: action.payload };\\n    case 'posts/fetchError': return { ...state, isLoading: false, error: action.payload };\\n    default: return state;\\n  }\\n}"],[2541,"Чтобы передать параметр в onClick, не вызывая функцию немедленно, используйте стрелочную функцию: onClick={() => handleClick(param)}. Это создает новую функцию, которая будет вызвана при клике. Альтернативно можно использовать .bind: onClick={handleClick.bind(null, param)}. Прямой вызов handleClick(param) выполнит функцию сразу при рендере.","Передача параметров в обработчик onClick\\nВ React и JavaScript важно передавать параметры в обработчики событий так, чтобы функция не вызывалась немедленно при рендере компонента. Если написать \`onClick={handleClick(param)}\`, то \`handleClick\` выполнится сразу, а не по клику, что часто приводит к ошибкам.\\n\\nОсновные способы\\n\\n- Стрелочная функция: \`onClick={() => handleClick(param)}\` — создает новую функцию, которая будет вызвана при событии. Это самый распространенный и читаемый способ.\\n- Метод .bind: \`onClick={handleClick.bind(null, param)}\` — возвращает новую функцию с привязанным контекстом и аргументами. Может быть менее производительным при частых ререндерах, но работает корректно.\\n\\nПример кода\\n\\nВ этом примере \`id\` передается в \`handleClick\` только при клике, а не при рендере.\\n\\nВывод\\nИспользуйте стрелочные функции для передачи параметров в обработчики событий в React — это просто, безопасно и соответствует лучшим практикам. Избегайте прямого вызова функций в JSX, чтобы предотвратить неожиданное выполнение кода.","function Button({ id }) {\\n  const handleClick = (param) => {\\n    console.log('Clicked:', param);\\n  };\\n\\n  return (\\n    <button onClick={() => handleClick(id)}>\\n      Click me\\n    </button>\\n  );\\n}"],[2542,"React использует поверхностное сравнение (shallow comparison) для определения изменений состояния. Когда вы вызываете setState, React сравнивает предыдущее и новое значение с помощью оператора строгого равенства (===). Мутация массива через push изменяет содержимое массива, но ссылка на массив остается той же. Поэтому React считает, что состояние не изменилось, и не запускает ре-рендер.","Почему мутация не вызывает ре-рендер?\\nВ React состояние должно быть неизменяемым (immutable). Когда вы используете хук \`useState\`, React хранит ссылку на объект состояния. При вызове функции обновления (например, \`setState\`) React сравнивает новое значение с предыдущим с помощью \`Object.is\` (аналог \`===\`). Если ссылка не изменилась, React считает, что состояние осталось прежним, и пропускает ре-рендер.\\n\\nПример проблемы\\n\\nКак это работает под капотом?\\nReact использует алгоритм согласования (reconciliation). Когда вызывается \`setState\`, React помечает компонент как требующий обновления. Затем во время рендера он сравнивает предыдущее виртуальное DOM-дерево с новым. Если состояние не изменилось (по ссылке), React пропускает рендер компонента и его дочерних элементов, что повышает производительность.\\n\\nВывод\\nВсегда создавайте новые объекты и массивы при обновлении состояния в React. Используйте спред-оператор, \`map\`, \`filter\` или библиотеки вроде Immer для удобной работы с иммутабельностью. Это гарантирует корректное обнаружение изменений и предсказуемое поведение интерфейса.","const [items, setItems] = useState([1, 2, 3]);\\n\\n// Неправильно: мутация\\nitems.push(4);\\nsetItems(items); // React не видит изменений, ре-рендера не будет\\n\\n// Правильно: создание нового массива\\nsetItems([...items, 4]); // Новая ссылка, ре-рендер произойдет"],[2543,"Если асинхронная операция в useEffect возвращает ошибку, React не обрабатывает её автоматически. Ошибка может привести к необработанному промису, что вызовет предупреждение в консоли или падение приложения. Для корректной обработки нужно использовать try/catch внутри эффекта и обновлять состояние ошибки. Также важно отменять запросы при размонтировании компонента через cleanup-функцию.","Что происходит при ошибке в асинхронном useEffect?\\nКогда вы выполняете асинхронную операцию внутри useEffect, например, fetch запрос, и она завершается ошибкой, React не перехватывает эту ошибку автоматически. Это может привести к необработанному отклонению промиса (unhandled promise rejection), которое в строгих окружениях (например, в Node.js) может завершить процесс, а в браузере — просто вывести предупреждение в консоль. Компонент при этом не узнает об ошибке, и пользователь не увидит никакого уведомления.\\n\\nКак правильно обрабатывать ошибки?\\nДля корректной обработки используйте конструкцию try/catch внутри асинхронной функции, объявленной в useEffect. Обновляйте состояние компонента, чтобы отобразить ошибку пользователю. Также важно отменять запросы при размонтировании компонента, чтобы избежать обновления состояния после размонтирования (это вызывает предупреждение React).\\n\\nПрактические рекомендации\\n\\n- Всегда оборачивайте асинхронный код в try/catch внутри useEffect.\\n- Используйте флаг или AbortController для отмены запросов при размонтировании.\\n- Не делайте сам useEffect асинхронным — React ожидает, что эффект вернет cleanup-функцию или undefined.\\n\\nВывод: обработка ошибок в асинхронных операциях useEffect — обязательная практика для стабильных React-приложений. Она предотвращает необработанные промисы и позволяет корректно уведомлять пользователя о проблемах.","useEffect(() => {\\n  let cancelled = false;\\n  async function fetchData() {\\n    try {\\n      const response = await fetch('/api/data');\\n      if (!cancelled) {\\n        setData(await response.json());\\n      }\\n    } catch (error) {\\n      if (!cancelled) {\\n        setError(error.message);\\n      }\\n    }\\n  }\\n  fetchData();\\n  return () => { cancelled = true; };\\n}, []);"],[2544,"Next.js — это фреймворк на основе React, который добавляет серверный рендеринг (SSR), статическую генерацию (SSG), маршрутизацию на основе файловой системы и API-роуты. В отличие от чистого React, который является только клиентской библиотекой для UI, Next.js предоставляет готовую архитектуру для full-stack приложений. Он упрощает SEO, улучшает производительность за счёт предварительной загрузки данных и автоматически оптимизирует бандлы.","Назначение Next.js\\nNext.js — это production-ready фреймворк для React, который решает задачи, выходящие за рамки клиентской библиотеки. Он предоставляет встроенные решения для серверного рендеринга (SSR), статической генерации (SSG), инкрементальной статической регенерации (ISR), маршрутизации, оптимизации изображений и API-роутов. Это позволяет создавать как полноценные веб-приложения с серверной логикой, так и высокопроизводительные статические сайты.\\n\\nКлючевые отличия от чистого React\\n\\n- Маршрутизация: В React используется React Router, который работает на клиенте. Next.js использует файловую систему для определения маршрутов (pages/ или app/), что упрощает навигацию и поддерживает динамические пути.\\n- Рендеринг: React рендерит всё на клиенте (CSR). Next.js позволяет выбирать между CSR, SSR, SSG и ISR для каждой страницы, что улучшает SEO и время загрузки.\\n- API-роуты: Next.js позволяет создавать серверные эндпоинты внутри проекта (pages/api), что устраняет необходимость в отдельном бэкенде для простых задач.\\n- Оптимизация: Встроенная оптимизация изображений, шрифтов, скриптов и автоматическое разделение кода (code splitting) — в React это требует дополнительных библиотек.\\n\\nПример кода: страница с SSR в Next.js\\n\\nВ этом примере данные загружаются на сервере перед отправкой HTML клиенту, что улучшает SEO и время до первого контента (FCP). В чистом React пришлось бы использовать useEffect и обрабатывать состояние загрузки.\\n\\nВывод\\nNext.js стоит применять, когда требуется SEO-оптимизация, быстрая загрузка страниц, встроенная серверная логика или статическая генерация контента. Для простых одностраничных приложений без потребности в SEO чистый React может быть более лёгким решением.","// pages/posts/[id].js\\nexport async function getServerSideProps(context) {\\n  const { id } = context.params;\\n  const res = await fetch(\`https://api.example.com/posts/\${id}\`);\\n  const post = await res.json();\\n  return { props: { post } };\\n}\\n\\nexport default function Post({ post }) {\\n  return <div><h1>{post.title}</h1><p>{post.body}</p></div>;\\n}"],[2545,"React Fragment — это встроенный компонент React, который позволяет группировать несколько элементов без добавления лишнего узла в DOM. Он используется, когда нужно вернуть несколько элементов из компонента, но обёртка вроде нарушает структуру или стили. Fragment не создаёт реального HTML-элемента, что улучшает производительность и чистоту разметки.","Что такое React Fragment?\\nReact Fragment — это легковесный способ группировки дочерних элементов в JSX без добавления лишнего узла в DOM. В обычном JSX вы не можете вернуть несколько элементов без обёртки, поэтому часто используют \`\`. Однако это может привести к избыточной вложенности, проблемам с CSS (например, Flexbox или Grid) и лишним узлам, которые замедляют рендеринг.\\n\\nЗачем он нужен?\\nFragment решает эти проблемы: он не создаёт реального HTML-элемента, а только группирует детей для React. Это особенно полезно в таблицах, списках или при использовании CSS-сеток, где лишний \`\` может сломать вёрстку.\\n\\nПример использования\\n\\nТакже можно использовать сокращённый синтаксис \`<>...\`, который не требует импорта.\\n\\nВывод\\nReact Fragment — это простой и эффективный инструмент для группировки элементов без загрязнения DOM. Применяйте его всегда, когда нужна обёртка только для JSX, а не для стилей или семантики.","import React, { Fragment } from 'react';\\n\\nfunction Table() {\\n  return (\\n    <table>\\n      <tr>\\n        <Fragment>\\n          <td>Ячейка 1</td>\\n          <td>Ячейка 2</td>\\n        </Fragment>\\n      </tr>\\n    </table>\\n  );\\n}"],[2546,"useRef создает объект с свойством .current, который сохраняется между рендерами. Для доступа к DOM-элементу нужно передать ref в атрибут элемента. Также useRef используется для хранения любых мутабельных данных (например, таймеров, предыдущих значений), изменение которых не вызывает ререндер компонента.","Что такое useRef и как он работает?\\nuseRef — это хук React, который возвращает мутабельный объект ref с единственным свойством .current. Этот объект сохраняется на протяжении всего жизненного цикла компонента и не изменяется между рендерами. В отличие от useState, изменение ref.current не вызывает повторный рендер компонента.\\n\\nДоступ к DOM-элементам\\nОсновное применение useRef — получение прямого доступа к DOM-элементу. Это полезно для фокусировки ввода, анимаций, интеграции с библиотеками, которые работают напрямую с DOM.\\n\\nХранение мутабельных значений\\nuseRef также используется для хранения любых данных, которые должны сохраняться между рендерами, но не влиять на них. Например, для хранения идентификатора таймера, предыдущего значения пропса или экземпляра стороннего объекта.\\n\\nВывод\\nuseRef — универсальный инструмент для работы с DOM и хранения мутабельных данных в React. Его стоит применять, когда нужно получить прямой доступ к элементу или сохранить значение без вызова ререндера, например, для таймеров, анимаций или интеграции с внешними библиотеками.","import { useRef, useEffect } from 'react';\\n\\nfunction AutoFocusInput() {\\n  const inputRef = useRef(null);\\n\\n  useEffect(() => {\\n    inputRef.current.focus();\\n  }, []);\\n\\n  return <input ref={inputRef} type=\\"text\\" />;\\n}\\n\\nimport { useRef, useEffect, useState } from 'react';\\n\\nfunction Timer() {\\n  const [count, setCount] = useState(0);\\n  const intervalRef = useRef(null);\\n\\n  useEffect(() => {\\n    intervalRef.current = setInterval(() => {\\n      setCount(prev => prev + 1);\\n    }, 1000);\\n    return () => clearInterval(intervalRef.current);\\n  }, []);\\n\\n  return <div>{count}</div>;\\n}"],[2547,"useContext — это хук React, который позволяет компонентам получать доступ к данным из контекста без передачи пропсов через всю цепочку. Он решает проблему пропс-дриллинга, когда данные нужно передавать через много уровней вложенных компонентов. Вместо этого вы создаете контекст с помощью createContext, оборачиваете компоненты в Provider и используете useContext для чтения значения.","Что такое useContext и зачем он нужен?\\nuseContext — это хук в React, который позволяет компоненту подписаться на контекст и получать его текущее значение. Контекст — это механизм для передачи данных через дерево компонентов без необходимости передавать пропсы на каждом уровне. Основная проблема, которую решает useContext, — это пропс-дриллинг (props drilling), когда данные передаются через множество промежуточных компонентов, которые сами их не используют. Это делает код громоздким и сложным для поддержки.\\n\\nКак это работает?\\nСначала создается контекст с помощью \`React.createContext()\`. Затем компонент-провайдер оборачивает дочерние компоненты и передает значение через атрибут \`value\`. Любой компонент внутри провайдера может использовать \`useContext(MyContext)\`, чтобы получить это значение. При изменении значения контекста все подписанные компоненты перерендериваются.\\n\\nПример кода\\n\\nКогда применять?\\nuseContext идеален для глобальных данных, которые редко меняются, таких как тема, язык или аутентификация. Однако для часто обновляемого состояния (например, данные формы) лучше использовать Redux или другие библиотеки, так как контекст может вызывать лишние перерендеры. Вывод: useContext — простой и эффективный способ избежать пропс-дриллинга, но его стоит применять для данных, которые не меняются слишком часто.","import React, { createContext, useContext, useState } from 'react';\\n\\nconst ThemeContext = createContext('light');\\n\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Toolbar />\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nfunction Toolbar() {\\n  const { theme, setTheme } = useContext(ThemeContext);\\n  return (\\n    <div>\\n      <p>Current theme: {theme}</p>\\n      <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>\\n        Toggle\\n      </button>\\n    </div>\\n  );\\n}"],[2548,"React использует поверхностное сравнение (===) для каждого элемента массива зависимостей. Если хотя бы одно значение изменилось по ссылке, эффект выполняется заново. Это позволяет React эффективно определять, когда нужно обновить побочные эффекты, избегая лишних вызовов.","Как работает отслеживание зависимостей в useEffect\\nReact сравнивает текущие значения зависимостей с предыдущими при каждом рендере. Для этого используется строгое равенство (Object.is), которое аналогично оператору ===, но с учетом NaN. Если хотя бы одна зависимость изменилась, эффект запускается повторно.\\n\\nПример с примитивами и объектами\\n\\nДля примитивов (числа, строки) сравнение происходит по значению. Для объектов и массивов — по ссылке. Поэтому изменение свойства объекта без создания нового объекта не вызовет эффект.\\n\\nПрактическое применение\\nЭтот механизм критичен для оптимизации производительности. Если передать в зависимости массив, который создается заново при каждом рендере, эффект будет выполняться каждый раз. Чтобы избежать этого, используют useMemo или useCallback для стабилизации ссылок.\\n\\nВывод: Понимание поверхностного сравнения зависимостей помогает избежать бесконечных циклов и лишних вызовов эффектов, что особенно важно в сложных React-приложениях.","const [count, setCount] = useState(0);\\nconst [user, setUser] = useState({ name: 'Alice' });\\n\\nuseEffect(() => {\\n  console.log('Эффект выполнен');\\n}, [count, user]);\\n\\n// При setCount(1) — эффект выполнится (count изменился)\\n// При setUser({ name: 'Alice' }) — эффект выполнится (новая ссылка на объект)"],[2549,"Вызов хука после условного return нарушает правила хуков React. React полагается на порядок вызова хуков между рендерами. Если хук вызывается после return, он может быть пропущен при следующем рендере, что приведет к ошибке \\"Rendered fewer hooks than expected\\".","Почему это проблема\\nReact использует порядок вызова хуков для сопоставления состояния между рендерами. Если хук вызывается после условного return, то при разных условиях рендера количество и порядок хуков могут меняться. Это нарушает внутренние ожидания React и вызывает ошибку.\\n\\nПример\\n\\nВ этом примере, если \`flag\` равен \`true\`, компонент возвращает \`null\` и хуки не вызываются. При следующем рендере с \`flag = false\` React ожидает, что хуки будут вызваны в том же порядке, но их количество изменилось, что приводит к ошибке.\\n\\nКак исправить\\nВсе хуки должны вызываться на верхнем уровне компонента, до любых условных return. Условный return можно разместить после всех хуков или использовать условный рендеринг внутри JSX.\\n\\nВывод\\nСоблюдение правил хуков гарантирует стабильность и предсказуемость работы компонентов. Всегда размещайте хуки до любых условных операторов, чтобы избежать ошибок времени выполнения.","function MyComponent({ flag }) {\\n  if (flag) {\\n    return null;\\n  }\\n  const [value, setValue] = useState(0); // Ошибка!\\n  useEffect(() => {}, []);\\n  return <div>{value}</div>;\\n}\\n\\nfunction MyComponent({ flag }) {\\n  const [value, setValue] = useState(0);\\n  useEffect(() => {}, []);\\n  if (flag) {\\n    return null;\\n  }\\n  return <div>{value}</div>;\\n}"],[2550,"Микрофронтенды могут взаимодействовать через глобальное событие (Event Bus), общее состояние (например, Redux store), URL-параметры или через родительский контейнер. Каждый микрофронтенд подписывается на события или читает общие данные. Это позволяет им обмениваться информацией, не нарушая изоляцию.","Способы взаимодействия микрофронтендов\\nМикрофронтенды — это независимые части интерфейса, которые разрабатываются и развертываются отдельно, но работают вместе в одном приложении. Для их координации нужны механизмы коммуникации, которые не нарушают автономность.\\n\\nОсновные подходы\\n\\n- Event Bus (шина событий): глобальный объект, через который микрофронтенды отправляют и получают события. Например, один микрофронтенд публикует событие 'userLoggedIn', а другой подписывается на него и обновляет UI.\\n- Общее состояние (Shared State): использование единого хранилища, такого как Redux или MobX, доступного всем микрофронтендам. Изменения в одном модуле автоматически отражаются в других.\\n- URL и маршрутизация: передача данных через query-параметры или хэш URL. Например, при переходе между микрофронтендами информация о текущем пользователе передается в адресной строке.\\n- Родительский контейнер (Shell): главное приложение выступает посредником, передавая пропсы или вызывая методы дочерних модулей.\\n\\nПример с Event Bus\\n\\nВывод\\nВыбор способа зависит от сложности приложения: для простых сценариев подходит Event Bus, для сложных — общее состояние. Главное — сохранять слабую связанность, чтобы микрофронтенды оставались независимыми.","// Микрофронтенд A публикует событие\\nwindow.eventBus.publish('cartUpdated', { items: 3 });\\n\\n// Микрофронтенд B подписывается\\nwindow.eventBus.subscribe('cartUpdated', (data) => {\\n  console.log('Корзина обновлена:', data.items);\\n});"],[2551,"Context API подходит для простого проброса данных, которые редко меняются, например тема или язык. Внешний стейт-менеджер (Redux, Zustand) нужен при частых обновлениях, сложной логике или большом количестве взаимосвязанных состояний. Context вызывает ререндер всех потребителей при любом изменении, что снижает производительность. Внешние решения оптимизируют обновления и предоставляют инструменты для отладки.","Когда Context API достаточен\\nContext API в React предназначен для передачи данных через дерево компонентов без явного прокидывания пропсов. Он хорошо работает для статических или редко изменяемых значений, таких как тема оформления, локаль пользователя или аутентификационные данные. В этих сценариях обновления происходят нечасто, и производительность не страдает.\\n\\nКогда нужен внешний стейт-менеджер\\nЕсли состояние часто обновляется (например, каждое нажатие клавиши в форме) или имеет сложную логику с множеством зависимостей, Context может вызвать избыточные ререндеры. Внешние библиотеки, такие как Redux или Zustand, используют подписки на отдельные части состояния, что минимизирует перерисовки. Они также предоставляют middleware, devtools и строгую архитектуру для больших приложений.\\n\\nПример сравнения\\n\\nВывод\\nИспользуйте Context API для глобальных, редко меняющихся данных. Для динамичного состояния с частыми обновлениями или сложной бизнес-логикой выбирайте внешний стейт-менеджер, чтобы сохранить производительность и поддерживаемость кода.","// Context - ререндер всех потребителей при изменении\\nconst ThemeContext = React.createContext('light');\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Header /> <!-- ререндерится -->\\n      <Footer /> <!-- ререндерится -->\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\n// Redux - обновляется только подписанный компонент\\nconst selectTheme = (state) => state.theme;\\nfunction Header() {\\n  const theme = useSelector(selectTheme);\\n  return <div>{theme}</div>;\\n}"],[2552,"Да, React гарантирует, что ссылка на функцию setter, возвращаемая из useState, остаётся стабильной между рендерами. Это означает, что функция не пересоздаётся при каждом рендере, если только компонент не размонтируется и не монтируется заново. Такая стабильность позволяет безопасно использовать setter в зависимостях эффектов или передавать его в дочерние компоненты без лишних ререндеров.","Стабильность ссылки на setter из useState\\nReact гарантирует, что функция setter, возвращаемая из хука useState, сохраняет одну и ту же ссылку между рендерами компонента. Это означает, что при каждом вызове useState в одном и том же компоненте возвращается одна и та же функция для обновления состояния, если только компонент не был полностью размонтирован и смонтирован заново.\\n\\nПочему это важно\\nСтабильность ссылки критична для оптимизации производительности в React. Когда вы передаёте setter в качестве пропса дочернему компоненту или используете его в массиве зависимостей хука useEffect, стабильная ссылка предотвращает ненужные ререндеры и повторные вызовы эффектов. Если бы ссылка менялась каждый рендер, это приводило бы к бесконечным циклам или избыточным вычислениям.\\n\\nПример кода\\n\\nВ этом примере setCount передаётся в зависимости useEffect. Благодаря стабильности ссылки эффект выполняется только при монтировании компонента, а не при каждом изменении count.\\n\\nИсключения и особенности\\n\\n- Стабильность гарантируется только для setter из useState. Другие хуки, например useReducer, также возвращают стабильный dispatch.\\n- Если компонент размонтируется и монтируется заново (например, при изменении ключа), setter будет новым.\\n- В строгом режиме React (StrictMode) может вызывать рендеры дважды, но ссылка на setter остаётся стабильной в рамках одного монтирования.\\n\\nВывод\\nСтабильность ссылки на setter из useState — это фундаментальная особенность React, которая упрощает оптимизацию и предотвращает баги, связанные с изменяющимися ссылками. Используйте это свойство для безопасной передачи setter в дочерние компоненты или в зависимости эффектов, не опасаясь лишних ререндеров.","import React, { useState, useEffect } from 'react';\\n\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    // setCount стабилен, эффект выполнится только один раз\\n    console.log('Effect runs');\\n  }, [setCount]);\\n\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={() => setCount(c => c + 1)}>Increment</button>\\n    </div>\\n  );\\n}"],[2553,"Когда таймер обновляет состояние в родительском компоненте, React перерисовывает родителя и всех его дочерних компонентов, даже если их пропсы не изменились. Это происходит из-за того, что при каждом рендере создаются новые ссылки на функции и объекты. Исправить можно с помощью React.memo для мемоизации дочернего компонента, useCallback для стабилизации функций-пропсов и useMemo для стабилизации объектов.","Почему таймер вызывает ре-рендер дочерних компонентов\\nВ React каждый раз, когда обновляется состояние компонента (например, через setInterval), происходит его ре-рендер. При ре-рендере родителя все дочерние компоненты также перерисовываются по умолчанию, даже если их пропсы не изменились. Это связано с тем, что React не сравнивает пропсы автоматически — он просто вызывает render для всех потомков.\\n\\nПроблема усугубляется, если в пропсы передаются функции или объекты, создаваемые прямо в JSX. При каждом рендере создаются новые ссылки, что ломает даже React.memo, если не использовать useCallback или useMemo.\\n\\nКак это исправить\\nЕсть три основных подхода:\\n- React.memo — оборачивает компонент, чтобы он перерисовывался только при изменении пропсов (поверхностное сравнение).\\n- useCallback — мемоизирует функцию, чтобы её ссылка оставалась стабильной между рендерами.\\n- useMemo — мемоизирует результат вычисления или объект.\\n\\nПример кода\\n\\nВ этом примере Child обёрнут в React.memo, а handleClick стабилизирован через useCallback. Благодаря этому Child не будет перерисовываться при каждом тике таймера.\\n\\nВывод\\nИспользуйте React.memo для компонентов, которые часто получают одни и те же пропсы, а useCallback/useMemo для стабилизации ссылок. Это особенно важно при работе с таймерами, анимациями или большими списками, чтобы избежать лишних ре-рендеров и сохранить производительность приложения.","import React, { useState, useEffect, useCallback, memo } from 'react';\\n\\nconst Child = memo(({ onClick }) => {\\n  console.log('Child re-render');\\n  return <button onClick={onClick}>Click</button>;\\n});\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const timer = setInterval(() => setCount(c => c + 1), 1000);\\n    return () => clearInterval(timer);\\n  }, []);\\n\\n  // Без useCallback — новая функция каждый рендер\\n  const handleClick = useCallback(() => {\\n    console.log('Clicked');\\n  }, []);\\n\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <Child onClick={handleClick} />\\n    </div>\\n  );\\n}"],[2554,"Основные способы: React.memo для мемоизации компонента, useMemo для мемоизации значений, useCallback для мемоизации функций-колбэков. Также можно выносить тяжелые вычисления в useMemo и избегать передачи новых объектов/функций при каждом рендере. Это помогает React пропускать рендер, если пропсы не изменились.","Проблема лишних ре-рендеров\\nВ React при обновлении состояния родительского компонента все его дочерние компоненты по умолчанию перерендериваются, даже если их пропсы не изменились. Это может привести к снижению производительности, особенно в глубоких деревьях компонентов или при тяжелых вычислениях.\\n\\nОсновные способы предотвращения\\n\\n- React.memo — оборачивает компонент и сравнивает пропсы поверхностно. Если пропсы не изменились, компонент не перерендеривается.\\n- useMemo — мемоизирует результат вычислений, чтобы не пересоздавать объекты/массивы при каждом рендере.\\n- useCallback — мемоизирует функцию, чтобы ссылка на неё оставалась стабильной между рендерами.\\n\\nПример кода\\n\\nВ этом примере \`Child\` обёрнут в \`React.memo\`, а пропсы \`data\` и \`onClick\` стабильны благодаря \`useMemo\` и \`useCallback\`. При изменении \`other\` \`Child\` не перерендерится.\\n\\nДополнительные техники\\n\\n- Подъём состояния (lifting state up) — выносить общее состояние выше, чтобы избежать лишних рендеров.\\n- Использование ключей (keys) для корректного сравнения элементов списка.\\n- Разделение компонентов на контейнеры и презентационные.\\n\\nВывод: Применяйте \`React.memo\`, \`useMemo\` и \`useCallback\` осознанно, только когда профилирование показывает проблему производительности. Избыточная мемоизация может усложнить код и не дать выигрыша.","import React, { useState, useMemo, useCallback } from 'react';\\n\\nconst Child = React.memo(({ onClick, data }) => {\\n  console.log('Child render');\\n  return <button onClick={onClick}>{data.value}</button>;\\n});\\n\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  const [other, setOther] = useState(0);\\n\\n  // useMemo для стабильного объекта\\n  const data = useMemo(() => ({ value: count }), [count]);\\n\\n  // useCallback для стабильной функции\\n  const handleClick = useCallback(() => {\\n    setCount(c => c + 1);\\n  }, []);\\n\\n  return (\\n    <div>\\n      <Child onClick={handleClick} data={data} />\\n      <button onClick={() => setOther(o => o + 1)}>Other: {other}</button>\\n    </div>\\n  );\\n}"],[2555,"Линтер (eslint-plugin-react-hooks) требует указывать все переменные и функции, используемые внутри useEffect, в массиве зависимостей. Пустой массив означает, что эффект выполняется только один раз при монтировании. Если внутри эффекта используются пропсы, стейт или другие значения, они могут быть устаревшими (stale closure). Линтер предупреждает об этом, чтобы предотвратить баги. Если пустой массив намеренный, нужно либо вынести логику в useRef, либо добавить комментарий // eslint-disable-next-line.","Почему линтер ругается на пустой массив зависимостей в useEffect?\\nЛинтер, а именно плагин \`eslint-plugin-react-hooks\`, анализирует код на соответствие правилам хуков React. Одно из ключевых правил — \`react-hooks/exhaustive-deps\`. Оно требует, чтобы все переменные, функции и пропсы, используемые внутри \`useEffect\`, были перечислены в массиве зависимостей. Если массив пуст, а внутри эффекта есть обращения к внешним значениям, линтер выдаёт предупреждение или ошибку.\\n\\nПроблема устаревших замыканий\\nКогда вы передаёте пустой массив \`[]\`, эффект выполняется только один раз — при монтировании компонента. Все переменные, захваченные в замыкание эффекта, сохраняют свои значения на момент первого рендера. Если эти переменные позже изменятся (например, через \`useState\` или пропсы), эффект продолжит использовать старые значения. Это называется stale closure (устаревшее замыкание).\\n\\nПример проблемы\\n\\nВ этом примере \`count\` внутри \`setInterval\` всегда будет равен 0, потому что эффект захватил его при первом рендере. Линтер предупреждает, что \`count\` должен быть в зависимостях.\\n\\nКогда пустой массив намеренный\\nИногда пустой массив действительно нужен, например, для подписки на внешний источник данных или аналитики, которая должна сработать один раз. В таких случаях можно:\\n- Использовать \`useRef\` для хранения актуальных значений, чтобы избежать устаревших замыканий.\\n- Добавить комментарий \`// eslint-disable-next-line react-hooks/exhaustive-deps\` над строкой с массивом, чтобы отключить предупреждение.\\n\\nПравильный подход\\n\\nВ этом варианте мы используем функциональную форму \`setCount\`, которая не зависит от внешнего \`count\`. Линтер видит, что внутри эффекта нет обращений к переменным из рендера, поэтому пустой массив допустим.\\n\\nВывод\\nЛинтер ругается на пустой массив зависимостей, чтобы предотвратить баги с устаревшими замыканиями. Если пустой массив намеренный, убедитесь, что внутри эффекта не используются внешние переменные, или используйте \`useRef\` для их хранения. В крайнем случае можно отключить правило для конкретной строки, но это должно быть осознанным решением.","function Timer({ start }) {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const id = setInterval(() => {\\n      setCount(count + 1); // count всегда 0, так как захвачен при монтировании\\n    }, 1000);\\n    return () => clearInterval(id);\\n  }, []); // линтер ругается: count не указан в зависимостях\\n\\n  return <div>{count}</div>;\\n}\\n\\nfunction Timer({ start }) {\\n  const [count, setCount] = useState(0);\\n\\n  useEffect(() => {\\n    const id = setInterval(() => {\\n      setCount(prev => prev + 1); // используем функциональную форму setState\\n    }, 1000);\\n    return () => clearInterval(id);\\n  }, []); // теперь линтер не ругается, так как нет внешних зависимостей\\n\\n  return <div>{count}</div>;\\n}"],[2556,"Внутри useEffect нельзя передавать асинхронную функцию напрямую, так как она возвращает промис, а не функцию очистки. Вместо этого нужно объявить асинхронную функцию внутри колбэка и вызвать её. Также важно обрабатывать ошибки с try/catch и использовать функцию очистки для отмены запросов при размонтировании компонента.","Проблема с async/await в useEffect\\nХук useEffect ожидает, что переданная функция либо ничего не возвращает, либо возвращает функцию очистки. Асинхронная функция всегда возвращает промис, поэтому передача её напрямую вызовет ошибку или нежелательное поведение.\\n\\nПравильный подход\\nСоздайте асинхронную функцию внутри колбэка useEffect и сразу вызовите её. Это позволяет использовать await и обрабатывать ошибки.\\n\\nОбработка отмены запросов\\nДля предотвращения утечек памяти при размонтировании компонента используйте флаг или AbortController.\\n\\nВывод\\nИспользуйте внутреннюю асинхронную функцию с try/catch и функцией очистки для безопасной работы с асинхронными операциями в useEffect. Это предотвращает утечки памяти и корректно обрабатывает ошибки.","useEffect(() => {\\n  const fetchData = async () => {\\n    try {\\n      const response = await fetch('/api/data');\\n      const data = await response.json();\\n      setData(data);\\n    } catch (error) {\\n      console.error('Ошибка загрузки:', error);\\n    }\\n  };\\n  fetchData();\\n}, []);\\n\\nuseEffect(() => {\\n  const controller = new AbortController();\\n  const fetchData = async () => {\\n    try {\\n      const response = await fetch('/api/data', { signal: controller.signal });\\n      const data = await response.json();\\n      setData(data);\\n    } catch (error) {\\n      if (error.name !== 'AbortError') {\\n        console.error(error);\\n      }\\n    }\\n  };\\n  fetchData();\\n  return () => controller.abort();\\n}, []);"],[2557,"useEffect принимает синхронную функцию, чтобы React мог гарантировать, что эффект выполняется после рендера, а функция очистки вызывается перед размонтированием или повторным запуском. Синхронность позволяет React управлять порядком выполнения и избегать гонок данных. Если бы функция была асинхронной, React не смог бы правильно обработать очистку и зависимость от предыдущего состояния.","Почему useEffect принимает синхронную функцию?\\nuseEffect в React предназначен для выполнения побочных эффектов, таких как запросы к API, подписки или манипуляции с DOM. Первый аргумент должен быть синхронной функцией, чтобы React мог контролировать её выполнение и гарантировать, что эффект запускается только после завершения рендера. Это также позволяет React вызывать функцию очистки, возвращаемую из эффекта, в правильный момент — перед размонтированием компонента или перед повторным запуском эффекта при изменении зависимостей.\\n\\nКак это работает на практике?\\nКогда вы передаёте асинхронную функцию напрямую, React не может дождаться её завершения, что может привести к проблемам с очисткой и утечкам памяти. Вместо этого вы должны объявить асинхронную функцию внутри синхронного колбэка и вызвать её. Например:\\n\\nЗдесь внешняя функция синхронна, что позволяет React корректно управлять её выполнением и очисткой.\\n\\nГде это применяется?\\nЭтот подход используется во всех React-приложениях для работы с побочными эффектами. Он гарантирует предсказуемое поведение компонентов и предотвращает ошибки, связанные с асинхронностью.\\n\\nВывод: Используйте синхронную функцию в useEffect, чтобы React мог правильно управлять жизненным циклом эффекта, а асинхронные операции выполняйте внутри неё для безопасности и чистоты кода.","useEffect(() => {\\n  const fetchData = async () => {\\n    const response = await fetch('/api/data');\\n    const data = await response.json();\\n    setData(data);\\n  };\\n  fetchData();\\n}, []);"],[2558,"Когда функция обновления состояния вызывается в дочернем компоненте, React обновляет состояние в родительском компоненте. Это вызывает повторный рендер родительского компонента и всех его дочерних компонентов, включая тот, который вызвал функцию. React по умолчанию перерендеривает все дочерние элементы, если не используются оптимизации вроде React.memo.","Как работает рендеринг при передаче функции обновления состояния\\nВ React состояние управляется на уровне компонента, где оно объявлено с помощью хука useState. Когда функция обновления состояния (setState) передается в дочерний компонент через пропсы и вызывается там, она изменяет состояние именно в родительском компоненте. Это запускает процесс повторного рендеринга, который начинается с родителя и распространяется вниз по дереву компонентов.\\n\\nКакие компоненты перерендериваются\\n\\n- Родительский компонент, где объявлено состояние, перерендеривается первым.\\n- Все дочерние компоненты родителя, включая тот, который вызвал функцию, также перерендериваются по умолчанию.\\n- Если дочерние компоненты не используют React.memo или другие оптимизации, они будут перерендерены независимо от того, изменились ли их пропсы.\\n\\nПример кода\\n\\nПри нажатии на кнопку в Child вызывается onIncrement, который обновляет count в Parent. Это приводит к повторному рендеру Parent и Child, что видно по сообщению в консоли.\\n\\nВывод\\nПонимание этого механизма важно для оптимизации производительности React-приложений. Если дочерний компонент не должен перерендериваться при каждом изменении состояния родителя, используйте React.memo или выделите состояние в отдельный контекст.","function Parent() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <Child onIncrement={() => setCount(c => c + 1)} />\\n    </div>\\n  );\\n}\\n\\nfunction Child({ onIncrement }) {\\n  console.log('Child re-rendered');\\n  return <button onClick={onIncrement}>Increment</button>;\\n}"],[2559,"Redux использует однонаправленный поток данных. Когда пользователь инициирует действие, вызывается dispatch(action). Redux передает action и текущее состояние в reducer, который возвращает новое состояние. Затем store обновляется, и подписанные компоненты перерисовываются.","Как работает цикл Redux\\nRedux — это предсказуемый контейнер состояния для JavaScript-приложений. Его ключевая особенность — однонаправленный поток данных, который делает изменения состояния предсказуемыми и легко отслеживаемыми.\\n\\nПуть действия от dispatch до обновления состояния\\n\\n- Действие (Action): Пользователь или код инициирует действие, создавая объект action с полем type и опциональными данными (payload).\\n- dispatch(action): Вызов store.dispatch(action) отправляет действие в store.\\n- Reducer: Store передает текущее состояние и action в корневой reducer. Reducer — это чистая функция, которая принимает предыдущее состояние и action, и возвращает новое состояние без мутации исходного.\\n- Обновление store: Store заменяет текущее состояние на новое, возвращенное reducer.\\n- Уведомление подписчиков: Store вызывает всех подписанных слушателей (например, через connect или useSelector в React), что приводит к перерисовке компонентов.\\n\\nПример кода\\n\\nВывод\\nЦикл Redux обеспечивает строгую последовательность: action → dispatch → reducer → новое состояние → обновление UI. Это упрощает отладку, тестирование и поддержку больших приложений, где важно контролировать изменения состояния.","// Action creator\\nconst increment = () => ({ type: 'INCREMENT' });\\n\\n// Reducer\\nconst counterReducer = (state = { count: 0 }, action) => {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return { count: state.count + 1 };\\n    default:\\n      return state;\\n  }\\n};\\n\\n// Store\\nimport { createStore } from 'redux';\\nconst store = createStore(counterReducer);\\n\\n// Dispatch\\nstore.dispatch(increment());\\nconsole.log(store.getState()); // { count: 1 }"],[2560,"createListenerMiddleware — это встроенный middleware в Redux Toolkit, который позволяет запускать побочные эффекты в ответ на действия Redux. Он слушает определенные экшены и выполняет колбэки, что удобно для логирования, навигации или вызовов API. В отличие от createAsyncThunk, он не создает новые экшены, а просто реагирует на существующие.","Что такое createListenerMiddleware?\\ncreateListenerMiddleware — это middleware из Redux Toolkit, который позволяет выполнять произвольный код (побочные эффекты) в ответ на диспатч определенных экшенов. Он похож на саги или эпики, но проще и легче в использовании, так как не требует дополнительных библиотек.\\n\\nКак это работает?\\nMiddleware перехватывает каждый диспатч и проверяет, соответствует ли он заданным условиям (например, типу экшена). Если условие выполняется, запускается колбэк, который может выполнять асинхронные операции, диспатчить другие экшены или взаимодействовать с состоянием.\\n\\nПример использования\\n\\nГде применяется?\\n\\n- Логирование действий пользователя\\n- Навигация после успешного действия (например, редирект после логина)\\n- Синхронизация с localStorage или IndexedDB\\n- Вызов API без создания thunk\\n\\nВывод\\ncreateListenerMiddleware — это удобный инструмент для обработки побочных эффектов в Redux, когда не требуется полная мощь саг или thunk. Он особенно полезен для простых сценариев, где нужно реагировать на действия без изменения логики редьюсеров.","import { createListenerMiddleware, isAnyOf } from '@reduxjs/toolkit';\\nimport { addTodo, removeTodo } from './todosSlice';\\n\\nconst listenerMiddleware = createListenerMiddleware();\\n\\nlistenerMiddleware.startListening({\\n  matcher: isAnyOf(addTodo, removeTodo),\\n  effect: async (action, listenerApi) => {\\n    console.log('Todo изменен:', action);\\n    // Можно диспатчить другие экшены\\n    listenerApi.dispatch({ type: 'log/action', payload: action.type });\\n  },\\n});\\n\\nexport default listenerMiddleware;"],[2561,"React.memo — это компонент высшего порядка, который мемоизирует результат рендеринга компонента, предотвращая его повторный рендер при неизменных пропсах. useMemo — это хук, который мемоизирует результат вычисления функции, предотвращая дорогие вычисления при каждом рендере. React.memo работает на уровне компонента, а useMemo — на уровне значения.","Основное различие\\nReact.memo и useMemo служат для оптимизации производительности, но работают на разных уровнях. React.memo — это компонент высшего порядка (HOC), который оборачивает компонент и предотвращает его повторный рендер, если пропсы не изменились (поверхностное сравнение). useMemo — это хук, который мемоизирует результат выполнения функции и пересчитывает его только при изменении зависимостей.\\n\\nПримеры использования\\nReact.memo применяется к компоненту:\\n\\nuseMemo используется внутри функционального компонента:\\n\\nКогда что применять\\n\\n- React.memo — когда нужно избежать повторного рендера целого компонента при неизменных пропсах.\\n- useMemo — когда нужно избежать дорогих вычислений или сохранить ссылочную стабильность объекта/массива между рендерами.\\n\\nВывод: React.memo оптимизирует рендер компонента, а useMemo — вычисления. Используйте их вместе для максимальной производительности, но не злоупотребляйте, так как мемоизация тоже требует ресурсов.","const MyComponent = React.memo(({ data }) => {\\n  console.log('Rendered');\\n  return <div>{data}</div>;\\n});\\n\\nconst sortedList = useMemo(() => {\\n  return items.sort((a, b) => a - b);\\n}, [items]);"],[2562,"Функциональный компонент перерендеривается при вызове функции-сеттера, возвращаемой useState. React сравнивает новое значение с текущим с помощью Object.is. Если значения разные, компонент и его дочерние элементы перерендериваются. Если одинаковые, ререндер не происходит.","Когда происходит ререндер при использовании useState\\nВ React функциональный компонент перерендеривается каждый раз, когда вызывается функция-сеттер, полученная из хука \`useState\`. Это основной механизм обновления UI в ответ на изменения состояния.\\n\\nМеханизм сравнения\\nReact использует строгое сравнение \`Object.is\` для определения, изменилось ли значение состояния. Если новое значение отличается от предыдущего, компонент перерендеривается. Если значения одинаковы (например, при передаче того же объекта или примитива), ререндер не происходит.\\n\\nПример кода\\n\\nВажные нюансы\\n\\n- При передаче функции в сеттер (например, \`setCount(prev => prev + 1)\`) React гарантирует, что будет использовано актуальное значение состояния.\\n- Если состояние — объект или массив, необходимо создавать новую ссылку, чтобы ререндер произошел. Мутация существующего объекта не вызовет ререндер.\\n- Ререндер компонента также может быть вызван изменением пропсов или контекста.\\n\\nВывод: Используйте useState для локального состояния компонента. Помните, что ререндер происходит только при изменении значения, а не при каждом вызове сеттера. Для сложных состояний используйте функциональную форму обновления.","import React, { useState } from 'react';\\n\\nfunction Counter() {\\n  const [count, setCount] = useState(0);\\n\\n  const handleClick = () => {\\n    setCount(count + 1); // ререндер произойдет\\n  };\\n\\n  const handleSameValue = () => {\\n    setCount(count); // ререндер НЕ произойдет, так как значение не изменилось\\n  };\\n\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={handleClick}>Increment</button>\\n      <button onClick={handleSameValue}>Set same</button>\\n    </div>\\n  );\\n}"],[2563,"useTransition — это хук React, который позволяет пометить обновление состояния как низкоприоритетное. Он помогает избежать блокировки интерфейса при выполнении тяжелых операций, таких как рендеринг больших списков. Хук возвращает кортеж: isPending (флаг ожидания) и startTransition (функция для запуска перехода). Это улучшает пользовательский опыт, делая приложение более отзывчивым.","Что такое useTransition?\\nuseTransition — это хук из React 18, который является частью Concurrent Mode. Он позволяет разработчику указать, что определенное обновление состояния является менее приоритетным и может быть отложено, чтобы не блокировать более срочные взаимодействия пользователя, такие как ввод текста или клики.\\n\\nКак это работает?\\nКогда вы вызываете startTransition, React помечает все обновления состояния внутри него как переходные. React может прервать эти обновления, если появляется более приоритетная задача (например, обновление от ввода). Это предотвращает зависание интерфейса.\\n\\nПример использования\\n\\nГде применять?\\n\\n- Поиск с фильтрацией больших данных\\n- Переключение вкладок с тяжелым контентом\\n- Анимации и переходы между страницами\\n\\nВывод: useTransition полезен, когда нужно сохранить отзывчивость интерфейса при выполнении ресурсоемких операций, особенно в приложениях с частыми обновлениями состояния.","import { useState, useTransition } from 'react';\\n\\nfunction SearchComponent() {\\n  const [query, setQuery] = useState('');\\n  const [results, setResults] = useState([]);\\n  const [isPending, startTransition] = useTransition();\\n\\n  const handleChange = (e) => {\\n    setQuery(e.target.value); // срочное обновление\\n    startTransition(() => {\\n      // низкоприоритетное обновление\\n      setResults(filterData(e.target.value));\\n    });\\n  };\\n\\n  return (\\n    <div>\\n      <input value={query} onChange={handleChange} />\\n      {isPending && <span>Загрузка...</span>}\\n      <ul>{results.map(item => <li key={item.id}>{item.name}</li>)}</ul>\\n    </div>\\n  );\\n}"],[2564,"При каждом рендере создается новый объект массива с новой ссылкой в памяти. Если массив передается как пропс дочернему компоненту, то React.memo не сможет предотвратить ререндер, так как сравнение по ссылке покажет изменение. Это приводит к лишним ререндерам и снижению производительности.","Проблема создания нового массива при каждом рендере\\nВ React при каждом рендере компонента все переменные, объявленные внутри него, создаются заново. Это касается и массивов, и объектов. Даже если содержимое массива не изменилось, создается новый объект с новой ссылкой в памяти.\\n\\nВлияние на дочерние компоненты\\nЕсли такой массив передается как пропс дочернему компоненту, обернутому в React.memo, то мемоизация не сработает. React.memo сравнивает пропсы поверхностно (shallow comparison), то есть по ссылке. Новая ссылка будет расценена как изменение, и дочерний компонент перерендерится, даже если данные не изменились.\\n\\nПример кода\\n\\nКогда это критично\\nПроблема становится заметной при большом количестве дочерних компонентов, сложных вычислениях в них или частых ререндерах родителя. В простых приложениях это может быть незаметно, но в крупных проектах лишние ререндеры могут существенно замедлить работу.\\n\\nВывод\\nИспользуйте useMemo для стабильных массивов и объектов, которые передаются как пропсы в мемоизированные компоненты. Это предотвращает лишние ререндеры и улучшает производительность приложения.","// Плохо: новый массив при каждом рендере\\nfunction Parent() {\\n  const items = ['a', 'b', 'c']; // новая ссылка каждый раз\\n  return <Child list={items} />;\\n}\\n\\n// Хорошо: мемоизация массива\\nfunction Parent() {\\n  const items = useMemo(() => ['a', 'b', 'c'], []);\\n  return <Child list={items} />;\\n}"],[2565,"useMemo кеширует результат вычисления между рендерами. Если зависимости не изменились, возвращается сохранённое значение. Это предотвращает пересоздание массивов и объектов при каждом рендере, что оптимизирует производительность.","Что такое useMemo и зачем он нужен?\\nuseMemo — это хук React, который позволяет мемоизировать (кешировать) результат вычисления между рендерами компонента. Когда компонент перерисовывается, все переменные и функции внутри него создаются заново. Для массивов и объектов это означает, что каждый раз создаётся новый экземпляр, даже если содержимое не изменилось. Это может привести к лишним ререндерам дочерних компонентов, которые зависят от этих данных.\\n\\nКак это работает?\\nuseMemo принимает два аргумента: функцию, возвращающую значение, и массив зависимостей. React запоминает результат функции и возвращает его при повторных рендерах, если зависимости остались прежними. Если зависимости изменились, функция выполняется заново.\\n\\nПример кода\\n\\nКогда применять useMemo?\\nИспользуйте useMemo для дорогих вычислений (например, фильтрация больших массивов, сложные математические операции) или для стабилизации ссылок на объекты/массивы, которые передаются в дочерние компоненты, обёрнутые в React.memo. Однако не стоит мемоизировать всё подряд — это добавляет накладные расходы на сравнение зависимостей. Применяйте только когда есть реальная проблема производительности.\\n\\nВывод: useMemo помогает избежать лишних вычислений и ререндеров, кешируя результат до изменения зависимостей. Это полезно для оптимизации React-приложений, особенно при работе с большими данными или часто перерисовывающимися компонентами.","import React, { useMemo } from 'react';\\n\\nfunction MyComponent({ items, filter }) {\\n  // Без useMemo: каждый рендер создаёт новый массив\\n  // const filteredItems = items.filter(item => item.includes(filter));\\n\\n  // С useMemo: массив пересоздаётся только при изменении items или filter\\n  const filteredItems = useMemo(() => {\\n    return items.filter(item => item.includes(filter));\\n  }, [items, filter]);\\n\\n  return (\\n    <ul>\\n      {filteredItems.map(item => <li key={item}>{item}</li>)}\\n    </ul>\\n  );\\n}"],[2566,"React.memo не гарантирует отсутствие лишних перерендеров при передаче сложных объектов или массивов. Он использует поверхностное сравнение (shallow comparison) пропсов, то есть сравнивает ссылки, а не содержимое. Если при каждом рендере родителя создается новый объект или массив, ссылка меняется, и React.memo считает пропсы измененными, вызывая перерендер дочернего компонента.","Как работает React.memo\\nReact.memo — это компонент высшего порядка, который запоминает результат рендеринга и пропускает повторный рендер, если пропсы не изменились. По умолчанию он использует поверхностное сравнение (shallow comparison) — сравнивает ссылки на объекты, а не их содержимое.\\n\\nПроблема с объектами и массивами\\nЕсли в пропсы передаются сложные объекты или массивы, которые создаются заново при каждом рендере родителя (например, литералы объектов или массивов, результаты вызовов функций), то ссылка на них будет новой. React.memo увидит, что ссылка изменилась, и выполнит перерендер, даже если содержимое объекта или массива осталось прежним.\\n\\nВ этом примере Child будет перерендериваться при каждом изменении count, несмотря на React.memo, потому что объект data создается заново.\\n\\nКак решить проблему\\nЧтобы избежать лишних перерендеров, нужно стабилизировать ссылки на объекты и массивы. Для этого можно использовать:\\n- \`useMemo\` — для мемоизации вычисляемых значений\\n- \`useCallback\` — для мемоизации функций\\n- Вынос констант за пределы компонента\\n\\nВывод\\nReact.memo эффективен только при стабильных ссылках на пропсы. Для сложных объектов и массивов необходимо использовать мемоизацию с помощью useMemo или выносить неизменяемые данные за пределы компонента. В противном случае React.memo не даст ожидаемого эффекта и может даже ухудшить производительность из-за накладных расходов на сравнение.","// Пример: каждый раз создается новый объект\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  const data = { name: 'John' }; // новая ссылка при каждом рендере\\n  return <Child data={data} />;\\n}\\n\\nconst Child = React.memo(({ data }) => {\\n  console.log('Child re-rendered');\\n  return <div>{data.name}</div>;\\n});\\n\\n// Использование useMemo для стабилизации ссылки\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n  const data = useMemo(() => ({ name: 'John' }), []);\\n  return <Child data={data} />;\\n}"],[2567,"Вызов setState внутри компонента помечает его как требующий обновления. React затем ререндерит этот компонент и всех его дочерних компонентов по умолчанию, даже если их пропсы не изменились. Это может привести к ненужным ререндерам, поэтому для оптимизации используют React.memo или shouldComponentUpdate.","Как setState влияет на дочерние компоненты\\nКогда вы вызываете setState в родительском компоненте, React помечает этот компонент как 'грязный' и планирует его ререндер. Во время следующего рендера React создает новое виртуальное DOM-дерево для родителя и всех его дочерних элементов. По умолчанию дочерние компоненты также ререндерятся, даже если их пропсы остались прежними.\\n\\nПочему это происходит\\nReact не сравнивает пропсы автоматически — он просто вызывает функцию рендера для каждого дочернего компонента. Это гарантирует, что UI всегда синхронизирован с состоянием, но может быть избыточным. Например:\\n\\nПри каждом клике Child будет выводить сообщение, хотя его содержимое не меняется.\\n\\nКак оптимизировать\\n\\n- React.memo — оборачивает компонент и предотвращает ререндер, если пропсы не изменились (поверхностное сравнение).\\n- useMemo/useCallback — мемоизируют значения и функции, чтобы пропсы оставались стабильными.\\n- shouldComponentUpdate (в классовых компонентах) — позволяет вручную управлять ререндером.\\n\\nВывод\\nПонимание этого механизма важно для написания производительных React-приложений. Используйте React.memo для компонентов, которые часто ререндерятся без изменения пропсов, и избегайте передачи новых объектов или функций при каждом рендере без необходимости.","function Parent() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <button onClick={() => setCount(count + 1)}>Click</button>\\n      <Child />\\n    </div>\\n  );\\n}\\n\\nfunction Child() {\\n  console.log('Child re-rendered');\\n  return <div>Static content</div>;\\n}"],[2568,"Если дочерние компоненты не обёрнуты в React.memo, то при каждом перерендере родителя они будут перерендериваться независимо от того, изменились ли их пропсы. React по умолчанию перерендеривает все дочерние компоненты рекурсивно. React.memo предотвращает это, выполняя поверхностное сравнение пропсов.","Поведение дочерних компонентов при перерендере родителя\\nВ React, когда родительский компонент перерендеривается (например, из-за изменения состояния или пропсов), все его дочерние компоненты также перерендериваются по умолчанию. Это происходит рекурсивно: каждый дочерний компонент, в свою очередь, перерендеривает своих потомков. Такое поведение гарантирует, что пользовательский интерфейс всегда синхронизирован с текущим состоянием приложения.\\n\\nПример без React.memo\\n\\nПри каждом клике на кнопку оба дочерних компонента будут перерендериваться, даже если их пропсы не изменились. Это видно по выводу в консоль.\\n\\nКак React.memo решает проблему\\nReact.memo — это компонент высшего порядка, который запоминает результат рендеринга. Он выполняет поверхностное сравнение пропсов (shallow comparison) и, если пропсы не изменились, использует сохранённый результат, предотвращая ненужный перерендер.\\n\\nТеперь при изменении состояния родителя дочерние компоненты не будут перерендериваться, если их пропсы остались прежними.\\n\\nВывод\\nИспользуйте React.memo для оптимизации производительности в случаях, когда дочерние компоненты часто перерендериваются из-за изменений в родителе, но их пропсы редко меняются. Однако не стоит оборачивать каждый компонент в React.memo без необходимости, так как это добавляет накладные расходы на сравнение пропсов.","import React, { useState } from 'react';\\n\\nconst Child = ({ name }) => {\\n  console.log('Child rendered:', name);\\n  return <div>{name}</div>;\\n};\\n\\nconst Parent = () => {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <div>\\n      <button onClick={() => setCount(c => c + 1)}>Click</button>\\n      <Child name=\\"Alice\\" />\\n      <Child name=\\"Bob\\" />\\n    </div>\\n  );\\n};\\n\\nconst Child = React.memo(({ name }) => {\\n  console.log('Child rendered:', name);\\n  return <div>{name}</div>;\\n});"],[2569,"При первом монтировании React сначала рендерит родительский компонент, затем дочерние. После завершения рендера всех компонентов в дереве, React синхронно запускает эффекты (useEffect) в порядке от дочерних к родительским. Это гарантирует, что DOM уже обновлен перед выполнением побочных эффектов.","Порядок рендера вложенных React-компонентов при первом монтировании\\nReact использует рекурсивный подход для рендера дерева компонентов. При первом монтировании процесс делится на две фазы: рендер (render phase) и фаза фиксации (commit phase).\\n\\nФаза рендера\\nReact начинает с корневого компонента и вызывает его функцию рендера. Если компонент возвращает дочерние компоненты, React рекурсивно рендерит их, прежде чем завершить рендер родителя. Таким образом, порядок вызова функций рендера идет сверху вниз: сначала родитель, затем его дети, затем внуки и так далее.\\n\\nФаза фиксации и эффекты\\nПосле завершения рендера всех компонентов React обновляет реальный DOM. Затем запускаются эффекты (useEffect). Эффекты выполняются в порядке от дочерних компонентов к родительским (снизу вверх). Это связано с тем, что дочерние эффекты могут зависеть от DOM, созданного родителем.\\n\\nПрактическое применение\\nЭтот порядок важен для корректной работы с побочными эффектами, такими как подписки на события или запросы данных. Например, если дочерний компонент использует данные, полученные в родительском эффекте, это может привести к ошибкам, так как родительский эффект выполняется позже.\\n\\nВывод: Понимание порядка рендера и эффектов помогает избежать багов при работе с вложенными компонентами и зависимостями в useEffect. Всегда учитывайте, что рендер идет сверху вниз, а эффекты — снизу вверх.","function Parent() {\\n  console.log('Parent render');\\n  return <Child />;\\n}\\n\\nfunction Child() {\\n  console.log('Child render');\\n  return <div>Hello</div>;\\n}\\n\\n// Вывод: Parent render, Child render\\n\\nfunction Parent() {\\n  useEffect(() => console.log('Parent effect'));\\n  return <Child />;\\n}\\n\\nfunction Child() {\\n  useEffect(() => console.log('Child effect'));\\n  return <div>Hello</div>;\\n}\\n\\n// Вывод: Child effect, Parent effect"],[2570,"useEffect может имитировать componentDidMount при пустом массиве зависимостей, componentDidUpdate при указании зависимостей, а componentWillUnmount через функцию очистки. Для componentDidMount передайте пустой массив, для componentDidUpdate — массив с отслеживаемыми переменными, для componentWillUnmount верните функцию из useEffect.","Соответствие useEffect методам жизненного цикла\\nХук useEffect в React объединяет функциональность нескольких методов жизненного цикла классовых компонентов. Он позволяет выполнять побочные эффекты после рендеринга компонента и управлять их очисткой.\\n\\ncomponentDidMount\\nДля воспроизведения поведения componentDidMount (выполнение кода один раз после монтирования компонента) используется useEffect с пустым массивом зависимостей:\\n\\ncomponentDidUpdate\\nДля имитации componentDidUpdate (выполнение кода при изменении определённых пропсов или состояния) укажите зависимости в массиве:\\n\\nЕсли нужно выполнять эффект при любом обновлении, опустите массив зависимостей (но это может привести к бесконечному циклу).\\n\\ncomponentWillUnmount\\nДля очистки ресурсов при размонтировании компонента (аналог componentWillUnmount) верните функцию из useEffect:\\n\\nФункция очистки также выполняется перед повторным запуском эффекта, если зависимости изменились.\\n\\nВывод\\nuseEffect — универсальный инструмент для управления побочными эффектами в функциональных компонентах React. Он заменяет componentDidMount, componentDidUpdate и componentWillUnmount, делая код более лаконичным и предсказуемым. Используйте его для работы с API, подписок, таймеров и других асинхронных операций.","useEffect(() => {\\n  // Код выполняется один раз после монтирования\\n  fetchData();\\n}, []);\\n\\nuseEffect(() => {\\n  // Код выполняется при каждом изменении userId\\n  fetchUserData(userId);\\n}, [userId]);\\n\\nuseEffect(() => {\\n  const subscription = subscribeToUpdates();\\n  return () => {\\n    // Очистка при размонтировании\\n    subscription.unsubscribe();\\n  };\\n}, []);"],[2571,"Методы жизненного цикла в классовых компонентах React — это специальные функции, которые автоматически вызываются на разных этапах существования компонента: монтирование, обновление и размонтирование. Основные методы: constructor(), render(), componentDidMount(), componentDidUpdate(), componentWillUnmount(). Они позволяют выполнять инициализацию, обновление данных и очистку ресурсов.","Что такое методы жизненного цикла?\\nВ классовых компонентах React жизненный цикл компонента делится на три фазы: монтирование (создание и вставка в DOM), обновление (при изменении props или state) и размонтирование (удаление из DOM). Для каждой фазы существуют специальные методы, которые React вызывает автоматически. Они дают разработчику контроль над поведением компонента в ключевые моменты.\\n\\nОсновные методы и их применение\\n\\n- constructor(props) — вызывается при создании компонента. Используется для инициализации state и привязки методов. Нельзя вызывать setState().\\n- render() — обязательный метод, возвращает JSX. Должен быть чистой функцией без побочных эффектов.\\n- componentDidMount() — вызывается сразу после монтирования компонента в DOM. Идеально подходит для запросов к API, подписок и установки таймеров.\\n- componentDidUpdate(prevProps, prevState) — вызывается после обновления компонента. Позволяет реагировать на изменения props или state, например, для повторного запроса данных.\\n- componentWillUnmount() — вызывается перед удалением компонента из DOM. Используется для очистки: отписки от событий, остановки таймеров, отмены запросов.\\n\\nПример кода\\n\\nВывод\\nМетоды жизненного цикла в классовых компонентах React предоставляют структурированный способ управления побочными эффектами и состоянием. Они особенно полезны в сложных компонентах, где требуется точный контроль над инициализацией, обновлением и очисткой ресурсов. Однако в современной разработке с функциональными компонентами и хуками (useEffect) эти методы используются реже, но понимание их работы остаётся важным для поддержки legacy-кода и глубокого понимания React.","class Timer extends React.Component {\\n  constructor(props) {\\n    super(props);\\n    this.state = { seconds: 0 };\\n  }\\n\\n  componentDidMount() {\\n    this.interval = setInterval(() => {\\n      this.setState({ seconds: this.state.seconds + 1 });\\n    }, 1000);\\n  }\\n\\n  componentDidUpdate(prevProps, prevState) {\\n    if (this.state.seconds === 10) {\\n      console.log('10 seconds reached');\\n    }\\n  }\\n\\n  componentWillUnmount() {\\n    clearInterval(this.interval);\\n  }\\n\\n  render() {\\n    return <div>Seconds: {this.state.seconds}</div>;\\n  }\\n}"],[2572,"Это методы жизненного цикла классовых компонентов React. componentDidMount вызывается после монтирования компонента, используется для запросов к API и подписок. componentDidUpdate вызывается после обновления пропсов или состояния, позволяет реагировать на изменения. componentWillUnmount вызывается перед удалением компонента, используется для очистки подписок и таймеров. componentDidCatch ловит ошибки в дочерних компонентах и позволяет отобразить запасной UI.","Методы жизненного цикла классовых компонентов React\\nВ классовых компонентах React существуют специальные методы, которые автоматически вызываются на разных этапах жизни компонента: монтирование, обновление, размонтирование и обработка ошибок. Эти методы позволяют разработчику выполнять побочные эффекты, такие как запросы к серверу, подписки или очистку ресурсов.\\n\\ncomponentDidMount\\nВызывается сразу после того, как компонент был вставлен в DOM. Это идеальное место для выполнения запросов к API, установки подписок или инициализации сторонних библиотек.\\n\\ncomponentDidUpdate\\nВызывается после каждого обновления компонента (изменения пропсов или состояния). Позволяет реагировать на изменения, например, обновлять данные при смене ID.\\n\\ncomponentWillUnmount\\nВызывается перед удалением компонента из DOM. Используется для отмены подписок, очистки таймеров или удаления обработчиков событий, чтобы избежать утечек памяти.\\n\\ncomponentDidCatch\\nЛовит ошибки, возникшие в дочерних компонентах (в методах render, lifecycle или конструкторах). Позволяет отобразить запасной UI и залогировать ошибку.\\n\\nВывод: Эти методы необходимы для управления побочными эффектами и ресурсами в классовых компонентах. С появлением хуков в функциональных компонентах их заменили useEffect и Error Boundary, но понимание lifecycle методов важно для работы с легаси-кодом и глубокого понимания React.","class MyComponent extends React.Component {\\n  componentDidMount() {\\n    fetch('/api/data')\\n      .then(res => res.json())\\n      .then(data => this.setState({ data }));\\n  }\\n  render() { return {this.state?.data}; }\\n}\\n\\ncomponentDidUpdate(prevProps) {\\n  if (this.props.userId !== prevProps.userId) {\\n    this.fetchUser(this.props.userId);\\n  }\\n}\\n\\ncomponentWillUnmount() {\\n  clearInterval(this.timer);\\n  this.subscription.unsubscribe();\\n}\\n\\ncomponentDidCatch(error, info) {\\n  console.error('Error caught:', error, info);\\n  this.setState({ hasError: true });\\n}\\nrender() {\\n  if (this.state.hasError) return <h1>Something went wrong.</h1>;\\n  return this.props.children;\\n}"],[2573,"useEffect позволяет выполнять побочные эффекты в функциональных компонентах. Он заменяет методы жизненного цикла componentDidMount, componentDidUpdate и componentWillUnmount. Вы передаёте функцию и массив зависимостей; эффект запускается после рендера и при изменении зависимостей. Возвращаемая функция используется для очистки (например, отписки от событий).","Что такое useEffect и зачем он нужен?\\nuseEffect — это хук в React, который позволяет выполнять побочные эффекты в функциональных компонентах. Побочные эффекты — это операции, которые влияют на внешний мир или зависят от него, например, запросы к API, подписки на события, работа с таймерами или изменение DOM вручную. В классовых компонентах для этого использовались методы жизненного цикла, такие как componentDidMount, componentDidUpdate и componentWillUnmount. useEffect объединяет их в одном API, делая код более чистым и предсказуемым.\\n\\nКак работает useEffect?\\nХук принимает два аргумента: функцию-эффект и необязательный массив зависимостей. Функция-эффект выполняется после каждого рендера компонента, если указанные зависимости изменились. Если массив зависимостей пуст, эффект выполняется только один раз после монтирования. Если зависимости не указаны, эффект запускается после каждого рендера. Функция может возвращать функцию очистки, которая вызывается перед размонтированием компонента или перед повторным запуском эффекта.\\n\\nПримеры использования\\nРассмотрим простой пример: загрузка данных с сервера при монтировании компонента.\\n\\nВ этом примере useEffect выполняет запрос к API при монтировании и каждый раз, когда меняется userId. Если бы мы не указали зависимость, запрос выполнялся бы при каждом рендере, что неэффективно.\\n\\nДругой пример — подписка на событие и её очистка:\\n\\nФункция очистки удаляет обработчик события, предотвращая утечки памяти.\\n\\nВывод\\nuseEffect — это мощный инструмент для управления побочными эффектами в функциональных компонентах React. Он делает код более декларативным и уменьшает дублирование, заменяя несколько методов жизненного цикла одним хуком. Используйте его для всех операций, которые не связаны напрямую с рендерингом, и всегда указывайте правильные зависимости, чтобы избежать неожиданного поведения.","import React, { useState, useEffect } from 'react';\\n\\nfunction UserProfile({ userId }) {\\n  const [user, setUser] = useState(null);\\n\\n  useEffect(() => {\\n    fetch(\`/api/users/\${userId}\`)\\n      .then(response => response.json())\\n      .then(data => setUser(data));\\n  }, [userId]); // эффект запускается при изменении userId\\n\\n  return <div>{user ? user.name : 'Loading...'}</div>;\\n}\\n\\nimport React, { useEffect } from 'react';\\n\\nfunction WindowSizeTracker() {\\n  useEffect(() => {\\n    const handleResize = () => console.log(window.innerWidth);\\n    window.addEventListener('resize', handleResize);\\n\\n    return () => {\\n      window.removeEventListener('resize', handleResize);\\n    };\\n  }, []); // пустой массив — эффект только при монтировании\\n\\n  return <div>Resize the window</div>;\\n}"],[2574,"Рекурсивные компоненты вызывают сами себя для обработки вложенных данных. Компонент принимает массив элементов и для каждого элемента рендерит его содержимое, а затем рекурсивно вызывает себя для дочерних элементов. Важно передавать уникальный ключ каждому элементу и правильно обрабатывать базовый случай, когда дочерних элементов нет.","Что такое рекурсивные компоненты?\\nРекурсивные компоненты — это компоненты, которые вызывают сами себя для обработки вложенных структур данных. Это особенно полезно при работе с деревьями, многоуровневыми меню, комментариями с ответами или файловыми системами.\\n\\nКак это работает?\\nКомпонент принимает массив данных и для каждого элемента рендерит его содержимое. Если у элемента есть дочерние элементы, компонент рекурсивно вызывает себя для их отображения. Базовый случай — отсутствие дочерних элементов, что предотвращает бесконечную рекурсию.\\n\\nПример кода\\n\\nВажные моменты\\n\\n- Всегда передавайте уникальный ключ каждому элементу для эффективного обновления DOM.\\n- Проверяйте наличие дочерних элементов перед рекурсивным вызовом, чтобы избежать ошибок.\\n- Избегайте глубокой вложенности, так как это может привести к проблемам с производительностью.\\n\\nВывод\\nРекурсивные компоненты — мощный инструмент для работы с вложенными данными. Их стоит применять, когда структура данных имеет неопределенную глубину, например, в древовидных меню, файловых системах или многоуровневых комментариях.","function TreeNode({ node }) {\\n  return (\\n    <li>\\n      {node.name}\\n      {node.children && (\\n        <ul>\\n          {node.children.map(child => (\\n            <TreeNode key={child.id} node={child} />\\n          ))}\\n        </ul>\\n      )}\\n    </li>\\n  );\\n}\\n\\nfunction Tree({ data }) {\\n  return (\\n    <ul>\\n      {data.map(node => (\\n        <TreeNode key={node.id} node={node} />\\n      ))}\\n    </ul>\\n  );\\n}"],[2575,"Контролируемая форма в React управляется через состояние компонента. Для каждого поля ввода создается отдельное значение в состоянии, а обработчик onChange обновляет соответствующее поле. Это позволяет React контролировать значения полей и упрощает валидацию и отправку данных.","Что такое контролируемая форма?\\nВ React контролируемая форма — это форма, значения полей которой хранятся в состоянии компонента и обновляются через обработчики событий. React становится единственным источником правды для данных формы, что упрощает управление, валидацию и отправку.\\n\\nРеализация с несколькими полями\\nДля нескольких полей удобно использовать объект в состоянии, где ключи соответствуют именам полей. Обработчик onChange использует атрибут name поля для динамического обновления состояния.\\n\\nПреимущества и применение\\n\\n- Простая валидация: можно проверять данные при каждом изменении.\\n- Легко отправлять данные на сервер: состояние уже содержит все значения.\\n- Удобно для динамических форм, где количество полей может меняться.\\n\\nВывод: контролируемые формы с несколькими полями ввода применяются в React для создания интерактивных и управляемых пользовательских интерфейсов, особенно когда требуется валидация или сложная логика отправки данных.","import React, { useState } from 'react';\\n\\nfunction MyForm() {\\n  const [formData, setFormData] = useState({\\n    username: '',\\n    email: '',\\n    password: ''\\n  });\\n\\n  const handleChange = (e) => {\\n    const { name, value } = e.target;\\n    setFormData(prev => ({ ...prev, [name]: value }));\\n  };\\n\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    console.log(formData);\\n  };\\n\\n  return (\\n    <form onSubmit={handleSubmit}>\\n      <input name=\\"username\\" value={formData.username} onChange={handleChange} />\\n      <input name=\\"email\\" value={formData.email} onChange={handleChange} />\\n      <input name=\\"password\\" type=\\"password\\" value={formData.password} onChange={handleChange} />\\n      <button type=\\"submit\\">Submit</button>\\n    </form>\\n  );\\n}"],[2576,"Вынос функции-обработчика за пределы компонента оправдан, когда она не зависит от пропсов или состояния компонента и не использует замыкания на внутренние переменные. Это позволяет избежать создания новой функции при каждом рендере, что улучшает производительность. Например, статические обработчики событий, такие как обработчики кликов, не требующие доступа к состоянию, можно вынести наружу. Однако если функция зависит от состояния или пропсов, лучше использовать useCallback.","Зачем выносить функцию-обработчик за пределы компонента?\\nВ React при каждом рендере компонента все функции, объявленные внутри него, создаются заново. Это может привести к лишним ререндерам дочерних компонентов, если они получают эти функции как пропсы. Вынос функции за пределы компонента позволяет сохранить ссылку на одну и ту же функцию между рендерами, что оптимизирует производительность.\\n\\nКогда это оправдано?\\n\\n- Функция не использует состояние или пропсы компонента (является чистой и статической).\\n- Функция не зависит от замыканий на внутренние переменные компонента.\\n- Компонент часто ререндерится, и дочерние компоненты используют React.memo или PureComponent.\\n\\nПример кода\\n\\nКогда не стоит выносить?\\nЕсли функция зависит от состояния или пропсов, вынос приведет к потере доступа к актуальным значениям. В таких случаях используйте useCallback с правильными зависимостями.\\n\\nВывод\\nВынос функций-обработчиков за пределы компонента — простой и эффективный способ оптимизации, который стоит применять для статических обработчиков, не зависящих от внутреннего состояния компонента.","// Неоптимизированный вариант: функция создается каждый раз\\nfunction MyComponent() {\\n  const handleClick = () => {\\n    console.log('Clicked');\\n  };\\n  return <button onClick={handleClick}>Click</button>;\\n}\\n\\n// Оптимизированный вариант: функция вынесена за пределы\\nconst handleClick = () => {\\n  console.log('Clicked');\\n};\\n\\nfunction MyComponent() {\\n  return <button onClick={handleClick}>Click</button>;\\n}"],[2577,"Событие onChange срабатывает каждый раз, когда пользователь изменяет значение поля ввода, например, вводит или удаляет символ. В React оно используется для обновления состояния компонента при каждом изменении, что позволяет создавать контролируемые компоненты. Обработчик получает объект события, из которого можно получить текущее значение через event.target.value.","Как работает событие onChange в полях формы\\nСобытие \`onChange\` в HTML и JavaScript срабатывает, когда пользователь изменяет содержимое элемента формы, такого как \`\`, \`\` или \`\`. В отличие от события \`oninput\`, которое срабатывает при каждом изменении, \`onchange\` обычно срабатывает после потери фокуса, но в React оно ведет себя как \`oninput\` и вызывается при каждом изменении значения.\\n\\nИспользование в React\\nВ React событие \`onChange\` используется для создания контролируемых компонентов, где состояние формы хранится в компоненте и обновляется через обработчик. Это позволяет React контролировать значение поля и реагировать на каждое изменение.\\n\\nВ этом примере при каждом вводе символа вызывается \`handleChange\`, который обновляет состояние \`name\`. Поле ввода отображает текущее значение из состояния, что делает его контролируемым.\\n\\nГде применяется\\nСобытие \`onChange\` широко используется в формах для валидации в реальном времени, автозаполнения, поиска с подсказками и других интерактивных элементов. Оно позволяет реагировать на каждое изменение ввода, обеспечивая динамическое обновление интерфейса.\\n\\nВывод\\nИспользуйте \`onChange\` в React для создания контролируемых компонентов, когда необходимо отслеживать и управлять состоянием полей формы в реальном времени. Это особенно полезно для валидации, фильтрации и других сценариев, требующих немедленной реакции на ввод пользователя.","import React, { useState } from 'react';\\n\\nfunction MyForm() {\\n  const [name, setName] = useState('');\\n\\n  const handleChange = (event) => {\\n    setName(event.target.value);\\n  };\\n\\n  return (\\n    <input type=\\"text\\" value={name} onChange={handleChange} />\\n  );\\n}"],[2578,"Вместо нескольких useState для каждого поля формы можно использовать один объект состояния. Для этого создается один хук useState с объектом, содержащим все поля. Обновление происходит через функцию setState с использованием spread-оператора или функционального обновления, чтобы сохранить остальные поля неизменными. Это упрощает код и делает управление формой более централизованным.","Объединение полей формы в один объект состояния\\nВ React для управления формой часто используют несколько хуков useState для каждого поля. Однако это приводит к дублированию кода и усложняет поддержку. Более эффективный подход — хранить все поля в одном объекте состояния. Это позволяет централизованно управлять формой, упрощает сброс, валидацию и отправку данных.\\n\\nКак это работает\\nВместо создания отдельных состояний для каждого поля, вы создаете один объект, где ключи — это имена полей, а значения — их текущие значения. Для обновления используется функция setState, которая принимает новый объект или функцию, возвращающую новый объект на основе предыдущего состояния. Важно использовать spread-оператор (...prevState) или Object.assign, чтобы не потерять другие поля.\\n\\nПример кода\\n\\nПреимущества и применение\\n\\n- Упрощает код: меньше хуков, легче читать и поддерживать.\\n- Удобно для сброса формы: достаточно вызвать setFormData с начальным объектом.\\n- Легко передавать данные в API или для валидации.\\n- Подходит для форм любого размера, особенно с большим количеством полей.\\n\\nВывод: Используйте один объект состояния для формы, когда нужно централизованное управление, упрощение кода и удобство работы с данными. Этот подход особенно полезен в сложных формах с множеством полей.","import React, { useState } from 'react';\\n\\nfunction MyForm() {\\n  const [formData, setFormData] = useState({\\n    username: '',\\n    email: '',\\n    password: ''\\n  });\\n\\n  const handleChange = (e) => {\\n    const { name, value } = e.target;\\n    setFormData(prevState => ({\\n      ...prevState,\\n      [name]: value\\n    }));\\n  };\\n\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    console.log(formData);\\n  };\\n\\n  return (\\n    <form onSubmit={handleSubmit}>\\n      <input name=\\"username\\" value={formData.username} onChange={handleChange} />\\n      <input name=\\"email\\" value={formData.email} onChange={handleChange} />\\n      <input name=\\"password\\" type=\\"password\\" value={formData.password} onChange={handleChange} />\\n      <button type=\\"submit\\">Submit</button>\\n    </form>\\n  );\\n}"],[2579,"Виртуальные списки с переменной высотой элементов требуют динамического измерения высоты каждого элемента. Обычно используется подход с предварительным расчетом позиций на основе известных размеров или с помощью библиотек, которые измеряют высоту после рендеринга. Это позволяет корректно вычислять видимую область и позиционировать элементы, избегая полной отрисовки всего списка.","Основная концепция\\nВиртуальные списки (или виртуализация списков) — это техника, при которой отображается только небольшая часть элементов, видимая в окне просмотра, а остальные элементы заменяются пустыми заполнителями. Когда элементы имеют переменную высоту, стандартные подходы с фиксированной высотой не работают, так как невозможно заранее определить точное положение каждого элемента.\\n\\nМетоды обработки переменной высоты\\n\\n- Предварительное измерение: Все элементы рендерятся один раз (возможно, вне экрана), их высота измеряется и сохраняется в массиве. Затем список использует эти данные для расчета позиций.\\n- Динамическое измерение: Высота измеряется в момент первого появления элемента в видимой области. После измерения позиции последующих элементов корректируются.\\n- Оценка на основе среднего: Используется средняя высота элемента для приблизительного расчета, что может привести к ошибкам прокрутки, но проще в реализации.\\n\\nПример реализации на JavaScript\\n\\nПрименение на практике\\nБиблиотеки, такие как react-window или react-virtualized, предоставляют компоненты для работы с переменной высотой. Например, в react-window используется компонент VariableSizeList, который принимает функцию для получения высоты каждого элемента.\\n\\nВывод\\nВиртуальные списки с переменной высотой необходимы для эффективной работы с динамическими данными, где размер элементов заранее неизвестен. Они широко применяются в чатах, лентах новостей и таблицах с изменяемым содержимым, обеспечивая плавную прокрутку и низкое потребление памяти.","class VirtualList {\\n  constructor(container, items, estimatedHeight = 50) {\\n    this.container = container;\\n    this.items = items;\\n    this.estimatedHeight = estimatedHeight;\\n    this.heights = new Array(items.length).fill(estimatedHeight);\\n    this.positions = [];\\n    this.calculatePositions();\\n  }\\n\\n  calculatePositions() {\\n    let offset = 0;\\n    this.positions = this.heights.map((h) => {\\n      const pos = offset;\\n      offset += h;\\n      return pos;\\n    });\\n  }\\n\\n  updateHeight(index, actualHeight) {\\n    this.heights[index] = actualHeight;\\n    this.calculatePositions();\\n    this.render();\\n  }\\n\\n  render() {\\n    const scrollTop = this.container.scrollTop;\\n    const containerHeight = this.container.clientHeight;\\n    const startIndex = this.findIndex(scrollTop);\\n    const endIndex = this.findIndex(scrollTop + containerHeight);\\n    // отрисовка элементов с startIndex по endIndex\\n  }\\n\\n  findIndex(offset) {\\n    // бинарный поиск по this.positions\\n  }\\n}"],[2580,"Да, в React можно хранить произвольные данные в рефах, не связанные с DOM. useRef создает объект с свойством current, который сохраняется между рендерами. Изменение current не вызывает перерендер компонента. Это удобно для хранения таймеров, предыдущих значений, ссылок на экземпляры классов или любых других мутируемых данных, которые не должны влиять на отображение.","Что такое useRef и как он работает\\nuseRef — это хук React, который возвращает мутабельный объект с единственным свойством current. В отличие от useState, изменение значения current не вызывает повторный рендер компонента. Это делает useRef идеальным для хранения данных, которые должны сохраняться между рендерами, но не влияют на UI.\\n\\nХранение произвольных данных\\nПомимо ссылок на DOM-элементы, useRef может хранить любые данные: числа, строки, объекты, функции, экземпляры классов. Например, можно хранить идентификатор таймера, предыдущее значение пропса или ссылку на внешний сервис.\\n\\nКогда это полезно\\n\\n- Хранение таймеров и интервалов для их последующей очистки\\n- Сохранение предыдущих значений пропсов или состояния для сравнения\\n- Хранение ссылок на внешние библиотеки или экземпляры классов\\n- Кеширование результатов вычислений без лишних рендеров\\n\\nВывод\\nuseRef — это мощный инструмент для хранения мутируемых данных, которые не должны влиять на рендер. Используйте его для таймеров, предыдущих значений и любых данных, которые нужно сохранять между рендерами без вызова обновления компонента.","import { useRef, useEffect } from 'react';\\n\\nfunction Timer() {\\n  const timerRef = useRef(null);\\n  const countRef = useRef(0);\\n\\n  useEffect(() => {\\n    timerRef.current = setInterval(() => {\\n      countRef.current += 1;\\n      console.log('Count:', countRef.current);\\n    }, 1000);\\n\\n    return () => clearInterval(timerRef.current);\\n  }, []);\\n\\n  return <div>Check console</div>;\\n}"],[2581,"Для отправки GET-запроса через HttpClient нужно импортировать HttpClientModule в AppModule, затем внедрить HttpClient в сервис или компонент. Вызовите метод http.get(url), который возвращает Observable. Подпишитесь на него с помощью subscribe() для получения данных или используйте async pipe в шаблоне.","Основы работы с HttpClient в Angular\\nHttpClient — это встроенный сервис Angular для выполнения HTTP-запросов. Он построен на основе RxJS Observable, что позволяет удобно работать с асинхронными данными и применять операторы для трансформации.\\n\\nНастройка и импорт\\nСначала необходимо импортировать HttpClientModule в корневой модуль приложения (обычно AppModule). Это делается в секции imports.\\n\\nОтправка GET-запроса\\nПосле настройки можно внедрить HttpClient в любой сервис или компонент через конструктор. Для отправки GET-запроса используется метод get(), который принимает URL и опциональные параметры.\\n\\nОбработка ответа\\nМетод get() возвращает Observable. Чтобы получить данные, нужно подписаться на него. В компоненте это можно сделать так:\\n\\nТакже можно использовать async pipe в шаблоне для автоматической подписки и отписки.\\n\\nВывод\\nHttpClient упрощает работу с HTTP в Angular, предоставляя типизированные ответы и интеграцию с RxJS. Его стоит применять для всех сетевых запросов в Angular-приложениях, так как он обеспечивает удобную обработку ошибок, перехватчики и тестирование.","import { HttpClientModule } from '@angular/common/http';\\n\\n@NgModule({\\n  imports: [\\n    HttpClientModule\\n  ]\\n})\\nexport class AppModule { }\\n\\nimport { HttpClient } from '@angular/common/http';\\nimport { Injectable } from '@angular/core';\\n\\n@Injectable({ providedIn: 'root' })\\nexport class DataService {\\n  constructor(private http: HttpClient) {}\\n\\n  getUsers() {\\n    return this.http.get('https://api.example.com/users');\\n  }\\n}\\n\\nthis.dataService.getUsers().subscribe({\\n  next: (data) => console.log(data),\\n  error: (err) => console.error(err)\\n});"],[2582,"BehaviorSubject — это разновидность Subject в RxJS, которая хранит последнее значение и передает его новым подписчикам. В отличие от обычного Subject, BehaviorSubject требует начального значения при создании. При подписке BehaviorSubject сразу выдает текущее значение, а Subject — только новые события. Это делает BehaviorSubject удобным для хранения состояния, например, текущего пользователя или темы оформления.","Что такое BehaviorSubject?\\nBehaviorSubject — это специальный тип Subject из библиотеки RxJS, который представляет собой observable, способный хранить текущее значение. При создании BehaviorSubject обязательно передается начальное значение. Когда новый подписчик подписывается на BehaviorSubject, он немедленно получает последнее (или начальное) значение, а затем продолжает получать все последующие обновления.\\n\\nОтличия от обычного Subject\\nОбычный Subject не хранит никакого значения. Он просто передает события всем текущим подписчикам. Если подписчик подписывается после того, как событие уже произошло, он его не получит. BehaviorSubject же всегда хранит последнее значение и выдает его новым подписчикам.\\n\\nПример кода\\n\\nГде применяется\\nBehaviorSubject часто используется для хранения глобального состояния в приложениях, например, текущего пользователя, настроек или темы. Он удобен, когда нужно, чтобы новый компонент сразу получил актуальное состояние без дополнительных запросов.\\n\\nВывод: BehaviorSubject следует применять, когда требуется хранить и передавать текущее состояние новым подписчикам, в отличие от Subject, который подходит только для трансляции событий без сохранения истории.","import { Subject, BehaviorSubject } from 'rxjs';\\n\\nconst subject = new Subject();\\nconst behaviorSubject = new BehaviorSubject('initial');\\n\\nsubject.subscribe(value => console.log('Subject:', value));\\nbehaviorSubject.subscribe(value => console.log('BehaviorSubject:', value));\\n\\nsubject.next('A');\\nbehaviorSubject.next('A');\\n\\n// Новый подписчик после событий\\nsubject.subscribe(value => console.log('Subject late:', value));\\nbehaviorSubject.subscribe(value => console.log('BehaviorSubject late:', value));\\n\\n// Вывод:\\n// Subject: A\\n// BehaviorSubject: initial\\n// BehaviorSubject: A\\n// BehaviorSubject late: A\\n// Subject late: (ничего)"],[2583,"Чтобы получить значение из события ввода, используйте event.target.value. Когда пользователь вводит текст в поле, браузер создает объект события. Свойство target указывает на элемент, вызвавший событие, а value содержит текущее текстовое значение этого элемента. Это стандартный способ доступа к данным формы в React и нативном JavaScript.","Как работает event.target.value\\nКогда пользователь взаимодействует с элементом формы (например, вводит текст в \`\`), браузер генерирует событие. Объект события содержит информацию о произошедшем действии. Свойство \`target\` ссылается на DOM-элемент, который инициировал событие. У этого элемента есть свойство \`value\`, которое хранит текущее содержимое поля ввода.\\n\\nПример использования в нативном JavaScript\\n\\nВ этом примере при каждом вводе символа в поле с id 'myInput' вызывается функция, которая получает значение поля через \`event.target.value\` и выводит его в консоль.\\n\\nИспользование в React\\nВ React обработка событий похожа, но используется синтаксис JSX. Обычно значение сохраняется в состояние компонента:\\n\\nЗдесь \`event.target.value\` получает новое значение поля, которое затем обновляет состояние компонента через \`setText\`. Это позволяет React контролировать значение поля и реагировать на изменения.\\n\\nГде применяется\\n\\n- Формы обратной связи, регистрации, входа\\n- Поисковые строки с автодополнением\\n- Редакторы текста и поля ввода данных\\n\\nВывод: \`event.target.value\` — это основной способ получения данных из полей ввода в веб-разработке. Он используется как в нативном JavaScript, так и в современных фреймворках (React, Vue, Angular) для обработки пользовательского ввода и управления состоянием формы.","document.getElementById('myInput').addEventListener('input', function(event) {\\n  const inputValue = event.target.value;\\n  console.log('Текущее значение:', inputValue);\\n});\\n\\nfunction MyComponent() {\\n  const [text, setText] = useState('');\\n\\n  const handleChange = (event) => {\\n    setText(event.target.value);\\n  };\\n\\n  return <input type=\\"text\\" value={text} onChange={handleChange} />;\\n}"],[2584,"useEffect гарантирует, что запрос выполняется после рендера, а не во время него, что предотвращает блокировку UI и обеспечивает синхронизацию с актуальным состоянием. Обработчик onChange вызывается синхронно при каждом изменении, что может привести к множественным ненужным запросам и проблемам с производительностью. useEffect также позволяет легко управлять отменой запросов и зависимостями.","Почему useEffect, а не onChange?\\nВ React обработчики событий, такие как onChange, выполняются синхронно во время рендера. Если в них разместить fetch, то каждый раз при изменении поля ввода будет запускаться новый запрос, что может привести к лавине запросов и ухудшению производительности. Кроме того, состояние компонента может измениться до завершения запроса, что приведет к гонке данных.\\n\\nРоль useEffect\\nХук useEffect предназначен для выполнения побочных эффектов после того, как компонент отрендерился. Это гарантирует, что запросы данных не блокируют рендер и выполняются только при изменении указанных зависимостей. useEffect также предоставляет механизм очистки (cleanup), который позволяет отменять предыдущие запросы, если зависимость изменилась до их завершения.\\n\\nПример кода\\n\\nВывод\\nИспользование useEffect для запросов при изменении состояния обеспечивает предсказуемое поведение, предотвращает гонки данных и позволяет эффективно управлять отменой запросов. Это особенно полезно в сценариях поиска с автодополнением или фильтрации, где важна производительность и актуальность данных.","import { useState, useEffect } from 'react';\\n\\nfunction SearchComponent() {\\n  const [query, setQuery] = useState('');\\n  const [results, setResults] = useState([]);\\n\\n  useEffect(() => {\\n    if (!query) return;\\n    const controller = new AbortController();\\n    const fetchData = async () => {\\n      try {\\n        const res = await fetch(\`/api/search?q=\${query}\`, {\\n          signal: controller.signal\\n        });\\n        const data = await res.json();\\n        setResults(data);\\n      } catch (err) {\\n        if (err.name !== 'AbortError') console.error(err);\\n      }\\n    };\\n    fetchData();\\n    return () => controller.abort(); // отмена предыдущего запроса\\n  }, [query]);\\n\\n  return (\\n    <input value={query} onChange={(e) => setQuery(e.target.value)} />\\n  );\\n}"],[2585,"Effector — это реактивный стейт-менеджер, основанный на событиях и стримах, в отличие от Redux, который использует действия и редьюсеры. В Effector нет единого хранилища, вместо этого используются независимые сторы, которые обновляются через события. Основные отличия: встроенная поддержка асинхронности через эффекты, отсутствие бойлерплейта и более простая работа с зависимостями.","Основная концепция Effector\\nEffector — это современный стейт-менеджер для JavaScript-приложений, который использует реактивный подход. В отличие от Redux, где состояние управляется через действия (actions) и редьюсеры (reducers), Effector опирается на события (events) и сторы (stores). События — это функции, которые могут изменять состояние сторов, а сторы — это реактивные контейнеры данных, которые автоматически уведомляют подписчиков об изменениях.\\n\\nКлючевые отличия от Redux\\n\\n- Архитектура: В Redux есть единое глобальное хранилище (store), а в Effector можно создавать множество независимых сторов, что упрощает модульность.\\n- Асинхронность: Effector предоставляет встроенные эффекты (effects) для работы с асинхронными операциями, такими как запросы к API, без необходимости использовать middleware (например, Redux Thunk).\\n- Бойлерплейт: В Redux требуется много шаблонного кода (типы действий, создатели действий, редьюсеры), в Effector код более лаконичный.\\n- Реактивность: Effector использует реактивные связи между сторами и событиями, что позволяет автоматически обновлять данные при изменении зависимостей.\\n\\nПример кода\\n\\nГде применяется\\nEffector хорошо подходит для сложных приложений с большим количеством взаимосвязанных состояний, где важна производительность и предсказуемость. Он часто используется в React-проектах, где требуется гибкое управление состоянием без излишнего бойлерплейта.\\n\\nВывод: Effector стоит применять, когда нужно быстрое и реактивное управление состоянием с минимальным шаблонным кодом, особенно в проектах с частыми асинхронными операциями и сложными зависимостями данных.","import { createStore, createEvent, createEffect } from 'effector';\\n\\n// Создаём событие\\nconst increment = createEvent();\\n\\n// Создаём стор с начальным значением\\nconst counter = createStore(0)\\n  .on(increment, (state) => state + 1);\\n\\n// Создаём эффект для асинхронного запроса\\nconst fetchUser = createEffect(async (id) => {\\n  const response = await fetch(\`/api/users/\${id}\`);\\n  return response.json();\\n});\\n\\n// Подписываемся на изменения стора\\ncounter.watch((value) => console.log('Counter:', value));\\n\\n// Вызываем событие\\nincrement(); // Counter: 1"],[2586,"Yup — это библиотека для валидации данных на основе схем. Она позволяет описывать правила проверки объектов, строк, чисел и других типов. Чаще всего используется с формами в React для проверки ввода пользователя перед отправкой.","Назначение Yup\\nYup — это библиотека для создания и выполнения схем валидации данных в JavaScript. Она предоставляет декларативный API для описания правил проверки значений, таких как строки, числа, массивы и объекты. Основная цель Yup — упростить валидацию данных, особенно в формах, делая код более читаемым и поддерживаемым.\\n\\nКак это работает\\nВы определяете схему, которая описывает ожидаемую структуру данных и правила для каждого поля. Затем вызываете метод \`validate\` или \`isValid\`, чтобы проверить, соответствует ли объект схеме. Если данные не проходят проверку, Yup возвращает понятные сообщения об ошибках.\\n\\nПример использования\\n\\nГде применяется\\nYup часто используется вместе с библиотеками управления формами, такими как Formik или React Hook Form. Это позволяет централизованно описывать правила валидации и автоматически отображать ошибки рядом с полями ввода.\\n\\nВывод\\nYup полезен для создания надежной и понятной валидации данных в веб-приложениях, особенно при работе с формами. Он помогает избежать дублирования кода и упрощает обработку ошибок.","import * as yup from 'yup';\\n\\nconst schema = yup.object().shape({\\n  name: yup.string().required('Имя обязательно'),\\n  age: yup.number().positive().integer(),\\n  email: yup.string().email('Некорректный email'),\\n});\\n\\nschema.validate({ name: 'Анна', age: 25, email: 'anna@test.com' })\\n  .then(() => console.log('Валидация пройдена'))\\n  .catch(err => console.log(err.errors));"],[2587,"React Query автоматически кэширует результаты запросов, используя уникальные ключи запросов. Данные считаются свежими в течение заданного staleTime, после чего помечаются устаревшими и могут быть повторно запрошены при повторном монтировании компонента или по таймеру. Кэш хранится в памяти и может быть настроен с помощью опций gcTime (ранее cacheTime) для управления временем хранения неиспользуемых данных.","Основы кэширования в React Query\\nReact Query (TanStack Query) предоставляет мощный механизм кэширования данных, получаемых с сервера. Каждый запрос идентифицируется уникальным ключом (query key), который используется для хранения и извлечения данных из кэша. Кэш хранится в памяти приложения и управляется автоматически.\\n\\nКлючевые концепции\\n\\n- staleTime — время в миллисекундах, в течение которого данные считаются свежими. По умолчанию 0, что означает, что данные сразу помечаются устаревшими.\\n- gcTime (ранее cacheTime) — время, в течение которого неиспользуемые данные остаются в кэше перед удалением. По умолчанию 5 минут.\\n- refetchOnMount — автоматический повторный запрос при монтировании компонента, если данные устарели.\\n- refetchOnWindowFocus — повторный запрос при фокусе окна браузера.\\n\\nПример настройки кэширования\\n\\nИнвалидация кэша\\nДля обновления данных после мутации используется инвалидация кэша с помощью queryClient.invalidateQueries. Это помечает данные как устаревшие и инициирует повторный запрос.\\n\\nВывод\\nКэширование в React Query позволяет значительно сократить количество запросов к серверу, улучшить производительность и обеспечить актуальность данных. Рекомендуется использовать staleTime для данных, которые редко меняются, и gcTime для управления памятью.","import { useQuery } from '@tanstack/react-query';\\n\\nfunction useTodos() {\\n  return useQuery({\\n    queryKey: ['todos'],\\n    queryFn: fetchTodos,\\n    staleTime: 5 * 60 * 1000, // 5 минут данные считаются свежими\\n    gcTime: 10 * 60 * 1000,   // 10 минут данные хранятся в кэше после удаления компонента\\n  });\\n}\\n\\nimport { useMutation, useQueryClient } from '@tanstack/react-query';\\n\\nfunction useAddTodo() {\\n  const queryClient = useQueryClient();\\n  return useMutation({\\n    mutationFn: addTodo,\\n    onSuccess: () => {\\n      queryClient.invalidateQueries({ queryKey: ['todos'] });\\n    },\\n  });\\n}"],[2588,"Если не указать key при рендере списка в React, появится предупреждение: \\"Warning: Each child in a list should have a unique 'key' prop.\\" Это предупреждение указывает на то, что React не может эффективно отслеживать изменения элементов списка. Без key React будет перерисовывать весь список при каждом обновлении, что снижает производительность.","Что такое key в React?\\nАтрибут \`key\` — это специальный строковый атрибут, который помогает React идентифицировать каждый элемент в списке. Когда вы рендерите массив данных с помощью \`map()\`, React использует \`key\` для сопоставления элементов до и после обновления. Это ключевая часть процесса согласования (reconciliation), который позволяет React минимизировать изменения в реальном DOM.\\n\\nПочему возникает предупреждение?\\nЕсли \`key\` не указан, React выводит предупреждение в консоль браузера: \`Warning: Each child in a list should have a unique 'key' prop.\` Это не ошибка, а рекомендация. Без \`key\` React использует индекс элемента в массиве как неявный ключ, что может привести к неправильному обновлению состояния компонентов, особенно при добавлении, удалении или перестановке элементов.\\n\\nПример кода с предупреждением\\n\\nКак правильно использовать key\\nИспользуйте уникальный идентификатор из данных, например \`id\`:\\n\\nЕсли уникального id нет, можно использовать индекс, но это крайний случай, так как индекс нестабилен при изменении списка.\\n\\nВывод\\nВсегда указывайте \`key\` при рендере списков в React, используя стабильные уникальные идентификаторы. Это улучшает производительность и предотвращает ошибки обновления состояния, особенно в динамических списках с добавлением или удалением элементов.","function TodoList() {\\n  const items = ['Купить молоко', 'Позвонить другу', 'Сделать ДЗ'];\\n  return (\\n    <ul>\\n      {items.map((item) => (\\n        <li>{item}</li>  // key не указан — будет предупреждение\\n      ))}\\n    </ul>\\n  );\\n}\\n\\nfunction TodoList() {\\n  const items = [\\n    { id: 1, text: 'Купить молоко' },\\n    { id: 2, text: 'Позвонить другу' },\\n  ];\\n  return (\\n    <ul>\\n      {items.map((item) => (\\n        <li key={item.id}>{item.text}</li>\\n      ))}\\n    </ul>\\n  );\\n}"],[2589,"React Hook Form использует неконтролируемые компоненты и минимизирует количество ререндеров, что делает её более производительной. Final Form основана на контролируемых компонентах и предоставляет более гибкую архитектуру с подписками на изменения. React Hook Form проще в интеграции с TypeScript и имеет меньший размер бандла.","Основные различия между React Hook Form и Final Form\\nReact Hook Form и Final Form — это две популярные библиотеки для управления формами в React, но они имеют принципиально разные подходы к работе. React Hook Form построена на неконтролируемых компонентах, что позволяет избежать лишних ререндеров и повысить производительность. Final Form, напротив, использует контролируемые компоненты и предоставляет более детальный контроль над состоянием формы через подписки.\\n\\nАрхитектура и производительность\\nReact Hook Form минимизирует количество ререндеров, так как она не хранит состояние формы в React state, а использует ref для доступа к значениям полей. Это особенно полезно для больших форм с множеством полей. Final Form использует подписки на изменения, что позволяет обновлять только те компоненты, которые подписаны на конкретные поля, но всё равно может быть менее производительной на очень больших формах.\\n\\nПример кода\\n\\nИнтеграция и экосистема\\nReact Hook Form имеет встроенную поддержку TypeScript и легко интегрируется с UI-библиотеками, такими как Material-UI или Ant Design. Final Form также поддерживает TypeScript, но требует больше ручной настройки для работы с внешними компонентами. React Hook Form имеет меньший размер бандла (около 8KB), что делает её предпочтительной для проектов, где важна производительность загрузки.\\n\\nВывод: React Hook Form лучше подходит для проектов, где важна производительность и простота использования, особенно с TypeScript. Final Form стоит выбирать, если требуется более гибкая архитектура с детальным контролем над подписками и состоянием формы.","// React Hook Form\\nimport { useForm } from 'react-hook-form';\\n\\nfunction MyForm() {\\n  const { register, handleSubmit } = useForm();\\n  const onSubmit = (data) => console.log(data);\\n\\n  return (\\n    <form onSubmit={handleSubmit(onSubmit)}>\\n      <input {...register('name')} />\\n      <button type=\\"submit\\">Submit</button>\\n    </form>\\n  );\\n}\\n\\n// Final Form\\nimport { Form, Field } from 'react-final-form';\\n\\nfunction MyForm() {\\n  const onSubmit = (values) => console.log(values);\\n\\n  return (\\n    <Form onSubmit={onSubmit}>\\n      {({ handleSubmit }) => (\\n        <form onSubmit={handleSubmit}>\\n          <Field name=\\"name\\">\\n            {({ input }) => <input {...input} />}\\n          </Field>\\n          <button type=\\"submit\\">Submit</button>\\n        </form>\\n      )}\\n    </Form>\\n  );\\n}"],[2590,"В React доступ к неуправляемому компоненту осуществляется через рефы. Создайте реф с помощью useRef и прикрепите его к элементу через атрибут ref. Затем обращайтесь к текущему значению через ref.current.value. Это позволяет получать данные напрямую из DOM, минуя состояние React.","Что такое неуправляемые компоненты?\\nНеуправляемые компоненты в React — это элементы формы, которые хранят своё состояние в DOM, а не в состоянии React. В отличие от управляемых компонентов, где каждое изменение поля синхронизируется с состоянием через onChange, неуправляемые компоненты полагаются на рефы для доступа к текущим значениям.\\n\\nКак получить доступ?\\nДля доступа к неуправляемому компоненту используется хук \`useRef\`. Он создаёт объект с свойством \`current\`, которое ссылается на DOM-элемент. Пример:\\n\\nВ этом примере \`inputRef\` прикрепляется к полю ввода. При отправке формы мы получаем значение через \`inputRef.current.value\`.\\n\\nКогда использовать?\\nНеуправляемые компоненты полезны для простых форм, где не требуется мгновенная валидация или сложная логика. Они также удобны при интеграции с библиотеками, управляющими DOM напрямую. Однако для сложных форм с динамическими изменениями лучше использовать управляемые компоненты.\\n\\nВывод: используйте неуправляемые компоненты и рефы для быстрого доступа к данным формы, когда не нужен полный контроль над каждым изменением.","import React, { useRef } from 'react';\\n\\nfunction MyForm() {\\n  const inputRef = useRef(null);\\n\\n  const handleSubmit = (e) => {\\n    e.preventDefault();\\n    alert('Значение: ' + inputRef.current.value);\\n  };\\n\\n  return (\\n    <form onSubmit={handleSubmit}>\\n      <input ref={inputRef} type=\\"text\\" />\\n      <button type=\\"submit\\">Отправить</button>\\n    </form>\\n  );\\n}"],[2591,"Управляемые компоненты хранят своё состояние в React через useState и обновляются через onChange. Неуправляемые компоненты используют ref для доступа к DOM-элементу напрямую, а состояние хранится в самом DOM. Управляемые дают больше контроля и предсказуемости, неуправляемые проще для простых форм.","Основное различие\\nУправляемые (controlled) и неуправляемые (uncontrolled) компоненты — это два подхода к работе с формами в React. В управляемых компонентах состояние поля ввода хранится в React-компоненте через \`useState\`, и каждое изменение обновляет это состояние через обработчик \`onChange\`. В неуправляемых компонентах состояние хранится в самом DOM, и для доступа к значению используется \`useRef\`.\\n\\nПример управляемого компонента\\n\\nПример неуправляемого компонента\\n\\nКогда что использовать\\n\\n- Управляемые компоненты: когда нужен мгновенный контроль над вводом (валидация, маски, динамические изменения).\\n- Неуправляемые компоненты: для простых форм без сложной логики, где не нужно отслеживать каждое изменение.\\n\\nВывод: управляемые компоненты предпочтительнее в большинстве случаев, так как они делают состояние предсказуемым и упрощают тестирование. Неуправляемые компоненты могут быть полезны для интеграции с не-React кодом или для очень простых полей.","import React, { useState } from 'react';\\n\\nfunction ControlledInput() {\\n  const [value, setValue] = useState('');\\n\\n  const handleChange = (e) => setValue(e.target.value);\\n\\n  return (\\n    <input\\n      type=\\"text\\"\\n      value={value}\\n      onChange={handleChange}\\n    />\\n  );\\n}\\n\\nimport React, { useRef } from 'react';\\n\\nfunction UncontrolledInput() {\\n  const inputRef = useRef(null);\\n\\n  const handleSubmit = () => {\\n    alert(inputRef.current.value);\\n  };\\n\\n  return (\\n    <div>\\n      <input type=\\"text\\" ref={inputRef} />\\n      <button onClick={handleSubmit}>Submit</button>\\n    </div>\\n  );\\n}"],[2592,"Метод shouldComponentUpdate в классовых компонентах по смыслу аналогичен React.memo. Он позволяет предотвратить повторный рендеринг компонента, если пропсы не изменились. React.memo делает то же самое для функциональных компонентов, оборачивая их и выполняя поверхностное сравнение пропсов.","Связь shouldComponentUpdate и React.memo\\nВ React классовые компоненты имеют метод жизненного цикла \`shouldComponentUpdate\`, который вызывается перед рендерингом, когда компонент получает новые пропсы или состояние. Этот метод возвращает \`true\` (по умолчанию) или \`false\`. Если он возвращает \`false\`, рендеринг и последующие методы жизненного цикла пропускаются. Это позволяет оптимизировать производительность, избегая ненужных обновлений.\\n\\n\`React.memo\` — это функция высшего порядка для функциональных компонентов. Она оборачивает компонент и выполняет поверхностное сравнение предыдущих и новых пропсов. Если пропсы не изменились, компонент не перерендеривается. По сути, \`React.memo\` автоматически реализует логику \`shouldComponentUpdate\` с поверхностным сравнением.\\n\\nПримеры кода\\nКлассовый компонент с shouldComponentUpdate:\\n\\nФункциональный компонент с React.memo:\\n\\nЕсли нужно кастомное сравнение, \`React.memo\` принимает второй аргумент — функцию сравнения:\\n\\nВывод\\nИспользуйте \`shouldComponentUpdate\` в классовых компонентах и \`React.memo\` в функциональных для предотвращения лишних рендеров, когда пропсы редко меняются. Это особенно полезно для компонентов, которые рендерят тяжелые элементы или часто обновляются.","class MyComponent extends React.Component {\\n  shouldComponentUpdate(nextProps) {\\n    // Сравниваем только нужные пропсы\\n    return nextProps.value !== this.props.value;\\n  }\\n\\n  render() {\\n    return <div>{this.props.value}</div>;\\n  }\\n}\\n\\nconst MyComponent = React.memo(({ value }) => {\\n  return <div>{value}</div>\\n});\\n// По умолчанию поверхностное сравнение пропсов\\n\\nconst MyComponent = React.memo(\\n  ({ value }) => <div>{value}</div>,\\n  (prevProps, nextProps) => prevProps.value === nextProps.value\\n);"],[2593,"В React используется однонаправленный поток данных (unidirectional data flow). Данные передаются от родительских компонентов к дочерним через props. Для обратной связи дочерние компоненты вызывают колбэки, переданные через props. Состояние поднимается вверх по иерархии (lifting state up), чтобы несколько компонентов могли его разделять.","Однонаправленный поток данных в React\\nReact использует однонаправленный поток данных (unidirectional data flow). Это означает, что данные передаются только сверху вниз — от родительских компонентов к дочерним. Такой подход упрощает отладку и делает предсказуемым поведение приложения.\\n\\nКак это работает\\nРодительский компонент передает данные дочернему через атрибуты, называемые props. Дочерний компонент не может напрямую изменять эти данные. Если нужно изменить состояние, дочерний компонент вызывает функцию-колбэк, переданную через props, которая обновляет состояние в родителе.\\n\\nПочему это важно\\nОднонаправленный поток данных предотвращает хаотичные изменения состояния, которые сложно отследить. Каждый компонент получает данные только от родителя и не может их изменить напрямую. Это делает код более предсказуемым и упрощает рефакторинг.\\n\\nВывод\\nОднонаправленный поток данных в React — это фундаментальный принцип, который обеспечивает стабильность и предсказуемость приложения. Его стоит применять во всех React-проектах для упрощения управления состоянием и отладки.","// Родительский компонент\\nfunction Parent() {\\n  const [count, setCount] = useState(0);\\n\\n  const increment = () => setCount(count + 1);\\n\\n  return <Child count={count} onIncrement={increment} />;\\n}\\n\\n// Дочерний компонент\\nfunction Child({ count, onIncrement }) {\\n  return (\\n    <div>\\n      <p>Count: {count}</p>\\n      <button onClick={onIncrement}>+1</button>\\n    </div>\\n  );\\n}"],[2594,"Prop drilling возникает, когда данные передаются через несколько уровней компонентов, даже если промежуточные компоненты их не используют. Это делает код громоздким и сложным для поддержки. Стейт-менеджеры (например, Redux, Zustand) или Context API позволяют хранить глобальное состояние и предоставлять его напрямую нужным компонентам, минуя промежуточные звенья.","Проблема prop drilling\\nВ React данные передаются от родительского компонента к дочерним через пропсы. Когда приложение разрастается, возникает ситуация, когда пропсы нужно передать через несколько уровней вложенности, хотя промежуточные компоненты их не используют. Это называется prop drilling. Такой подход усложняет рефакторинг, увеличивает связанность компонентов и делает код менее читаемым.\\n\\nКак стейт-менеджеры решают эту проблему\\nСтейт-менеджеры (например, Redux, MobX, Zustand) или встроенный Context API предоставляют механизм для хранения глобального состояния, доступного любому компоненту без явной передачи через пропсы. Компонент может подписаться на нужную часть состояния и получать обновления автоматически.\\n\\nПример с Context API\\n\\nВ этом примере Toolbar не получает пропсы, а ThemedButton напрямую использует контекст. Это устраняет prop drilling.\\n\\nВывод\\nСтейт-менеджеры и Context API решают проблему prop drilling, упрощая архитектуру приложения и делая код более поддерживаемым. Их стоит применять, когда данные используются многими компонентами на разных уровнях вложенности, чтобы избежать излишней передачи пропсов.","import React, { createContext, useContext, useState } from 'react';\\n\\nconst ThemeContext = createContext();\\n\\nfunction App() {\\n  const [theme, setTheme] = useState('light');\\n  return (\\n    <ThemeContext.Provider value={{ theme, setTheme }}>\\n      <Toolbar />\\n    </ThemeContext.Provider>\\n  );\\n}\\n\\nfunction Toolbar() {\\n  return <ThemedButton />;\\n}\\n\\nfunction ThemedButton() {\\n  const { theme, setTheme } = useContext(ThemeContext);\\n  return (\\n    <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>\\n      Current theme: {theme}\\n    </button>\\n  );\\n}"],[2595,"HOC — это функция, которая принимает компонент и возвращает новый компонент с дополнительными свойствами или логикой. В стейт-менеджерах, например в Redux, HOC \`connect\` используется для подписки компонента на хранилище и передачи ему части состояния и действий. Это позволяет отделить логику управления состоянием от представления, делая код более модульным и переиспользуемым.","Что такое HOC и как он работает в стейт-менеджерах?\\nHigher-Order Component (HOC) — это паттерн в React, который представляет собой функцию, принимающую компонент и возвращающую новый компонент с расширенной функциональностью. В контексте стейт-менеджеров, таких как Redux, HOC используется для связывания компонента с глобальным состоянием приложения.\\n\\nПример с Redux connect\\nНаиболее известный пример — функция \`connect\` из библиотеки \`react-redux\`. Она принимает две функции: \`mapStateToProps\` и \`mapDispatchToProps\`, и возвращает HOC, который оборачивает ваш компонент. Внутри HOC подписывается на store Redux и передаёт нужные данные и действия через props.\\n\\nКак это работает внутри?\\nHOC, созданный \`connect\`, внутри себя использует \`React.Context\` или прямой доступ к store (через \`useStore\` в современных версиях). Он отслеживает изменения в store и при обновлении состояния перерисовывает обёрнутый компонент, передавая ему новые props. Это позволяет компоненту оставаться \\"глупым\\" (чисто презентационным), не зная о существовании Redux.\\n\\nПрименение в других стейт-менеджерах\\nАналогичный подход используется в MobX (через \`observer\` HOC) или в библиотеках для работы с Context (например, \`withTheme\`). HOC позволяет инкапсулировать логику подписки на состояние и делает компоненты более переиспользуемыми.\\n\\nВывод: HOC в стейт-менеджерах — это мощный инструмент для разделения ответственности между управлением состоянием и отображением UI. Он особенно полезен в больших приложениях, где требуется централизованное состояние и чистая архитектура компонентов.","import { connect } from 'react-redux';\\n\\nconst mapStateToProps = (state) => ({\\n  count: state.counter.value\\n});\\n\\nconst mapDispatchToProps = (dispatch) => ({\\n  increment: () => dispatch({ type: 'INCREMENT' })\\n});\\n\\nconst Counter = ({ count, increment }) => (\\n  <div>\\n    <p>{count}</p>\\n    <button onClick={increment}>+</button>\\n  </div>\\n);\\n\\nexport default connect(mapStateToProps, mapDispatchToProps)(Counter);"],[2596,"В React данные передаются от родителя к ребенку через props. Чтобы передать данные обратно, родитель передает функцию-колбэк как prop. Дочерний компонент вызывает эту функцию с нужными данными, и родитель получает их в своем обработчике. Это называется подъемом состояния (lifting state up).","Передача данных из дочернего компонента в родительский в React\\nВ React данные обычно движутся сверху вниз — от родителя к дочерним компонентам через props. Однако часто возникает необходимость передать информацию обратно, например, когда пользователь вводит текст в поле внутри дочернего компонента, и родитель должен узнать это значение. Для этого используется механизм колбэков.\\n\\nКак это работает\\nРодительский компонент определяет функцию-обработчик и передает её дочернему компоненту как prop. Дочерний компонент вызывает эту функцию, передавая в неё данные (например, значение из input). Родитель получает эти данные в своей функции и может обновить своё состояние или выполнить другие действия.\\n\\nПример кода\\n\\nГде это применяется\\n\\n- Формы: когда нужно собрать данные из нескольких полей ввода и передать их наверх.\\n- Списки: при клике на элемент списка нужно сообщить родителю, какой элемент выбран.\\n- Модальные окна: при закрытии модального окна передать результат (например, подтверждение).\\n\\nВывод\\nПередача данных через колбэки — это стандартный и простой способ организовать обратную связь от дочернего компонента к родительскому. Этот подход следует использовать, когда нужно поднять состояние на уровень выше для совместного использования данных несколькими компонентами.","// Родительский компонент\\nfunction Parent() {\\n  const [childData, setChildData] = useState('');\\n\\n  const handleDataFromChild = (data) => {\\n    setChildData(data);\\n  };\\n\\n  return (\\n    <div>\\n      <h1>Данные от ребенка: {childData}</h1>\\n      <Child onSendData={handleDataFromChild} />\\n    </div>\\n  );\\n}\\n\\n// Дочерний компонент\\nfunction Child({ onSendData }) {\\n  const [inputValue, setInputValue] = useState('');\\n\\n  const handleClick = () => {\\n    onSendData(inputValue); // Передаём данные родителю\\n  };\\n\\n  return (\\n    <div>\\n      <input\\n        type=\\"text\\"\\n        value={inputValue}\\n        onChange={(e) => setInputValue(e.target.value)}\\n      />\\n      <button onClick={handleClick}>Отправить родителю</button>\\n    </div>\\n  );\\n}"],[2597,"HOC — это функция, которая принимает компонент и возвращает новый компонент с дополнительной логикой. Он решает проблему дублирования кода, когда несколько компонентов используют одинаковую бизнес-логику, например, подписку на данные или обработку авторизации. HOC оборачивает компонент, добавляя ему props или поведение, что позволяет избежать повторения кода и улучшает поддерживаемость.","Что такое HOC и какую проблему он решает?\\nHigher-Order Component (HOC) — это паттерн в React, который позволяет переиспользовать логику между компонентами. Если множество компонентов содержат одинаковую бизнес-логику, например, загрузку данных из API, проверку прав доступа или подписку на события, то без HOC пришлось бы дублировать эту логику в каждом компоненте. HOC решает эту проблему, выступая в роли обертки: он принимает компонент и возвращает новый компонент с добавленными свойствами или поведением.\\n\\nКак это работает?\\nHOC — это функция, которая принимает компонент и возвращает новый компонент. Внутри HOC можно реализовать общую логику, а затем передать данные через props в обернутый компонент. Например, если нужно добавить логику авторизации к нескольким страницам, можно создать HOC \`withAuth\`, который проверяет, авторизован ли пользователь, и либо рендерит компонент, либо перенаправляет на страницу входа.\\n\\nГде применяется?\\nHOC часто используется для:\\n- Добавления логики подписки на данные (например, с Redux или Context)\\n- Обработки ошибок или загрузки\\n- Управления доступом (авторизация)\\n- Логирования или аналитики\\n\\nОднако с появлением React Hooks (например, \`useEffect\`, \`useContext\`) HOC стал менее популярен, так как хуки позволяют переиспользовать логику без создания новых компонентов. Тем не менее, HOC остается полезным в легаси-коде или при работе с библиотеками, которые его требуют.\\n\\nВывод\\nHOC — это мощный инструмент для переиспользования логики в React, особенно когда нужно добавить одинаковое поведение к нескольким компонентам без дублирования кода. Его стоит применять в проектах, где еще не используются хуки, или при интеграции с библиотеками, которые ожидают HOC-обертки.","function withAuth(WrappedComponent) {\\n  return function AuthenticatedComponent(props) {\\n    const isAuthenticated = checkAuth(); // общая логика\\n    if (!isAuthenticated) {\\n      return <Redirect to=\\"/login\\" />;\\n    }\\n    return <WrappedComponent {...props} />;\\n  };\\n}\\n\\nconst ProtectedPage = withAuth(MyPage);"],[2598,"Пользователь или код вызывает dispatch(action). Redux передаёт action и текущий state в reducer. Reducer возвращает новый state. Store сохраняет его и уведомляет подписчиков. React перерисовывает компоненты, подключённые через connect или useSelector.","Жизненный цикл Redux\\nRedux — это предсказуемый контейнер состояния для JavaScript-приложений. Весь цикл начинается с вызова функции dispatch с объектом action, который содержит тип и опциональные данные. Далее Redux передаёт текущее состояние и action в корневой reducer, который решает, как изменить состояние. Reducer должен быть чистой функцией: он не изменяет исходный state, а возвращает новый объект. После этого store обновляет своё внутреннее состояние и вызывает всех подписчиков, зарегистрированных через subscribe. В React-приложении подписка осуществляется через react-redux: connect или хуки useSelector/useDispatch. Когда store уведомляет об изменении, React запускает ререндер компонентов, которые зависят от изменившейся части состояния.\\n\\nПример кода\\n\\nВывод\\nПонимание этого цикла необходимо для отладки, оптимизации производительности и правильного проектирования архитектуры Redux-приложений. Используйте этот подход, когда требуется централизованное управление состоянием с предсказуемыми изменениями.","// action creator\\nconst increment = () => ({ type: 'INCREMENT' });\\n\\n// reducer\\nconst counter = (state = 0, action) => {\\n  switch (action.type) {\\n    case 'INCREMENT':\\n      return state + 1;\\n    default:\\n      return state;\\n  }\\n};\\n\\n// store\\nconst store = createStore(counter);\\n\\n// dispatch\\nstore.dispatch(increment());\\nconsole.log(store.getState()); // 1"],[2599,"В React для загрузки данных с сервера используется хук useEffect с пустым массивом зависимостей. Это аналог метода componentDidMount в классовых компонентах. Хук выполняется после первого рендера компонента, что гарантирует наличие DOM-элементов. Такой подход предотвращает лишние запросы при каждом обновлении состояния.","Загрузка данных в React\\nВ React для выполнения побочных эффектов, таких как загрузка данных с сервера, используется хук \`useEffect\`. Этот хук вызывается после того, как компонент был отрендерен и добавлен в DOM. Это гарантирует, что у нас есть доступ к DOM-элементам и что запрос не блокирует первоначальный рендер.\\n\\nПравильное использование useEffect\\nЧтобы загрузить данные только один раз при монтировании компонента, необходимо передать пустой массив зависимостей вторым аргументом в \`useEffect\`. Это эквивалентно методу \`componentDidMount\` в классовых компонентах.\\n\\nВажные аспекты\\n\\n- Не используйте асинхронную функцию напрямую в \`useEffect\`, лучше объявить её внутри и вызвать\\n- Всегда обрабатывайте ошибки и состояния загрузки\\n- Для отмены запросов при размонтировании компонента используйте функцию очистки в \`useEffect\`\\n\\nВывод: Использование \`useEffect\` с пустым массивом зависимостей является стандартным и рекомендуемым способом загрузки данных при монтировании компонента в React. Это обеспечивает предсказуемое поведение и предотвращает утечки памяти.","import React, { useState, useEffect } from 'react';\\n\\nfunction UserList() {\\n  const [users, setUsers] = useState([]);\\n  const [loading, setLoading] = useState(true);\\n\\n  useEffect(() => {\\n    fetch('/api/users')\\n      .then(response => response.json())\\n      .then(data => {\\n        setUsers(data);\\n        setLoading(false);\\n      })\\n      .catch(error => console.error('Error:', error));\\n  }, []); // Пустой массив зависимостей\\n\\n  if (loading) return <div>Loading...</div>;\\n\\n  return (\\n    <ul>\\n      {users.map(user => (\\n        <li key={user.id}>{user.name}</li>\\n      ))}\\n    </ul>\\n  );\\n}"],[2600,"React Router v6 представил несколько значительных изменений. Компонент Switch заменен на Routes, а Route теперь использует element вместо component. Порядок маршрутов больше не важен, так как v6 использует алгоритм ранжирования. Хук useHistory заменен на useNavigate. Также в v6 появилась поддержка вложенных маршрутов и относительных ссылок.","Основные различия между React Router v5 и v6\\nReact Router v6 представляет собой значительное обновление, которое упрощает API и делает маршрутизацию более интуитивной. Главное изменение — замена компонента Switch на Routes, который автоматически выбирает наиболее подходящий маршрут, а не первый совпадающий.\\n\\nИзменения в компонентах маршрутов\\nВ v5 использовался компонент Switch для группировки Route, и порядок маршрутов имел значение. В v6 Switch заменен на Routes, а Route теперь принимает prop element вместо component или render. Это позволяет передавать компоненты напрямую:\\n\\nНавигация и хуки\\nВ v5 для программной навигации использовался хук useHistory. В v6 он заменен на useNavigate, который предоставляет более гибкий API:\\n\\nВложенные маршруты и относительные ссылки\\nReact Router v6 значительно улучшил поддержку вложенных маршрутов. Теперь можно определять дочерние маршруты прямо внутри родительского компонента, используя Outlet:\\n\\nВывод\\nReact Router v6 предлагает более чистый и предсказуемый API, упрощает работу с вложенными маршрутами и улучшает производительность. При миграции с v5 на v6 стоит обратить внимание на замену Switch на Routes, обновление хуков навигации и рефакторинг вложенных маршрутов с использованием Outlet.","// React Router v5\\n\\n\\n// React Router v6\\n\\n  } />\\n  } />\\n\\n// React Router v5\\nconst history = useHistory();\\nhistory.push('/home');\\n\\n// React Router v6\\nconst navigate = useNavigate();\\nnavigate('/home');\\nnavigate(-1); // для перехода назад\\n\\nfunction App() {\\n  return (\\n    \\n      }>\\n        } />\\n        } />\\n      \\n    \\n  );\\n}\\n\\nfunction Dashboard() {\\n  return (\\n    \\n      Dashboard\\n       {/* Здесь будут отображаться дочерние маршруты */}\\n    \\n  );\\n}"]]`);export{e as default};